-- ============================================================================
-- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D — card-present provider ledger (server side).
-- Contract: API_CONTRACT §4.55 (+ §4.14 / §4.30b / §4.30c / §4.33 / §4.35 item 4
-- card notes), DOMAIN_MODEL §8.4–§8.7, DEPLOYMENT §18.2, T-023; DECISIONS
-- D-051..D-058 as merged at 0caf3f5a (M2), plus D-059 (local correction C1) and
-- D-060 (local correction C2). Execution packet:
-- docs/BIZBOT_PAYMENTS_ZCREDIT_PILOT_001D_EXECUTION.md.
--
-- Dark by default: this migration inserts no binding, revision, credential,
-- attempt, payment or order. With no app.card_payments_pilot_revisions row the
-- pilot is OFF; with no app.payment_terminals row every device keeps today's
-- behaviour. No credential, terminal number, PIN-pad identifier, device UUID or
-- provider payload appears here. The pilot scope below is the Maps Burger tenant
-- named by D-051 point 1 and already pinned in-repo by 20261017004438.
--
-- Contents:
--   1. Text policy helpers (UCD 15.1.0 closed policy, M4/M5), key formatter
--      (closed set, M7), event-detail allowlist, advisory-lock helpers.
--   2. The five private tables (app schema; forced RLS; deny_client; no grants).
--   3. Internal helpers (caller binding, proof, derivation, envelope, predicates,
--      event writer).
--   4. Integrity triggers.
--   5. Caller-authority RPCs (card_attempt_context, owner_card_attempts).
--   6. Service-only RPCs (claim, adapter read, finish, release mark, recording
--      result, free_order).
--   7. Internal sync_push guards (card_claim_guard, card_recording_resume_guard).
--   8. Operator-only RPCs (pilot revision, terminal binding, orphan / TEST
--      closure, incident hold, TEST purge).
--   9. Re-created live functions: app.sync_push (exactly seven changes),
--      app.pin_session_capabilities, app.pos_order_snapshots, app.audit_category,
--      app.audit_action_has_detail, app.audit_safe_detail, app.owner_audit_events.
--  10. Grants (explicit revoke from every app role, then one grant per layer).
-- app.record_payment, app.close_shift and app.reconcile_shift are NOT changed.
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 1. Text policy, key formatter, event-detail allowlist, advisory locks.
-- ----------------------------------------------------------------------------
-- M4: the canonical stored form. NFKC, then trim exactly the 17 Space_Separator
-- code points of Unicode 15.1 at both ends; empty after trimming = absent.
create function app.card_text_canonical(p_value text)
  returns text
  language plpgsql
  immutable
  strict
  parallel safe
  set search_path = ''
as $$
declare
  c_trim constant text := U&'\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\202F\205F\3000';
begin
  return nullif(btrim(normalize(p_value, nfkc), c_trim), '');
end;
$$;

-- M4's absent test at linear cost: NULL, or nothing but the 17 Space_Separator
-- code points. It equals card_text_canonical(p_value) IS NULL: NFKC maps each
-- Space_Separator to Space_Separators only and every other code point to a
-- sequence holding a non-Space_Separator (checked over every code point of
-- UCD 15.1; execution packet §4.5).
create function app.card_text_absent(p_value text)
  returns boolean
  language sql
  immutable
  parallel safe
  set search_path = ''
as $$
  select p_value is null
      or btrim(p_value, U&'\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\202F\205F\3000') = '';
$$;

-- M5 / D-058 point 10, closed by D-059 point 4: the field-specific no-card-data
-- rule. Returns NULL when the value passes, else the failed rule token (charset |
-- length | control_character | digit_run | masked_pattern). The class constants
-- are derived from three pinned Unicode Character Database 15.1.0 files:
-- UnicodeData.txt (sha256 2fc713e6a31a87c4850a37fe2caffa4218180fadb5de86b43a143ddb4581fb86),
-- DerivedCoreProperties.txt (sha256 f55d0db69123431a7317868725b1fcbf1eab6b265d756d1bd7f0f6d9f9ee108b)
-- and extracted/DerivedNumericType.txt
-- (sha256 0f22ca7770c836211e2b5390c6c9c3b5faae8e60cd8a59f244a43f9f5421cddd):
-- printable allowlist 710 ranges = L* M* N* P* S* Zs + U+061C U+200C U+200D
-- U+200E U+200F; refused controls 26 ranges = Cc Zl Zp, every other Cf and every
-- other Default_Ignorable_Code_Point (Hangul fillers, variation selectors, the
-- grapheme joiner ...); refused non-digit numerics 162 ranges / 1 114 code points
-- (Numeric_Type=Numeric); digit-like 83 ranges / 808 code points (Numeric_Type
-- Decimal or Digit); Co / Cs / Cn outside the allowlist; 39 explicit mask code
-- points, every code point named BULLET among them. Recipe: execution packet §4.5.
create function app.card_safe_text_failure(p_value text, p_field text)
  returns text
  language plpgsql
  immutable
  parallel safe
  set search_path = ''
