43\U0001E94B\U0001E950-\U0001E959\U0001EE00-\U0001EE03\U0001EE05-\U0001EE1F\U0001EE21-\U0001EE22\U0001EE24\U0001EE27\U0001EE29-\U0001EE32\U0001EE34-\U0001EE37\U0001EE39\U0001EE3B\U0001EE42\U0001EE47\U0001EE49\U0001EE4B\U0001EE4D-\U0001EE4F\U0001EE51-\U0001EE52\U0001EE54\U0001EE57\U0001EE59\U0001EE5B\U0001EE5D\U0001EE5F\U0001EE61-\U0001EE62\U0001EE64\U0001EE67-\U0001EE6A\U0001EE6C-\U0001EE72\U0001EE74-\U0001EE77\U0001EE79-\U0001EE7C\U0001EE7E\U0001EE80-\U0001EE89\U0001EE8B-\U0001EE9B\U0001EEA1-\U0001EEA3\U0001EEA5-\U0001EEA9\U0001EEAB-\U0001EEBB\U0001F100-\U0001F10A\U0001FBF0-\U0001FBF9\U00020000-\U0002A6DF\U0002A700-\U0002B739\U0002B740-\U0002B81D\U0002B820-\U0002CEA1\U0002CEB0-\U0002EBE0\U0002EBF0-\U0002EE5D\U0002F800-\U0002FA1D\U00030000-\U0003134A\U00031350-\U000323AF]';
  c_trim constant text := U&'\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\202F\205F\3000';
  v_canonical text;
  v_charset   text;
  v_min       integer := 1;
  v_max       integer;
  v_free      boolean := false;
begin
  if p_value is null then
    return null;
  end if;
  case p_field
    when 'provider_reference', 'deposit_id' then
      v_charset := '^[A-Za-z0-9-]+$'; v_max := 32;
    when 'approval_number', 'voucher_number' then
      v_charset := '^[A-Za-z0-9]+$'; v_max := 16;
    when 'card_last4' then
      v_charset := '^[0-9]+$'; v_min := 4; v_max := 4;
    when 'card_brand_code', 'approval_type', 'pan_entry_mode', 'payment_method_code', 'provider_status_code' then
      v_charset := '^[A-Za-z0-9_-]+$'; v_max := 16;
    when 'provider_query_key', 'provider_duplicate_key' then
      v_charset := '^[a-p]+$'; v_max := 64;
    when 'terminal_ref', 'credential_ref' then
      v_charset := '^[a-z0-9_-]+$'; v_max := 64;
    when 'confirmation_reference', 'resolution_reference', 'incident_hold_reference',
         'operator_reference', 'actor_reference' then
      v_charset := '^[A-Za-z0-9._:/-]+$'; v_max := 64;
    when 'order_freed_note', 'reason' then
      v_free := true; v_max := 200;
    else
      return 'charset';
  end case;
  -- (1) Raw: a refused control or Default_Ignorable code point (never stripped into
  -- an accepted value), the printable allowlist, and every non-digit numeric
  -- character, which is refused and never treated as a separator.
  if p_value ~ c_control then
    return 'control_character';
  end if;
  if p_value !~ c_allowed_only or p_value ~ c_numeric_other then
    return 'charset';
  end if;
  -- (2) A linear bound before NFKC, whose mark reordering is quadratic: the largest
  -- canonical decomposition in UCD 15.1 is 4 code points (U+1F82), so a value
  -- whose trimmed raw form is longer than 4 x the maximum has a canonical form
  -- longer than the maximum and is refused either way; for such a value this
  -- answers 'length' where the canonical checks below might have named
  -- 'control_character' or 'charset' first (nothing is stored in any case).
  if char_length(btrim(p_value, c_trim)) > 4 * v_max then
    return 'length';
  end if;
  v_canonical := app.card_text_canonical(p_value);
  if v_canonical is null then
    return 'length';
  end if;
  if v_canonical ~ c_control then
    return 'control_character';
  end if;
  if v_canonical !~ c_allowed_only or v_canonical ~ c_numeric_other
     or (not v_free and v_canonical !~ v_charset) then
    return 'charset';
  end if;
  -- (3) The canonical length range; a human reason or note also needs at least
  -- one visible letter or digit (an invisible-, mark- or symbol-only value fails).
  if char_length(v_canonical) < v_min or char_length(v_canonical) > v_max
     or (v_free and v_canonical !~ c_visible) then
    return 'length';
  end if;
  -- (4) 12 or more digit-like characters (Numeric_Type Decimal or Digit: any
  -- script, fullwidth, mathematical, superscript, circled, dingbat ...) anywhere in
  -- the field, raw or canonical: nothing between them resets the count.
  if char_length(regexp_replace(p_value, c_not_digit, '', 'g')) >= 12
     or char_length(regexp_replace(v_canonical, c_not_digit, '', 'g')) >= 12 then
    return 'digit_run';
  end if;
  -- (5) A masked card pattern once separators - anything but a non-modifier
  -- letter, a digit-like character or a mask - are ignored, raw and canonical.
  if regexp_replace(p_value, c_mask_strip, '', 'g') ~ c_masked
     or regexp_replace(v_canonical, c_mask_strip, '', 'g') ~ c_masked then
    return 'masked_pattern';
  end if;
  return null;
end;
$$;

-- The contract helper (API §4.55.10): IMMUTABLE, SECURITY INVOKER, reads no
-- table. NULL in = NULL out (a NULL column passes its CHECK; writers treat an
-- absent value before calling it).
create function app.card_safe_text_ok(p_value text, p_field text)
  returns boolean
  language sql
  immutable
  parallel safe
  set search_path = ''
as $$
  select case when p_value is null then null
              else app.card_safe_text_failure(p_value, p_field) is null end;
$$;

-- D-058 point 2: SHA-256 of the domain-separated full identity tuple
-- ('card-status-key/v1' | 'card-duplicate-key/v1'), canonical lowercase text.
create function app.card_identity_digest(p_purpose text, p_organization_id uuid, p_device_id uuid, p_local_operation_id text)
  returns bytea
  language sql
  immutable
  parallel safe
  set search_path = ''
as $$
  select case when p_purpose in ('card-status-key/v1', 'card-duplicate-key/v1')
              then sha256(convert_to(p_purpose || '|' || p_organization_id::text || '|' || p_device_id::text
                                     || '|' || p_local_operation_id, 'UTF8')) end;
$$;

-- M7: the closed formatter candidate set. Each key = the first N hex nibbles of
-- its digest, nibble 0..15 mapped to the letters a..p. The alphabet {a..p} holds
-- no decimal digit of any script and no mask code point, so no output can trip
-- the digit-run or masked-pattern rule. An unknown version yields NULL.
create function app.card_provider_key(p_digest bytea, p_version text)
  returns text
  language sql
  immutable
  parallel safe
  set search_path = ''
as $$
  select case
    when p_digest is null or octet_length(p_digest) <> 32 then null
    when p_version = 'alpha16-l20-v1' then translate(left(encode(p_digest, 'hex'), 20), '0123456789abcdef', 'abcdefghijklmnop')
    when p_version = 'alpha16-l24-v1' then translate(left(encode(p_digest, 'hex'), 24), '0123456789abcdef', 'abcdefghijklmnop')
    when p_version = 'alpha16-l32-v1' then translate(left(encode(p_digest, 'hex'), 32), '0123456789abcdef', 'abcdefghijklmnop')
  end;
$$;

-- DOMAIN §8.6: private-event detail = allowlisted scalar keys per action.
create function app.card_event_detail_ok(p_action text, p_detail jsonb)
  returns boolean
  language sql
  immutable
  parallel safe
  set search_path = ''
as $$
  select p_detail is not null
     and jsonb_typeof(p_detail) = 'object'
     and not exists (select 1 from jsonb_each(p_detail) e
                      where jsonb_typeof(e.value) not in ('string', 'number', 'boolean', 'null'))
     and not exists (
       select 1 from jsonb_object_keys(p_detail) k
        where k <> all (case p_action
          when 'operator.card_payments_pilot_updated' then
            array['enabled', 'mode', 'window_until', 'max_test_amount_minor', 'max_live_amount_minor']
          when 'operator.payment_terminal_updated' then
            array['binding_mode', 'prior_lifecycle', 'new_lifecycle', 'starts_admitted', 'reason_code']
          when 'operator.card_attempt_orphan_resolved' then array['resolution', 'attempt_state']
          when 'operator.card_attempt_test_closed' then array['resolution', 'attempt_state']
          when 'operator.card_test_attempt_hold_updated' then array['target_kind', 'hold']
          when 'operator.card_test_attempts_purged' then
            array['attempts_purged', 'events_purged', 'attempts_deferred', 'events_deferred', 'devices_locked',
                  'cutoff']
          when 'test.card_attempt_denied' then array['rpc', 'denied_reason']
          when 'security.card_credential_mismatch' then array['check', 'source']
          when 'security.card_finish_scope_mismatch' then
            array['organization_id', 'device_id', 'local_operation_id', 'mode', 'amount_minor', 'currency_code']
          when 'security.card_resolution_contradicted' then array['source', 'outcome']
          when 'security.card_provider_field_dropped' then array['field', 'rule', 'source']
          else array[]::text[] end))
     and (p_action <> 'operator.payment_terminal_updated'
          or (p_detail ?& array['binding_mode', 'prior_lifecycle', 'new_lifecycle', 'starts_admitted', 'reason_code']
              and p_detail ->> 'binding_mode' in ('test', 'live')
              and (p_detail -> 'prior_lifecycle' = 'null'::jsonb
                   or p_detail ->> 'prior_lifecycle' in ('configured', 'enabled', 'draining', 'retired'))
              and p_detail ->> 'new_lifecycle' in ('configured', 'enabled', 'draining', 'retired')
              and jsonb_typeof(p_detail -> 'starts_admitted') = 'boolean'
              and p_detail ->> 'reason_code' in ('test_setup', 'test_end', 'live_activation', 'incident',
                                                 'rotation', 'end_of_pilot')))
     and (p_action <> 'security.card_provider_field_dropped'
          or (p_detail ?& array['field', 'rule', 'source']
              and p_detail ->> 'field' in ('provider_reference', 'approval_number', 'voucher_number', 'deposit_id',
                                           'card_last4', 'card_brand_code', 'approval_type', 'pan_entry_mode',
                                           'payment_method_code', 'provider_status_code', 'provider_return_code',
                                           'provider_saved_at', 'error_flag', 'phone_authorization', 'tip_amount',
                                           'provider_amount', 'provider_currency')
              and p_detail ->> 'rule' in ('charset', 'length', 'control_character', 'digit_run',
                                          'masked_pattern', 'format')
              and p_detail ->> 'source' in ('commit', 'lookup', 'release')))
     and (p_action <> 'test.card_recording_refused' or p_detail = '{}'::jsonb);
$$;

-- D-058 points 5 and 6: transaction-scoped admission locks. A NULL key part is
-- a programming error (pg_advisory_xact_lock is STRICT and would silently not
-- lock), so it raises.
create function app.card_identity_lock(p_organization_id uuid, p_device_id uuid, p_local_operation_id text)
  returns void
  language plpgsql
  volatile
  set search_path = ''
as $$
begin
  if p_organization_id is null or p_device_id is null or p_local_operation_id is null then
    raise exception 'card_identity_lock: identity is incomplete' using errcode = '22004';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'card-identity/v1:' || p_organization_id::text || ':' || p_device_id::text || ':' || p_local_operation_id, 0));
end;
$$;

create function app.card_terminal_lock(p_organization_id uuid, p_device_id uuid)
  returns void
  language plpgsql
  volatile
  set search_path = ''
as $$
begin
  if p_organization_id is null or p_device_id is null then
    raise exception 'card_terminal_lock: scope is incomplete' using errcode = '22004';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'card-terminal/v1:' || p_organization_id::text || ':' || p_device_id::text, 0));
end;
$$;


-- ----------------------------------------------------------------------------
-- 2. Private tables (DOMAIN_MODEL §8.4–§8.7). Never client-readable, never a
--    sync_pull entity, written only by the §4.55 SECURITY DEFINER bodies.
-- ----------------------------------------------------------------------------
-- 2.1 Operator revision store (§8.7). Append-only; the latest row is current;
--     no row = OFF. Pinned to the pilot scope by CHECK.
create table app.card_payments_pilot_revisions (
  revision              bigint generated always as identity primary key,
  organization_id       uuid not null,
  restaurant_id         uuid not null,
  branch_id             uuid not null,
  enabled               boolean not null default false,
  mode                  text not null,
  window_until          timestamptz not null,
  max_test_amount_minor bigint,
  max_live_amount_minor bigint,
  reason                text not null,
  operator_reference    text not null,
  actor_app_user_id     uuid not null,
  executor_principal    text not null,
  recorded_at           timestamptz not null default clock_timestamp(),
  constraint card_pilot_revisions_pilot_scope check (
    organization_id = '20605c2b-3145-4803-a990-bbec3d9c1096'::uuid
    and restaurant_id = 'de3bbc64-edad-4ff4-bccd-c2ef217c1d56'::uuid
    and branch_id = '2847c0be-3e31-45a5-957c-508729f1971e'::uuid),
  constraint card_pilot_revisions_mode check (mode in ('test', 'live')),
  constraint card_pilot_revisions_test_cap check (
    max_test_amount_minor is null or max_test_amount_minor between 1 and 99999999999),
  constraint card_pilot_revisions_live_cap check (
    max_live_amount_minor is null or max_live_amount_minor between 1 and 99999999999),
  constraint card_pilot_revisions_reason check (
    app.card_safe_text_ok(reason, 'reason') and reason = app.card_text_canonical(reason)),
  constraint card_pilot_revisions_operator_reference check (
    app.card_safe_text_ok(operator_reference, 'operator_reference')
    and operator_reference = app.card_text_canonical(operator_reference)),
  constraint card_pilot_revisions_executor check (btrim(executor_principal) <> ''),
  foreign key (organization_id, restaurant_id, branch_id)
    references public.branches (organization_id, restaurant_id, id) on delete restrict
);

-- 2.2 Exact-device terminal binding (§8.5). Opaque references only.
create table app.payment_terminals (
  id                   uuid primary key default gen_random_uuid(),
  organization_id      uuid not null,
  restaurant_id        uuid not null,
  branch_id            uuid not null,
  device_id            uuid not null,
  terminal_ref         text not null,
  credential_ref       text not null,
  mode                 text not null,
  lifecycle            text not null default 'configured',
  lifecycle_changed_at timestamptz not null default clock_timestamp(),
  created_at           timestamptz not null default clock_timestamp(),
  updated_at           timestamptz not null default clock_timestamp(),
  deleted_at           timestamptz,
  constraint payment_terminals_mode check (mode in ('test', 'live')),
  constraint payment_terminals_lifecycle check (lifecycle in ('configured', 'enabled', 'draining', 'retired')),
  constraint payment_terminals_terminal_ref check (
    terminal_ref ~ '^[a-z0-9_-]{1,64}$' and app.card_safe_text_ok(terminal_ref, 'terminal_ref')
    and terminal_ref = app.card_text_canonical(terminal_ref)),
  constraint payment_terminals_credential_ref check (
    credential_ref ~ '^[a-z0-9_-]{1,64}$' and app.card_safe_text_ok(credential_ref, 'credential_ref')
    and credential_ref = app.card_text_canonical(credential_ref)),
  constraint payment_terminals_refs_distinct check (terminal_ref <> credential_ref),
  foreign key (organization_id, restaurant_id, branch_id)
    references public.branches (organization_id, restaurant_id, id) on delete restrict,
  foreign key (organization_id, restaurant_id, branch_id, device_id)
    references public.devices (organization_id, restaurant_id, branch_id, id) on delete restrict
);
create unique index payment_terminals_one_current_per_device
  on app.payment_terminals (organization_id, device_id)
  where deleted_at is null and lifecycle <> 'retired';
create unique index payment_terminals_one_admitting_per_org
  on app.payment_terminals (organization_id)
  where lifecycle in ('enabled', 'draining');
create index payment_terminals_credential_ref_idx on app.payment_terminals (credential_ref);

-- 2.3 The provider-attempt ledger (§8.4).
create table app.card_provider_attempts (
  id                               uuid primary key default gen_random_uuid(),
  organization_id                  uuid not null,
  restaurant_id                    uuid not null,
  branch_id                        uuid not null,
  device_id                        uuid not null,
  local_operation_id               text not null,
  order_id                         uuid,
  shift_id                         uuid,
  cash_drawer_session_id           uuid,
  initiated_by_employee_profile_id uuid not null,
  initiated_by_membership_id       uuid not null,
  mode                             text not null,
  state                            text not null default 'sent',
  amount_minor                     bigint not null,
  currency_code                    text not null,
  expected_revision                integer,
  terminal_ref                     text not null,
  credential_ref                   text not null,
  provider_status_digest           bytea not null,
  provider_duplicate_digest        bytea not null,
  provider_key_format_version      text not null,
  provider_query_key               text not null,
  provider_duplicate_key           text not null,
  provider_reference               text,
  approval_number                  text,
  voucher_number                   text,
  card_last4                       text,
  card_brand_code                  text,
  approval_type                    text,
  provider_return_code             integer,
  provider_return_class            text,
  provider_anomaly_code            text,
  charge_may_exist                 boolean not null default false,
  pan_entry_mode                   text,
  payment_method_code              text,
  provider_status_code             text,
  deposit_id                       text,
  provider_saved_at                timestamptz,
  provider_approved_at             timestamptz,
  refusal_code                     text,
  recording_refused_at             timestamptz,
  recording_resume_count           integer not null default 0,
  recording_refusal_history        jsonb not null default '[]'::jsonb,
  recording_resume_history         jsonb not null default '[]'::jsonb,
  release_requested_at             timestamptz,
  released_at                      timestamptz,
  last_lookup_at                   timestamptz,
  auto_poll_count                  integer not null default 0,
  order_freed_at                   timestamptz,
  order_freed_reason               text,
  confirmation_source              text,
  confirmation_reference           text,
  order_freed_note                 text,
  resolution                       text,
  resolution_reference             text,
  resolved_at                      timestamptz,
  retention_until                  timestamptz,
  incident_hold_at                 timestamptz,
  incident_hold_reference          text,
  start_deadline_at                timestamptz not null,
  started_at                       timestamptz not null default clock_timestamp(),
  finished_at                      timestamptz,
  created_at                       timestamptz not null default clock_timestamp(),
  updated_at                       timestamptz not null default clock_timestamp(),
  -- D-059 point 1: the durable claim signal of the snapshot watermark - stamped
  -- by the guards at the claim and advanced only by a state change, a manager free
  -- or a resolution (never by a poll counter, lookup stamp, mark, Resume counter,
  -- hold or provider field; a poll or lookup whose result changes the state does).
  claim_signal_at                  timestamptz not null default clock_timestamp(),
  constraint card_attempts_identity unique (organization_id, device_id, local_operation_id),
  constraint card_attempts_status_digest_key unique (provider_status_digest),
  constraint card_attempts_duplicate_digest_key unique (provider_duplicate_digest),
  constraint card_attempts_query_key_key unique (provider_query_key),
  constraint card_attempts_duplicate_key_key unique (provider_duplicate_key),
  constraint card_attempts_local_operation_id check (
    local_operation_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'),
  constraint card_attempts_mode check (mode in ('test', 'live')),
  constraint card_attempts_state check (state in ('sent', 'approved', 'declined', 'unknown', 'released')),
  constraint card_attempts_amount check (amount_minor between 1 and 99999999999),
  constraint card_attempts_currency check (currency_code ~ '^[A-Z]{3}$'),
  constraint card_attempts_test_shape check (
    mode <> 'test' or (order_id is null and shift_id is null and cash_drawer_session_id is null
                       and expected_revision is null and retention_until is not null
                       and provider_reference is null and approval_number is null and voucher_number is null
                       and card_last4 is null and card_brand_code is null and pan_entry_mode is null
                       and payment_method_code is null and deposit_id is null)),
  constraint card_attempts_live_shape check (
    mode <> 'live' or (order_id is not null and shift_id is not null and cash_drawer_session_id is not null
                       and expected_revision is not null and retention_until is null)),
  constraint card_attempts_digests check (
    provider_status_digest = app.card_identity_digest('card-status-key/v1', organization_id, device_id, local_operation_id)
    and provider_duplicate_digest = app.card_identity_digest('card-duplicate-key/v1', organization_id, device_id, local_operation_id)),
  constraint card_attempts_key_version check (
    provider_key_format_version in ('alpha16-l20-v1', 'alpha16-l24-v1', 'alpha16-l32-v1')),
  constraint card_attempts_keys check (
    provider_query_key = app.card_provider_key(provider_status_digest, provider_key_format_version)
    and provider_duplicate_key = app.card_provider_key(provider_duplicate_digest, provider_key_format_version)
    and provider_query_key ~ '^[a-p]{20,32}$' and provider_duplicate_key ~ '^[a-p]{20,32}$'
    and app.card_safe_text_ok(provider_query_key, 'provider_query_key')
    and app.card_safe_text_ok(provider_duplicate_key, 'provider_duplicate_key')),
  constraint card_attempts_refs check (
    terminal_ref ~ '^[a-z0-9_-]{1,64}$' and credential_ref ~ '^[a-z0-9_-]{1,64}$'
    and app.card_safe_text_ok(terminal_ref, 'terminal_ref') and app.card_safe_text_ok(credential_ref, 'credential_ref')),
  constraint card_attempts_provider_fields check (
    (provider_reference is null or (app.card_safe_text_ok(provider_reference, 'provider_reference')
                                    and provider_reference = app.card_text_canonical(provider_reference)))
    and (approval_number is null or (app.card_safe_text_ok(approval_number, 'approval_number')
                                     and approval_number = app.card_text_canonical(approval_number)))
    and (voucher_number is null or (app.card_safe_text_ok(voucher_number, 'voucher_number')
                                    and voucher_number = app.card_text_canonical(voucher_number)))
    and (deposit_id is null or (app.card_safe_text_ok(deposit_id, 'deposit_id')
                                and deposit_id = app.card_text_canonical(deposit_id)))
    and (card_last4 is null or (card_last4 ~ '^[0-9]{4}$' and app.card_safe_text_ok(card_last4, 'card_last4')))
    and (card_brand_code is null or (app.card_safe_text_ok(card_brand_code, 'card_brand_code')
                                     and card_brand_code = app.card_text_canonical(card_brand_code)))
    and (approval_type is null or (app.card_safe_text_ok(approval_type, 'approval_type')
                                   and approval_type = app.card_text_canonical(approval_type)))
    and (pan_entry_mode is null or (app.card_safe_text_ok(pan_entry_mode, 'pan_entry_mode')
                                    and pan_entry_mode = app.card_text_canonical(pan_entry_mode)))
    and (payment_method_code is null or (app.card_safe_text_ok(payment_method_code, 'payment_method_code')
                                         and payment_method_code = app.card_text_canonical(payment_method_code)))
    and (provider_status_code is null or (app.card_safe_text_ok(provider_status_code, 'provider_status_code')
                                          and provider_status_code = app.card_text_canonical(provider_status_code)))
    and (provider_return_code is null or provider_return_code between -999999 and 999999)),
  constraint card_attempts_return_class check (
    provider_return_class is null or provider_return_class in
      ('approved', 'declined', 'error', 'pending', 'not_found', 'duplicate', 'phone_authorization', 'unclassified')),
  constraint card_attempts_anomaly check (
    provider_anomaly_code is null or provider_anomaly_code in
      ('amount_mismatch', 'currency_mismatch', 'preauthorization', 'partial_refund', 'refunded', 'voided', 'out_of_contract')),
  constraint card_attempts_charge_may_exist check (
    not charge_may_exist or (provider_anomaly_code is not null and state in ('unknown', 'released'))),
  constraint card_attempts_refusal_code check (
    refusal_code is null or refusal_code in
      ('release_failed', 'order_not_chargeable', 'conflict', 'precondition_failed', 'revoked_employee',
       'permission_denied', 'revoked_device', 'amount_mismatch', 'payment_in_progress', 'card_context_lost',
       'provider_recording_refused', 'nonrecoverable_refusal')),
  constraint card_attempts_resume check (
    recording_resume_count between 0 and 3
    and jsonb_typeof(recording_refusal_history) = 'array' and jsonb_array_length(recording_refusal_history) <= 3
    and jsonb_typeof(recording_resume_history) = 'array' and jsonb_array_length(recording_resume_history) <= 3),
  constraint card_attempts_poll check (auto_poll_count >= 0),
  constraint card_attempts_freed check (
    (order_freed_at is null and order_freed_reason is null)
    or (order_freed_at is not null and mode = 'live'
        and order_freed_reason in ('manager_confirmed', 'orphan_resolved'))),
  constraint card_attempts_confirmation check (
    (confirmation_source is null and confirmation_reference is null and order_freed_note is null)
    or (confirmation_source in ('provider_report', 'provider_back_office')
        and confirmation_reference is not null and order_freed_note is not null and order_freed_at is not null)),
  constraint card_attempts_confirmation_text check (
    (confirmation_reference is null or (app.card_safe_text_ok(confirmation_reference, 'confirmation_reference')
                                        and confirmation_reference = app.card_text_canonical(confirmation_reference)))
    and (order_freed_note is null or (app.card_safe_text_ok(order_freed_note, 'order_freed_note')
                                      and order_freed_note = app.card_text_canonical(order_freed_note)))),
  constraint card_attempts_resolution check (
    (resolution is null and resolution_reference is null and resolved_at is null)
    or (resolution is not null and resolution_reference is not null and resolved_at is not null
        and ((mode = 'live' and resolution in ('provider_voided', 'provider_refunded'))
             or (mode = 'test' and resolution = 'test_closed')))),
  constraint card_attempts_resolution_text check (
    resolution_reference is null or (app.card_safe_text_ok(resolution_reference, 'resolution_reference')
                                     and resolution_reference = app.card_text_canonical(resolution_reference))),
  constraint card_attempts_hold check (
    (incident_hold_at is null and incident_hold_reference is null)
    or (mode = 'test' and incident_hold_at is not null and incident_hold_reference is not null
        and app.card_safe_text_ok(incident_hold_reference, 'incident_hold_reference')
        and incident_hold_reference = app.card_text_canonical(incident_hold_reference))),
  foreign key (organization_id, restaurant_id, branch_id)
    references public.branches (organization_id, restaurant_id, id) on delete restrict,
  foreign key (organization_id, restaurant_id, branch_id, device_id)
    references public.devices (organization_id, restaurant_id, branch_id, id) on delete restrict,
  foreign key (organization_id, order_id) references public.orders (organization_id, id) on delete restrict,
  foreign key (organization_id, shift_id) references public.shifts (organization_id, id) on delete restrict,
  foreign key (organization_id, cash_drawer_session_id)
    references public.cash_drawer_sessions (organization_id, id) on delete restrict,
  foreign key (organization_id, initiated_by_employee_profile_id)
    references public.employee_profiles (organization_id, id) on delete restrict,
  foreign key (organization_id, initiated_by_membership_id)
    references public.memberships (organization_id, id) on delete restrict
);
-- The one claim per order of §4.55.3 (deliberately also covering recorded approvals).
create unique index card_attempts_one_claim_per_order
  on app.card_provider_attempts (organization_id, order_id)
  where order_freed_at is null and state in ('sent', 'unknown', 'released', 'approved');
create index card_attempts_order_idx on app.card_provider_attempts (organization_id, order_id);
create index card_attempts_shift_idx on app.card_provider_attempts (organization_id, shift_id);
create index card_attempts_branch_identity_idx
  on app.card_provider_attempts (organization_id, branch_id, local_operation_id);
create index card_attempts_retention_idx on app.card_provider_attempts (mode, retention_until);

-- 2.4 Private operator / security events (§8.6).
create table app.card_provider_private_events (
  id                        uuid primary key default gen_random_uuid(),
  organization_id           uuid not null,
  restaurant_id             uuid not null,
  branch_id                 uuid not null,
  attempt_row_id            uuid,
  mode                      text,
  action                    text not null,
  actor_kind                text not null,
  actor_reference           text not null,
  actor_app_user_id         uuid,
  executor_principal        text,
  actor_employee_profile_id uuid,
  device_id                 uuid,
  reason                    text,
  detail                    jsonb not null default '{}'::jsonb,
  retention_until           timestamptz,
  incident_hold_at          timestamptz,
  incident_hold_reference   text,
  created_at                timestamptz not null default clock_timestamp(),
  constraint card_events_action check (action in (
    'operator.card_payments_pilot_updated', 'operator.payment_terminal_updated',
    'operator.card_attempt_orphan_resolved', 'operator.card_attempt_test_closed',
    'operator.card_test_attempt_hold_updated', 'operator.card_test_attempts_purged',
    'test.card_attempt_denied', 'test.card_recording_refused',
    'security.card_credential_mismatch', 'security.card_finish_scope_mismatch',
    'security.card_resolution_contradicted', 'security.card_provider_field_dropped')),
  constraint card_events_actor_kind check (actor_kind in ('attested_owner_approver', 'employee', 'device', 'adapter')),
  constraint card_events_mode check (
    (action like 'operator.%' and mode is null and retention_until is null)
    or (action like 'test.%' and mode = 'test')
    or (action like 'security.%' and mode in ('test', 'live'))),
  constraint card_events_retention check (
    (mode = 'test') = (retention_until is not null)),
  -- D-059 point 3: a TEST event always names its device, so the purge can bound
  -- its deletes to the device set it locked (no unlockable TEST event exists).
  constraint card_events_test_device check (mode is distinct from 'test' or device_id is not null),
  constraint card_events_operator check (
    (action like 'operator.%') = (actor_kind = 'attested_owner_approver')
    and (action not like 'operator.%' or (actor_app_user_id is not null and executor_principal is not null
                                          and btrim(executor_principal) <> ''))
    and (action like 'operator.%' or (actor_app_user_id is null and executor_principal is null))),
  constraint card_events_adapter check (
    (action in ('security.card_finish_scope_mismatch', 'security.card_resolution_contradicted',
                'security.card_provider_field_dropped'))
    = (actor_kind = 'adapter' and actor_reference = 'card_adapter')),
  constraint card_events_actor_reference check (
    app.card_safe_text_ok(actor_reference, 'actor_reference') and actor_reference = app.card_text_canonical(actor_reference)
    and (actor_kind <> 'employee' or actor_reference = 'employee')
    and (actor_kind <> 'device' or actor_reference = 'device')),
  constraint card_events_reason check (
    reason is null or (app.card_safe_text_ok(reason, 'reason') and reason = app.card_text_canonical(reason))),
  constraint card_events_hold check (
    (incident_hold_at is null and incident_hold_reference is null)
    or (mode = 'test' and incident_hold_at is not null and incident_hold_reference is not null
        and app.card_safe_text_ok(incident_hold_reference, 'incident_hold_reference')
        and incident_hold_reference = app.card_text_canonical(incident_hold_reference))),
  constraint card_events_detail check (app.card_event_detail_ok(action, detail)),
  foreign key (organization_id, restaurant_id, branch_id)
    references public.branches (organization_id, restaurant_id, id) on delete restrict
);
create unique index card_events_one_test_recording_refusal
  on app.card_provider_private_events (attempt_row_id)
  where action = 'test.card_recording_refused';
create unique index card_events_one_field_drop
  on app.card_provider_private_events (attempt_row_id, (detail ->> 'field'), (detail ->> 'rule'))
  where action = 'security.card_provider_field_dropped';
create index card_events_attempt_idx on app.card_provider_private_events (attempt_row_id);
create index card_events_retention_idx on app.card_provider_private_events (mode, retention_until);

-- 2.5 Identity tombstones of purged TEST attempts (D-058 point 7).
create table app.card_attempt_identity_tombstones (
  organization_id             uuid not null,
  device_id                   uuid not null,
  local_operation_id          text not null,
  provider_status_digest      bytea not null,
  provider_duplicate_digest   bytea not null,
  provider_key_format_version text not null,
  provider_query_key          text not null,
  provider_duplicate_key      text not null,
  purged_at                   timestamptz not null default clock_timestamp(),
  primary key (organization_id, device_id, local_operation_id),
  constraint card_tombstones_status_digest_key unique (provider_status_digest),
  constraint card_tombstones_duplicate_digest_key unique (provider_duplicate_digest),
  constraint card_tombstones_query_key_key unique (provider_query_key),
  constraint card_tombstones_duplicate_key_key unique (provider_duplicate_key),
  constraint card_tombstones_local_operation_id check (
    local_operation_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'),
  constraint card_tombstones_key_version check (
    provider_key_format_version in ('alpha16-l20-v1', 'alpha16-l24-v1', 'alpha16-l32-v1')),
  constraint card_tombstones_digests check (
    provider_status_digest = app.card_identity_digest('card-status-key/v1', organization_id, device_id, local_operation_id)
    and provider_duplicate_digest = app.card_identity_digest('card-duplicate-key/v1', organization_id, device_id, local_operation_id)),
  constraint card_tombstones_keys check (
    provider_query_key = app.card_provider_key(provider_status_digest, provider_key_format_version)
    and provider_duplicate_key = app.card_provider_key(provider_duplicate_digest, provider_key_format_version))
);

-- Lockdown (the 20261017092726 pattern).
do $$
declare t text;
begin
  foreach t in array array['card_payments_pilot_revisions', 'payment_terminals', 'card_provider_attempts',
                           'card_provider_private_events', 'card_attempt_identity_tombstones'] loop
    execute format('alter table app.%I enable row level security', t);
    execute format('alter table app.%I force row level security', t);
    execute format('create policy deny_client on app.%I for all to authenticated using(false) with check(false)', t);
    execute format('revoke all on app.%I from public, anon, authenticated, service_role', t);
  end loop;
end $$;
revoke all on sequence app.card_payments_pilot_revisions_revision_seq from public, anon, authenticated, service_role;


-- ----------------------------------------------------------------------------
-- 3. Internal helpers (no grant to any app role; called by the §4.55 bodies).
-- ----------------------------------------------------------------------------
-- The latest operator revision (no row = OFF).
create function app.card_pilot_revision_current()
  returns app.card_payments_pilot_revisions
  language sql
  stable
  security definer
  set search_path = ''
as $$
  select r.* from app.card_payments_pilot_revisions r order by r.revision desc limit 1;
$$;

-- D-057 point 6: an attested owner approver = an active org_owner of the pilot
-- organization or an active restaurant_owner of the pilot restaurant. An
-- existence check, not authentication (the executor is recorded separately).
create function app.card_attested_approver_ok(p_actor_app_user_id uuid)
  returns boolean
  language sql
  stable
  security definer
  set search_path = ''
as $$
  select p_actor_app_user_id is not null and exists (
    select 1 from public.memberships m
     where m.app_user_id = p_actor_app_user_id
       and m.organization_id = '20605c2b-3145-4803-a990-bbec3d9c1096'::uuid
       and m.status = 'active' and m.deleted_at is null
       and ((m.role = 'org_owner'
             and (m.restaurant_id is null or m.restaurant_id = 'de3bbc64-edad-4ff4-bccd-c2ef217c1d56'::uuid)
             and (m.branch_id is null or m.branch_id = '2847c0be-3e31-45a5-957c-508729f1971e'::uuid))
         or (m.role = 'restaurant_owner'
             and m.restaurant_id = 'de3bbc64-edad-4ff4-bccd-c2ef217c1d56'::uuid
             and (m.branch_id is null or m.branch_id = '2847c0be-3e31-45a5-957c-508729f1971e'::uuid))));
$$;

-- §4.55.2: the SQL proof shared by the context proof (p_renew = true: the
-- app.renew_device_session path of the app.pos_web_order_context precedent) and
-- by every service-only body (p_renew = false: the same token proof and the same
-- identity-row locks — organizations / restaurants / branches FOR SHARE, devices /
-- device_pairings / device_sessions FOR NO KEY UPDATE, then memberships before
-- employee_profiles before pin_sessions FOR SHARE — without any write). The
-- caller-JWT gate is the context function's own. A refusal never discloses a
-- reason; permission_denied carries the proven scope for denial evidence only.
-- §4.55.2 / D-060 point 2: the original caller of a service-only request, as the
-- trusted adapter asserts it - the auth.users id the same request's caller-scoped
-- context proof returned as caller_auth_user_id. NULL = a valid caller outside an
-- ACTIVE platform support session; otherwise the refusal token: invalid_request
-- (no binding), invalid_session (no auth.users row, or a deleted or currently
-- banned one), permission_denied (the caller's app user - mapped through
-- app_users.auth_user_id exactly as app.current_app_user_id() maps auth.uid() -
-- holds a support session that the canonical predicate of
-- app.current_support_session() calls ACTIVE: status active, token consumed, not
-- past expires_at). It reads only the explicit identity: never auth.uid(),
-- session_user, request.jwt.claims or a GUC, and it sets none. An assertion of
-- the trusted service caller, not an end-user authentication.
create function app.card_caller_binding_denial(p_caller_auth_user_id uuid)
  returns text
  language sql
  stable
  security definer
  set search_path = ''
as $$
  select case
    when p_caller_auth_user_id is null then 'invalid_request'
    when not exists (select 1 from auth.users u
                      where u.id = p_caller_auth_user_id and u.deleted_at is null
                        and (u.banned_until is null or u.banned_until <= now())) then 'invalid_session'
    when exists (select 1 from public.platform_support_sessions s
                  where s.platform_admin_app_user_id = (select au.id from public.app_users au
                                                         where au.auth_user_id = p_caller_auth_user_id
                                                         limit 1)
                    and s.status = 'active'
                    and s.token_consumed_at is not null
                    and s.expires_at > now()) then 'permission_denied'
  end;
$$;

create function app.card_attempt_proof(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_renew boolean)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_invalid constant jsonb := jsonb_build_object('ok', false, 'error', 'invalid_session');
  v_proof jsonb;
  v_hash text;
  v_sid uuid;
  v_session public.device_sessions%rowtype;
  v_device public.devices%rowtype;
  v_pairing public.device_pairings%rowtype;
  v_branch public.branches%rowtype;
  v_restaurant public.restaurants%rowtype;
  v_organization public.organizations%rowtype;
  v_pin public.pin_sessions;
  v_locked_pin public.pin_sessions;
  v_employee public.employee_profiles;
  v_initial_employee public.employee_profiles;
  v_membership public.memberships;
  v_now timestamptz;
  v_count integer;
begin
  if p_pin_session_id is null or p_device_id is null or p_device_session_token is null
     or length(p_device_session_token) > 4096 or btrim(p_device_session_token) = '' then
    return v_invalid;
  end if;
  if p_renew then
    v_proof := app.renew_device_session(p_device_id, p_device_session_token);
    if (v_proof ->> 'ok') is distinct from 'true' then
      return v_invalid;
    end if;
  else
    v_hash := app.hash_provisioning_secret(btrim(p_device_session_token));
    select ds.* into v_session from public.device_sessions ds
      where ds.device_id = p_device_id and ds.session_token_ref = v_hash
      order by ds.started_at desc, ds.id desc limit 1;
    if not found then return v_invalid; end if;
    v_sid := v_session.id;
    select o.* into v_organization from public.organizations o
      where o.id = v_session.organization_id for share;
    if not found or v_organization.deleted_at is not null then return v_invalid; end if;
    select r.* into v_restaurant from public.restaurants r
      where r.id = v_session.restaurant_id and r.organization_id = v_organization.id for share;
    if not found or v_restaurant.deleted_at is not null then return v_invalid; end if;
    select b.* into v_branch from public.branches b
      where b.id = v_session.branch_id and b.organization_id = v_organization.id
        and b.restaurant_id = v_restaurant.id for share;
    if not found or v_branch.deleted_at is not null then return v_invalid; end if;
    select d.* into v_device from public.devices d
      where d.id = p_device_id and d.organization_id = v_organization.id
        and d.restaurant_id = v_restaurant.id and d.branch_id = v_branch.id
      for no key update;
    if not found then return v_invalid; end if;
    select dp.* into v_pairing from public.device_pairings dp
      where dp.id = v_session.device_pairing_id and dp.device_id = v_device.id
        and dp.organization_id = v_organization.id and dp.restaurant_id = v_restaurant.id
        and dp.branch_id = v_branch.id
      for no key update;
    if not found then return v_invalid; end if;
    select ds.* into v_session from public.device_sessions ds
      where ds.id = v_sid and ds.device_id = p_device_id and ds.session_token_ref = v_hash
        and ds.organization_id = v_organization.id and ds.restaurant_id = v_restaurant.id
        and ds.branch_id = v_branch.id and ds.device_pairing_id = v_pairing.id
      for no key update;
    if not found then return v_invalid; end if;
    if v_session.revoked_at is not null or v_pairing.revoked_at is not null or v_pairing.status = 'revoked'
       or not v_session.is_active or not v_device.is_active or v_device.deleted_at is not null
       or v_pairing.status <> 'active' or v_pairing.deleted_at is not null
       or (v_session.expires_at is not null and v_session.expires_at <= clock_timestamp()) then
      return v_invalid;
    end if;
    v_proof := jsonb_build_object('ok', true, 'entity', 'device_session',
      'device_session_id', v_sid, 'organization_id', v_organization.id,
      'restaurant_id', v_restaurant.id, 'branch_id', v_branch.id,
      'device_id', p_device_id, 'device_type', v_device.device_type,
      'session_expires_at', v_session.expires_at, 'server_now', clock_timestamp());
  end if;
  if v_proof ->> 'device_type' is distinct from 'pos' then
    return jsonb_build_object('ok', false, 'error', 'permission_denied', 'proven_scope', true,
      'organization_id', (v_proof ->> 'organization_id')::uuid, 'restaurant_id', (v_proof ->> 'restaurant_id')::uuid,
      'branch_id', (v_proof ->> 'branch_id')::uuid, 'device_id', p_device_id,
      'employee_profile_id', null, 'resolved_membership_id', null);
  end if;
  if not exists (
    select 1 from public.organizations o
    join public.restaurants r on r.organization_id = o.id
    join public.branches b on b.organization_id = o.id and b.restaurant_id = r.id
    where o.id = (v_proof ->> 'organization_id')::uuid and o.status = 'active' and o.deleted_at is null
      and r.id = (v_proof ->> 'restaurant_id')::uuid and r.status = 'active' and r.deleted_at is null
      and b.id = (v_proof ->> 'branch_id')::uuid and b.status = 'active' and b.deleted_at is null
  ) then
    return v_invalid;
  end if;
  select * into v_pin from public.pin_sessions ps
    where ps.id = p_pin_session_id
      and ps.device_session_id = (v_proof ->> 'device_session_id')::uuid
      and ps.organization_id = (v_proof ->> 'organization_id')::uuid
      and ps.restaurant_id = (v_proof ->> 'restaurant_id')::uuid
      and ps.branch_id = (v_proof ->> 'branch_id')::uuid;
  if not found then return v_invalid; end if;
  select * into v_initial_employee from public.employee_profiles ep
    where ep.id = v_pin.employee_profile_id and ep.organization_id = v_pin.organization_id;
  if not found then return v_invalid; end if;
  if v_initial_employee.membership_id is null and v_initial_employee.app_user_id is not null then
    perform 1 from public.app_users u where u.id = v_initial_employee.app_user_id for update;
  end if;
  select * into v_membership from public.memberships m
    where m.id = v_pin.resolved_membership_id and m.organization_id = v_pin.organization_id for share;
  if not found then return v_invalid; end if;
  select * into v_employee from public.employee_profiles ep
    where ep.id = v_pin.employee_profile_id and ep.organization_id = v_pin.organization_id for share;
  if not found then return v_invalid; end if;
  select * into v_locked_pin from public.pin_sessions ps where ps.id = p_pin_session_id for share;
  if not found or v_locked_pin.device_session_id is distinct from v_pin.device_session_id
     or v_locked_pin.employee_profile_id is distinct from v_pin.employee_profile_id
     or v_locked_pin.resolved_membership_id is distinct from v_pin.resolved_membership_id
     or v_locked_pin.organization_id is distinct from v_pin.organization_id
     or v_locked_pin.restaurant_id is distinct from v_pin.restaurant_id
     or v_locked_pin.branch_id is distinct from v_pin.branch_id then
    return v_invalid;
  end if;
  v_now := clock_timestamp();
  if not v_locked_pin.is_active or v_locked_pin.ended_at is not null
     or (v_locked_pin.expires_at is not null and v_locked_pin.expires_at <= v_now)
     or (v_proof ->> 'session_expires_at')::timestamptz <= v_now
     or v_employee.employment_status <> 'active' or v_employee.deleted_at is not null
     or (v_employee.restaurant_id is not null and v_employee.restaurant_id <> v_pin.restaurant_id)
     or (v_employee.branch_id is not null and v_employee.branch_id <> v_pin.branch_id)
     or v_membership.status <> 'active' or v_membership.deleted_at is not null
     or (v_membership.restaurant_id is not null and v_membership.restaurant_id <> v_pin.restaurant_id)
     or (v_membership.branch_id is not null and v_membership.branch_id <> v_pin.branch_id)
     or v_employee.membership_id is distinct from v_initial_employee.membership_id
     or v_employee.app_user_id is distinct from v_initial_employee.app_user_id then
    return v_invalid;
  end if;
  if v_employee.membership_id is not null then
    if v_employee.membership_id <> v_membership.id then
      return v_invalid;
    end if;
  else
    if v_employee.app_user_id is null or v_membership.app_user_id <> v_employee.app_user_id then
      return v_invalid;
    end if;
    select count(*) into v_count from public.memberships m
      where m.organization_id = v_pin.organization_id and m.app_user_id = v_employee.app_user_id
        and m.status = 'active' and m.deleted_at is null;
    if v_count <> 1 then return v_invalid; end if;
  end if;
  if v_membership.role not in ('cashier', 'manager', 'restaurant_owner', 'org_owner') then
    return jsonb_build_object('ok', false, 'error', 'permission_denied', 'proven_scope', true,
      'organization_id', v_pin.organization_id, 'restaurant_id', v_pin.restaurant_id,
      'branch_id', v_pin.branch_id, 'device_id', p_device_id,
      'employee_profile_id', v_employee.id, 'resolved_membership_id', v_membership.id);
  end if;
  return jsonb_build_object('ok', true,
    'organization_id', v_pin.organization_id, 'restaurant_id', v_pin.restaurant_id,
    'branch_id', v_pin.branch_id, 'device_id', p_device_id,
    'device_session_id', (v_proof ->> 'device_session_id')::uuid,
    'employee_profile_id', v_employee.id, 'resolved_membership_id', v_membership.id,
    'role', v_membership.role, 'pin_expires_at', v_locked_pin.expires_at);
end;
$$;

-- The strict-join payment of a LIVE attempt (D-057 point 1), or NULL.
create function app.card_attempt_payment_id(p_attempt app.card_provider_attempts)
  returns uuid
  language sql
  stable
  security definer
  set search_path = ''
as $$
  select p.id from public.payments p
   where p_attempt.mode = 'live'
     and p.organization_id = p_attempt.organization_id
     and p.device_id = p_attempt.device_id
     and p.local_operation_id = p_attempt.local_operation_id
     and p.order_id = p_attempt.order_id
     and p.method = 'card'
     and p.status = 'completed'
     and p.deleted_at is null
     and p.amount_minor = p_attempt.amount_minor
     and p.currency_code = p_attempt.currency_code
     and p.shift_id = p_attempt.shift_id
     and p.cash_drawer_session_id = p_attempt.cash_drawer_session_id
   limit 1;
$$;

-- The derived facts of one attempt (DOMAIN §8.4; API §4.55.3 / §4.55.7):
-- recorded, payment_id, classification, reason, recoverable, claim_active,
-- blocks_close (the canonical close predicate), unresolved (§4.55.9 gates).
create function app.card_attempt_derive(p_attempt app.card_provider_attempts)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  a app.card_provider_attempts := p_attempt;
  v_payment_id uuid;
  v_recorded boolean := false;
  v_reason text;
  v_class text;
  v_order public.orders;
  v_shift public.shifts;
  v_drawer public.cash_drawer_sessions;
  v_device public.devices;
  v_context_ok boolean;
  v_sync_status text;
  v_sync_updated_at timestamptz;
  v_recoverable boolean := false;
  v_claim_active boolean := false;
  v_blocks_close boolean := false;
  v_unresolved boolean := false;
  v_recording_token text;
begin
  if a.id is null then
    return null;
  end if;
  if a.mode = 'test' then
    return jsonb_build_object(
      'recorded', false, 'payment_id', null, 'classification', 'test_' || a.state, 'reason', null,
      'recoverable', false, 'claim_active', false, 'blocks_close', false,
      'unresolved', a.state in ('sent', 'unknown', 'released') and a.resolution is null);
  end if;
  v_payment_id := app.card_attempt_payment_id(a);
  v_recorded := v_payment_id is not null;
  v_claim_active := a.order_freed_at is null and a.resolution is null
                    and (a.state in ('sent', 'unknown', 'released') or (a.state = 'approved' and not v_recorded));
  v_blocks_close := a.resolution is null
                    and ((a.state in ('sent', 'unknown', 'released') and (a.order_freed_at is null or a.charge_may_exist))
                         or (a.state = 'approved' and not v_recorded));
  -- the stored recording-leg token (never release_failed, which is a release fact)
  v_recording_token := case when a.recording_refused_at is not null and a.refusal_code <> 'release_failed'
                            then a.refusal_code end;
  if a.state = 'approved' and not v_recorded and a.resolution is null then
    select * into v_order from public.orders o where o.organization_id = a.organization_id and o.id = a.order_id;
    select * into v_shift from public.shifts s where s.organization_id = a.organization_id and s.id = a.shift_id;
    select * into v_drawer from public.cash_drawer_sessions c
      where c.organization_id = a.organization_id and c.id = a.cash_drawer_session_id;
    select * into v_device from public.devices d where d.organization_id = a.organization_id and d.id = a.device_id;
    v_context_ok := v_shift.id is not null and v_shift.status = 'open' and v_shift.device_id = a.device_id
                    and v_shift.deleted_at is null
                    and v_drawer.id is not null and v_drawer.status = 'active' and v_drawer.shift_id = a.shift_id
                    and v_drawer.deleted_at is null;
    select so.status, so.updated_at into v_sync_status, v_sync_updated_at from public.sync_operations so
      where so.organization_id = a.organization_id and so.device_id = a.device_id
        and so.local_operation_id = a.local_operation_id;
    -- A non-recoverable stored token is sticky (the identity's row may even be a
    -- foreign row parked pending). A recoverable one is the current reason only
    -- while it reports the leg's latest refusal: the leg terminal again and the
    -- report not older than the row's last stamp or the last authorized Resume;
    -- otherwise that refusal still awaits its report (pending_recording).
    if v_recording_token in ('precondition_failed', 'revoked_employee', 'permission_denied')
       and (coalesce(v_sync_status, '') in ('pending', 'in_flight', 'created')
            or a.recording_refused_at < v_sync_updated_at
            or a.recording_refused_at
               < coalesce((a.recording_resume_history -> -1 ->> 'at')::timestamptz, '-infinity')) then
      v_recording_token := null;
    end if;
    v_reason := case
      when a.order_freed_at is not null then 'order_freed'
      when not v_context_ok then 'context_lost'
      when v_order.id is null or v_order.status in ('voided', 'cancelled', 'completed') then 'order_terminal'
      when v_order.grand_total_minor <> a.amount_minor or v_order.currency_code <> a.currency_code then 'amount_mismatch'
      when v_device.id is null or not v_device.is_active then 'device_revoked'
      when a.recording_resume_count >= 3 and v_sync_status in ('rejected', 'conflict') then 'resume_limit'
      when v_recording_token is not null
           and v_recording_token not in ('precondition_failed', 'revoked_employee', 'permission_denied')
        then 'nonrecoverable_refusal'
      when v_recording_token is not null then 'recording_refused'
      when not exists (
        select 1 from public.device_pairings dp
        join public.device_sessions ds on ds.device_pairing_id = dp.id and ds.device_id = dp.device_id
        where dp.device_id = a.device_id and dp.organization_id = a.organization_id
          and dp.status = 'active' and dp.revoked_at is null and dp.deleted_at is null
          and ds.is_active and ds.revoked_at is null
          and (ds.expires_at is null or ds.expires_at > clock_timestamp())) then 'device_session_unavailable'
      else 'pending_recording'
    end;
    v_recoverable := v_reason = 'recording_refused'
      and a.recording_resume_count < 3
      and v_claim_active
      and v_device.is_active
      and v_context_ok
      and v_order.status in ('submitted', 'accepted', 'preparing', 'ready', 'served')
      and v_order.grand_total_minor > 0
      and v_order.grand_total_minor = a.amount_minor
      and v_order.currency_code = a.currency_code
      and not app.order_is_fully_settled(a.organization_id, a.order_id)
      and not exists (select 1 from public.payments p
                       where p.organization_id = a.organization_id and p.order_id = a.order_id
                         and p.status = 'completed' and p.deleted_at is null);
  end if;
  v_class := case
    when a.resolution is not null then 'resolved'
    when a.state = 'sent' then 'in_progress'
    when a.state in ('unknown', 'released') and a.charge_may_exist then 'provider_anomaly'
    when a.state in ('unknown', 'released') and a.order_freed_at is not null then 'freed'
    when a.state in ('unknown', 'released') then 'in_progress'
    when a.state = 'declined' then 'declined'
    when v_recorded then 'recorded'
    when v_reason in ('order_freed', 'context_lost', 'order_terminal', 'amount_mismatch', 'device_revoked',
                      'resume_limit', 'nonrecoverable_refusal') then 'orphan_approved'
    else 'approved_unrecorded'
  end;
  v_unresolved := v_class in ('in_progress', 'provider_anomaly', 'approved_unrecorded', 'orphan_approved');
  return jsonb_build_object(
    'recorded', v_recorded, 'payment_id', v_payment_id, 'classification', v_class, 'reason', v_reason,
    'recoverable', coalesce(v_recoverable, false), 'claim_active', v_claim_active,
    'blocks_close', v_blocks_close, 'unresolved', v_unresolved);
end;
$$;

-- The one §4.55.4 response envelope. No card data, provider reference, key,
-- terminal or credential reference ever appears here.
create function app.card_attempt_envelope(p_attempt app.card_provider_attempts)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  d jsonb := app.card_attempt_derive(p_attempt);
  v jsonb;
begin
  v := jsonb_build_object('ok', true, 'attempt_id', p_attempt.local_operation_id,
    'state', p_attempt.state, 'classification', d ->> 'classification',
    'recorded', (d ->> 'recorded')::boolean,
    'amount_minor', p_attempt.amount_minor, 'currency_code', p_attempt.currency_code,
    'server_ts', clock_timestamp());
  if p_attempt.provider_return_code is not null then
    v := v || jsonb_build_object('provider_return_code', p_attempt.provider_return_code);
  end if;
  if p_attempt.refusal_code is not null then
    v := v || jsonb_build_object('refusal_code', p_attempt.refusal_code);
  end if;
  if d ->> 'classification' = 'provider_anomaly' then
    v := v || jsonb_build_object('anomaly_code', p_attempt.provider_anomaly_code);
  end if;
  if p_attempt.resolution is not null then
    v := v || jsonb_build_object('resolution', p_attempt.resolution);
  end if;
  if d ->> 'classification' in ('approved_unrecorded', 'orphan_approved') then
    v := v || jsonb_build_object('recoverable', (d ->> 'recoverable')::boolean,
                                 'resume_count', p_attempt.recording_resume_count);
  end if;
  if (d ->> 'recorded')::boolean then
    v := v || jsonb_build_object('payment_id', (d ->> 'payment_id')::uuid);
  end if;
  return v;
end;
$$;

-- §4.55.3 "active claim" of an order (the guard; the snapshot key of §4.30c
-- counts the order's own-branch LIVE attempts, the same set for every row the
-- RPCs write - D-059 point 1).
create function app.card_order_claim_active(p_organization_id uuid, p_order_id uuid)
  returns boolean
  language sql
  stable
  security definer
  set search_path = ''
as $$
  select exists (
    select 1 from app.card_provider_attempts a
     where a.organization_id = p_organization_id and a.order_id = p_order_id
       and a.mode = 'live' and a.order_freed_at is null and a.resolution is null
       and (a.state in ('sent', 'unknown', 'released')
            or (a.state = 'approved' and app.card_attempt_payment_id(a) is null)));
$$;

-- §4.55.3 canonical close predicate over every LIVE attempt frozen to the shift.
create function app.card_shift_close_blocked(p_organization_id uuid, p_shift_id uuid)
  returns boolean
  language sql
  stable
  security definer
  set search_path = ''
as $$
  select exists (
    select 1 from app.card_provider_attempts a
     where a.organization_id = p_organization_id and a.shift_id = p_shift_id
       and a.mode = 'live' and a.resolution is null
       and ((a.state in ('sent', 'unknown', 'released') and (a.order_freed_at is null or a.charge_may_exist))
            or (a.state = 'approved' and app.card_attempt_payment_id(a) is null)));
$$;

-- D-057 point 3: the active-manager proof of a Resume, read without row locks.
-- NULL = passes; else actor_not_active | not_manager | device_not_active.
create function app.card_active_manager_denial(p_pin_session_id uuid, p_device_id uuid)
  returns text
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_pin public.pin_sessions;
  v_membership public.memberships;
  v_employee public.employee_profiles;
  v_device public.devices;
  v_ds_device uuid;
begin
  select * into v_pin from public.pin_sessions ps where ps.id = p_pin_session_id;
  if not found or not app.is_pin_session_valid(p_pin_session_id) then
    return 'actor_not_active';
  end if;
  select * into v_membership from public.memberships m
    where m.id = v_pin.resolved_membership_id and m.organization_id = v_pin.organization_id;
  select * into v_employee from public.employee_profiles ep
    where ep.id = v_pin.employee_profile_id and ep.organization_id = v_pin.organization_id;
  if v_membership.id is null or v_membership.status <> 'active' or v_membership.deleted_at is not null
     or (v_membership.restaurant_id is not null and v_membership.restaurant_id <> v_pin.restaurant_id)
     or (v_membership.branch_id is not null and v_membership.branch_id <> v_pin.branch_id)
     or v_employee.id is null or v_employee.employment_status <> 'active' or v_employee.deleted_at is not null then
    return 'actor_not_active';
  end if;
  if v_membership.role not in ('manager', 'restaurant_owner', 'org_owner') then
    return 'not_manager';
  end if;
  select ds.device_id into v_ds_device from public.device_sessions ds where ds.id = v_pin.device_session_id;
  select * into v_device from public.devices d
    where d.id = p_device_id and d.organization_id = v_pin.organization_id;
  if v_ds_device is distinct from p_device_id or v_device.id is null or not v_device.is_active
     or v_device.deleted_at is not null or v_device.device_type <> 'pos' then
    return 'device_not_active';
  end if;
  return null;
end;
$$;

-- §4.55.3 "Authorization first": true only when the dispatched RPC is CERTAIN
-- to deny this PIN session on a payload-independent gate (membership, role,
-- cashier capability, close_shift's own-shift rule, the pos device-type gate of
-- add_order_items / edit_order). The membership row is read FOR SHARE so the
-- decision is exact against a concurrent grant or revocation.
create function app.card_dispatch_certain_deny(
  p_pin_session_id uuid, p_device_id uuid, p_operation_type text, p_shift_id uuid)
  returns boolean
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_pin public.pin_sessions;
  v_membership public.memberships;
  v_device_type text;
  v_opened_by uuid;
  v_found boolean;
begin
  select * into v_pin from public.pin_sessions ps where ps.id = p_pin_session_id;
  if not found then
    return true;
  end if;
  select * into v_membership from public.memberships m
    where m.id = v_pin.resolved_membership_id and m.organization_id = v_pin.organization_id
    for share;
  if not found or v_membership.status <> 'active' or v_membership.deleted_at is not null then
    return true;
  end if;
  case p_operation_type
    when 'payment.create' then
      return v_membership.role not in ('cashier', 'manager', 'restaurant_owner', 'org_owner');
    when 'order.void' then
      return not ((v_membership.role in ('manager', 'restaurant_owner', 'org_owner'))
                  or app.cashier_capability_allowed(v_membership.role, v_membership.permissions, 'void_order'));
    when 'order.discount' then
      return not ((v_membership.role in ('manager', 'restaurant_owner', 'org_owner'))
                  or app.cashier_capability_allowed(v_membership.role, v_membership.permissions, 'apply_discount'));
    when 'order.items_add', 'order.edit' then
      select d.device_type into v_device_type from public.devices d
        where d.id = p_device_id and d.organization_id = v_pin.organization_id;
      return v_device_type is distinct from 'pos'
          or v_membership.role not in ('cashier', 'manager', 'restaurant_owner', 'org_owner');
    when 'shift.close' then
      select s.opened_by_employee_profile_id, true into v_opened_by, v_found from public.shifts s
        where s.id = p_shift_id and s.organization_id = v_pin.organization_id and s.branch_id = v_pin.branch_id;
      if not coalesce(v_found, false) then
        return false;
      end if;
      return not ((v_membership.role in ('manager', 'restaurant_owner', 'org_owner'))
                  or (app.cashier_capability_allowed(v_membership.role, v_membership.permissions, 'close_shift')
                      and v_opened_by = v_pin.employee_profile_id));
    else
      return false;
  end case;
end;
$$;

-- The only writer of app.card_provider_private_events rows. M1: the two
-- deduplicated actions insert ON CONFLICT on exactly their partial unique
-- index; every other error still raises.
create function app.card_private_event_write(
  p_organization_id uuid, p_restaurant_id uuid, p_branch_id uuid, p_attempt_row_id uuid,
  p_mode text, p_action text, p_actor_kind text, p_actor_reference text,
  p_actor_app_user_id uuid, p_executor_principal text, p_actor_employee_profile_id uuid,
  p_device_id uuid, p_reason text, p_detail jsonb)
  returns uuid
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_now timestamptz := clock_timestamp();
  v_id uuid;
begin
  if p_action = 'security.card_provider_field_dropped' then
    insert into app.card_provider_private_events (organization_id, restaurant_id, branch_id, attempt_row_id, mode,
        action, actor_kind, actor_reference, actor_app_user_id, executor_principal, actor_employee_profile_id,
        device_id, reason, detail, retention_until, created_at)
      values (p_organization_id, p_restaurant_id, p_branch_id, p_attempt_row_id, p_mode, p_action, p_actor_kind,
        p_actor_reference, p_actor_app_user_id, p_executor_principal, p_actor_employee_profile_id, p_device_id,
        p_reason, coalesce(p_detail, '{}'::jsonb),
        case when p_mode = 'test' then v_now + interval '90 days' end, v_now)
      on conflict (attempt_row_id, (detail ->> 'field'), (detail ->> 'rule'))
        where action = 'security.card_provider_field_dropped' do nothing
      returning id into v_id;
  elsif p_action = 'test.card_recording_refused' then
    insert into app.card_provider_private_events (organization_id, restaurant_id, branch_id, attempt_row_id, mode,
        action, actor_kind, actor_reference, actor_app_user_id, executor_principal, actor_employee_profile_id,
        device_id, reason, detail, retention_until, created_at)
      values (p_organization_id, p_restaurant_id, p_branch_id, p_attempt_row_id, p_mode, p_action, p_actor_kind,
        p_actor_reference, p_actor_app_user_id, p_executor_principal, p_actor_employee_profile_id, p_device_id,
        p_reason, coalesce(p_detail, '{}'::jsonb),
        case when p_mode = 'test' then v_now + interval '90 days' end, v_now)
      on conflict (attempt_row_id) where action = 'test.card_recording_refused' do nothing
      returning id into v_id;
  else
    insert into app.card_provider_private_events (organization_id, restaurant_id, branch_id, attempt_row_id, mode,
        action, actor_kind, actor_reference, actor_app_user_id, executor_principal, actor_employee_profile_id,
        device_id, reason, detail, retention_until, created_at)
      values (p_organization_id, p_restaurant_id, p_branch_id, p_attempt_row_id, p_mode, p_action, p_actor_kind,
        p_actor_reference, p_actor_app_user_id, p_executor_principal, p_actor_employee_profile_id, p_device_id,
        p_reason, coalesce(p_detail, '{}'::jsonb),
        case when p_mode = 'test' then v_now + interval '90 days' end, v_now)
      returning id into v_id;
  end if;
  return v_id;
end;
$$;

-- Tenant audit for the LIVE card_attempt.* family (§4.33). reason is always NULL
-- (the Activity log returns it raw); the detail is projected by the
-- action-scoped allowlist of app.audit_safe_detail.
create function app.card_audit_write(
  p_organization_id uuid, p_restaurant_id uuid, p_branch_id uuid, p_actor_employee_profile_id uuid,
  p_device_id uuid, p_action text, p_detail jsonb)
  returns void
  language sql
  volatile
  security definer
  set search_path = ''
as $$
  insert into public.audit_events (organization_id, restaurant_id, branch_id, actor_app_user_id,
      actor_employee_profile_id, device_id, action, reason, old_values, new_values)
  values (p_organization_id, p_restaurant_id, p_branch_id, null, p_actor_employee_profile_id, p_device_id,
          p_action, null, null, p_detail);
$$;

-- Denial evidence of a writing §4.55 RPC (§4.55.2; D-056 point 6): a LIVE
-- request -> tenant audit card_attempt.denied; a TEST request -> the private
-- event test.card_attempt_denied (90-day retention). Never for an invalid
-- session (no proven scope).
create function app.card_denial_evidence(
  p_mode text, p_organization_id uuid, p_restaurant_id uuid, p_branch_id uuid,
  p_actor_employee_profile_id uuid, p_device_id uuid, p_attempt_row_id uuid, p_rpc text, p_denied_reason text)
  returns void
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
begin
  if p_mode = 'live' then
    perform app.card_audit_write(p_organization_id, p_restaurant_id, p_branch_id, p_actor_employee_profile_id,
      p_device_id, 'card_attempt.denied', jsonb_build_object('denied_reason', p_denied_reason));
  elsif p_mode = 'test' then
    perform app.card_private_event_write(p_organization_id, p_restaurant_id, p_branch_id, p_attempt_row_id, 'test',
      'test.card_attempt_denied',
      case when p_actor_employee_profile_id is null then 'device' else 'employee' end,
      case when p_actor_employee_profile_id is null then 'device' else 'employee' end,
      null, null, p_actor_employee_profile_id, p_device_id,
      null, jsonb_build_object('rpc', p_rpc, 'denied_reason', p_denied_reason));
  end if;
end;
$$;

-- Resolve an attempt for a proven session (§4.55.2): a cashier acts on the
-- originating till only, by (organization, device, attempt_id); a manager+
-- resolves by (organization, branch, attempt_id) — attempt_not_found on no
-- match, conflict on more than one (the client-minted id is unique only per
-- device). Returns the row id or the refusal token. Never locks.
create function app.card_attempt_resolve(p_proof jsonb, p_attempt_id text)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_id uuid;
  v_count integer;
begin
  if p_proof ->> 'role' in ('manager', 'restaurant_owner', 'org_owner') then
    select count(*), min(a.id::text)::uuid into v_count, v_id from app.card_provider_attempts a
      where a.organization_id = (p_proof ->> 'organization_id')::uuid
        and a.branch_id = (p_proof ->> 'branch_id')::uuid
        and a.local_operation_id = p_attempt_id;
    if v_count = 1 then
      return jsonb_build_object('ok', true, 'attempt_row_id', v_id);
    elsif v_count > 1 then
      return jsonb_build_object('ok', false, 'error', 'conflict');
    end if;
    return jsonb_build_object('ok', false, 'error', 'attempt_not_found');
  end if;
  select a.id into v_id from app.card_provider_attempts a
    where a.organization_id = (p_proof ->> 'organization_id')::uuid
      and a.device_id = (p_proof ->> 'device_id')::uuid
      and a.local_operation_id = p_attempt_id;
  if v_id is not null then
    return jsonb_build_object('ok', true, 'attempt_row_id', v_id);
  end if;
  return jsonb_build_object('ok', false, 'error', 'attempt_not_found');
end;
$$;

-- A write-time proof refusal of a service-only mark (§4.55.2): an invalid
-- session has no proven scope and writes nothing; a permission_denied with a
-- proven scope writes the mode-aware denial evidence for the originating
-- device's attempt (organization, device, attempt_id), or nothing when no such
-- attempt exists. Never locks.
create function app.card_proof_denial_evidence(p_proof jsonb, p_device_id uuid, p_attempt_id text, p_rpc text)
  returns void
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  a app.card_provider_attempts;
begin
  if p_proof ->> 'error' is distinct from 'permission_denied' or not coalesce((p_proof ->> 'proven_scope')::boolean, false)
     or p_attempt_id is null then
    return;
  end if;
  select * into a from app.card_provider_attempts x
    where x.organization_id = (p_proof ->> 'organization_id')::uuid and x.device_id = p_device_id
      and x.local_operation_id = p_attempt_id;
  if a.id is null then
    return;
  end if;
  perform app.card_denial_evidence(a.mode, a.organization_id, a.restaurant_id, a.branch_id,
    (p_proof ->> 'employee_profile_id')::uuid, p_device_id, a.id, p_rpc, 'permission_denied');
end;
$$;

-- §4.55.4 / §4.55.5: validate the configuration records behind a terminal and
-- credential reference (references, tokens and ids only — never a credential
-- value). NULL = valid; else a closed mismatch token for the security event.
create function app.card_config_mismatch(
  p_mode text, p_restaurant_id uuid, p_terminal_ref text, p_credential_ref text,
  p_environment text, p_terminals jsonb, p_credentials jsonb)
  returns text
  language plpgsql
  immutable
  set search_path = ''
as $$
declare
  v_record jsonb;
begin
  if p_environment is distinct from (case p_mode when 'test' then 'test' when 'live' then 'production' end) then
    return 'environment_mode';
  end if;
  if p_terminals is null or jsonb_typeof(p_terminals) <> 'object' or not (p_terminals ? p_terminal_ref) then
    return 'terminal_absent';
  end if;
  if jsonb_typeof(p_terminals -> p_terminal_ref) <> 'string' or p_terminals ->> p_terminal_ref <> p_credential_ref then
    return 'terminal_credential';
  end if;
  if p_credentials is null or jsonb_typeof(p_credentials) <> 'object' or not (p_credentials ? p_credential_ref) then
    return 'credential_absent';
  end if;
  v_record := p_credentials -> p_credential_ref;
  if jsonb_typeof(v_record) <> 'object' or v_record ->> 'mode' is distinct from p_mode then
    return 'credential_mode';
  end if;
  if p_mode = 'live' then
    if v_record ->> 'scope' is distinct from 'merchant' then
      return 'credential_scope';
    end if;
    if v_record ->> 'restaurant_id' is distinct from p_restaurant_id::text then
      return 'credential_restaurant';
    end if;
  else
    if v_record ->> 'scope' is distinct from 'development' then
      return 'credential_scope';
    end if;
    if v_record ? 'restaurant_id' and v_record -> 'restaurant_id' <> 'null'::jsonb then
      return 'credential_restaurant';
    end if;
  end if;
  return null;
end;
$$;


-- ----------------------------------------------------------------------------
-- 4. Integrity triggers (the database is the last boundary, D-012 layer 4).
-- ----------------------------------------------------------------------------
create function app.card_append_only_guard()
  returns trigger
  language plpgsql
  set search_path = ''
as $$
begin
  raise exception '% is append-only: % is not permitted', tg_table_name, tg_op using errcode = '42501';
end;
$$;

create trigger card_pilot_revisions_append_only
  before update or delete on app.card_payments_pilot_revisions
  for each row execute function app.card_append_only_guard();
create trigger card_pilot_revisions_no_truncate
  before truncate on app.card_payments_pilot_revisions
  for each statement execute function app.card_append_only_guard();
create trigger card_tombstones_append_only
  before update or delete on app.card_attempt_identity_tombstones
  for each row execute function app.card_append_only_guard();
create trigger card_tombstones_no_truncate
  before truncate on app.card_attempt_identity_tombstones
  for each statement execute function app.card_append_only_guard();
create trigger card_attempts_no_truncate
  before truncate on app.card_provider_attempts
  for each statement execute function app.card_append_only_guard();
create trigger card_events_no_truncate
  before truncate on app.card_provider_private_events
  for each statement execute function app.card_append_only_guard();
create trigger payment_terminals_no_truncate
  before truncate on app.payment_terminals
  for each statement execute function app.card_append_only_guard();

-- §8.5 terminal binding: insert only as configured; lifecycle transitions;
-- immutable scope / mode / references; no delete; credential-reference
-- ownership (one mode per reference; a live reference belongs to exactly one
-- organization + restaurant).
create function app.payment_terminals_guard()
  returns trigger
  language plpgsql
  security definer
  set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'payment_terminals rows are never deleted' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    if new.lifecycle <> 'configured' or new.deleted_at is not null then
      raise exception 'payment_terminals: a binding is created configured' using errcode = '23514';
    end if;
    -- Serialize bindings naming the same credential reference, so the ownership
    -- check below also holds between concurrent operator calls for different devices.
    perform pg_advisory_xact_lock(hashtextextended('card-credential-ref/v1:' || new.credential_ref, 0));
    if exists (select 1 from app.payment_terminals t
                where t.credential_ref = new.credential_ref
                  and (t.mode <> new.mode
                       or (new.mode = 'live' and (t.organization_id <> new.organization_id
                                                  or t.restaurant_id <> new.restaurant_id)))) then
      raise exception 'payment_terminals: credential reference ownership violated' using errcode = '23514';
    end if;
    new.lifecycle_changed_at := clock_timestamp();
    new.created_at := clock_timestamp();
    new.updated_at := clock_timestamp();
    return new;
  end if;
  if new.id <> old.id or new.organization_id <> old.organization_id or new.restaurant_id <> old.restaurant_id
     or new.branch_id <> old.branch_id or new.device_id <> old.device_id or new.mode <> old.mode
     or new.terminal_ref <> old.terminal_ref or new.credential_ref <> old.credential_ref
     or new.created_at <> old.created_at or new.deleted_at is distinct from old.deleted_at then
    raise exception 'payment_terminals: mode, references and scope are immutable' using errcode = '23514';
  end if;
  if new.lifecycle <> old.lifecycle then
    if not ((old.lifecycle = 'configured' and new.lifecycle in ('enabled', 'retired'))
            or (old.lifecycle = 'enabled' and new.lifecycle = 'draining')
            or (old.lifecycle = 'draining' and new.lifecycle in ('enabled', 'retired'))) then
      raise exception 'payment_terminals: lifecycle % -> % is not allowed', old.lifecycle, new.lifecycle
        using errcode = '23514';
    end if;
    new.lifecycle_changed_at := clock_timestamp();
  else
    new.lifecycle_changed_at := old.lifecycle_changed_at;
  end if;
  new.updated_at := clock_timestamp();
  return new;
end;
$$;
create trigger payment_terminals_guard
  before insert or update or delete on app.payment_terminals
  for each row execute function app.payment_terminals_guard();

-- §8.4 ledger insert: a fresh row is sent, unresolved, unfreed; a LIVE drawer
-- session belongs to the frozen shift.
create function app.card_attempts_insert_guard()
  returns trigger
  language plpgsql
  security definer
  set search_path = ''
as $$
begin
  if new.state <> 'sent' or new.resolution is not null or new.order_freed_at is not null
     or new.charge_may_exist or new.recording_resume_count <> 0 or new.refusal_code is not null then
    raise exception 'card_provider_attempts: a fresh attempt is an unresolved sent claim' using errcode = '23514';
  end if;
  if new.mode = 'live' and not exists (
       select 1 from public.cash_drawer_sessions c
        where c.organization_id = new.organization_id and c.id = new.cash_drawer_session_id
          and c.shift_id = new.shift_id) then
    raise exception 'card_provider_attempts: the drawer session must belong to the frozen shift' using errcode = '23514';
  end if;
  new.created_at := clock_timestamp();
  new.updated_at := new.created_at;
  new.claim_signal_at := new.created_at;
  if new.mode = 'test' then
    new.retention_until := new.created_at + interval '90 days';
  end if;
  return new;
end;
$$;
create trigger card_attempts_insert_guard
  before insert on app.card_provider_attempts
  for each row execute function app.card_attempts_insert_guard();

-- §8.4 ledger update / delete. A disallowed state transition (or any state /
-- provider-field change on a resolved row) is a silent no-op (RETURN NULL), never
-- a RAISE; the frozen identity / claim columns, the free stamp and the
-- resolution are guarded with exactly the RPC predicates and raise when broken.
create function app.card_attempts_guard()
  returns trigger
  language plpgsql
  security definer
  set search_path = ''
as $$
declare
  v_old_class text;
  v_mutable_changed boolean;
begin
  if tg_op = 'DELETE' then
    if old.mode = 'test' and old.retention_until <= clock_timestamp() and old.incident_hold_at is null then
      return old;
    end if;
    raise exception 'card_provider_attempts: only an expired, unheld TEST attempt may be purged' using errcode = '42501';
  end if;
  if (new.id, new.organization_id, new.restaurant_id, new.branch_id, new.device_id, new.local_operation_id,
      new.order_id, new.shift_id, new.cash_drawer_session_id, new.initiated_by_employee_profile_id,
      new.initiated_by_membership_id, new.mode, new.amount_minor, new.currency_code, new.expected_revision,
      new.terminal_ref, new.credential_ref, new.provider_status_digest, new.provider_duplicate_digest,
      new.provider_key_format_version, new.provider_query_key, new.provider_duplicate_key,
      new.start_deadline_at, new.started_at, new.created_at, new.retention_until)
     is distinct from
     (old.id, old.organization_id, old.restaurant_id, old.branch_id, old.device_id, old.local_operation_id,
      old.order_id, old.shift_id, old.cash_drawer_session_id, old.initiated_by_employee_profile_id,
      old.initiated_by_membership_id, old.mode, old.amount_minor, old.currency_code, old.expected_revision,
      old.terminal_ref, old.credential_ref, old.provider_status_digest, old.provider_duplicate_digest,
      old.provider_key_format_version, old.provider_query_key, old.provider_duplicate_key,
      old.start_deadline_at, old.started_at, old.created_at, old.retention_until) then
    raise exception 'card_provider_attempts: the frozen attempt facts are immutable' using errcode = '23514';
  end if;
  -- A resolved attempt is final: only the TEST hold metadata may still change.
  if old.resolution is not null then
    v_mutable_changed := (to_jsonb(new) - 'incident_hold_at' - 'incident_hold_reference' - 'updated_at')
                         is distinct from (to_jsonb(old) - 'incident_hold_at' - 'incident_hold_reference' - 'updated_at');
    if v_mutable_changed then
      return null;
    end if;
    new.claim_signal_at := old.claim_signal_at;
    new.updated_at := clock_timestamp();
    return new;
  end if;
  -- State machine: sent -> approved|declined|unknown|released; unknown|released
  -- -> approved|declined; nothing leaves approved or declined.
  if new.state <> old.state
     and not ((old.state = 'sent' and new.state in ('approved', 'declined', 'unknown', 'released'))
              or (old.state in ('unknown', 'released') and new.state in ('approved', 'declined'))) then
    return null;
  end if;
  if old.provider_anomaly_code is not null and new.provider_anomaly_code is null then
    raise exception 'card_provider_attempts: the anomaly code is kept as history' using errcode = '23514';
  end if;
  -- Only a later exact approved / declined result clears charge_may_exist; a
  -- final row's anomaly history never changes (disallowed changes are no-ops).
  if old.charge_may_exist and not new.charge_may_exist
     and not (old.state in ('unknown', 'released') and new.state in ('approved', 'declined')) then
    return null;
  end if;
  if old.state in ('approved', 'declined')
     and new.provider_anomaly_code is distinct from old.provider_anomaly_code then
    return null;
  end if;
  -- The free stamp: set once, never re-stamped (§4.55.6 / §4.55.7 predicates).
  if old.order_freed_at is not null
     and (new.order_freed_at is distinct from old.order_freed_at
          or new.order_freed_reason is distinct from old.order_freed_reason) then
    raise exception 'card_provider_attempts: order_freed_at is never re-stamped' using errcode = '23514';
  end if;
  if (old.confirmation_source, old.confirmation_reference, old.order_freed_note)
     is distinct from (new.confirmation_source, new.confirmation_reference, new.order_freed_note)
     and not (old.order_freed_at is null and new.order_freed_at is not null
              and new.order_freed_reason = 'manager_confirmed') then
    raise exception 'card_provider_attempts: the free confirmation is written only with the manager free'
      using errcode = '23514';
  end if;
  if old.order_freed_at is null and new.order_freed_at is not null then
    if new.order_freed_reason = 'manager_confirmed' then
      if not (old.mode = 'live' and old.state in ('unknown', 'released') and new.state = old.state
              and not old.charge_may_exist and not new.charge_may_exist and old.last_lookup_at is not null
              and new.confirmation_source in ('provider_report', 'provider_back_office')
              and coalesce(btrim(new.confirmation_reference), '') <> '' and new.resolution is null) then
        raise exception 'card_provider_attempts: the manager free predicate does not hold' using errcode = '42501';
      end if;
    elsif new.order_freed_reason = 'orphan_resolved' then
      if new.resolution is null or new.resolution not in ('provider_voided', 'provider_refunded') then
        raise exception 'card_provider_attempts: an orphan free needs a provider void or refund' using errcode = '42501';
      end if;
    else
      raise exception 'card_provider_attempts: unknown free reason' using errcode = '23514';
    end if;
  end if;
  -- The resolution: set once, only on the rows the operator RPC may resolve.
  if new.resolution is not null then
    if old.mode = 'live' then
      v_old_class := app.card_attempt_derive(old) ->> 'classification';
      if not (new.resolution in ('provider_voided', 'provider_refunded')
              and (v_old_class = 'orphan_approved'
                   or (old.state in ('unknown', 'released') and old.charge_may_exist))
              and new.state = old.state) then
        raise exception 'card_provider_attempts: this LIVE attempt cannot be resolved' using errcode = '42501';
      end if;
    else
      if not (new.resolution = 'test_closed'
              and ((old.state = 'sent' and old.start_deadline_at <= clock_timestamp())
                   or old.state in ('unknown', 'released'))) then
        raise exception 'card_provider_attempts: this TEST attempt cannot be closed' using errcode = '42501';
      end if;
    end if;
  end if;
  -- D-059 point 1: the claim signal advances only when the active-claim facts can
  -- change - the state (at most two transitions), the manager free or the
  -- resolution (each once); every other write keeps it, so it terminates.
  if new.state is distinct from old.state or new.order_freed_at is distinct from old.order_freed_at
     or new.resolution is distinct from old.resolution then
    new.claim_signal_at := clock_timestamp();
  else
    new.claim_signal_at := old.claim_signal_at;
  end if;
  new.updated_at := clock_timestamp();
  return new;
end;
$$;
create trigger card_attempts_guard
  before update or delete on app.card_provider_attempts
  for each row execute function app.card_attempts_guard();

-- §8.6: event facts are immutable; only the hold metadata of a mode='test'
-- event may change; DELETE only for an expired TEST event with no hold of its
-- own whose attempt (if any) carries no hold.
create function app.card_events_guard()
  returns trigger
  language plpgsql
  security definer
  set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    if old.mode = 'test' and old.retention_until <= clock_timestamp() and old.incident_hold_at is null
       and not exists (select 1 from app.card_provider_attempts a
                        where a.id = old.attempt_row_id and a.incident_hold_at is not null) then
      return old;
    end if;
    raise exception 'card_provider_private_events: only an expired, unheld TEST event may be purged'
      using errcode = '42501';
  end if;
  if (to_jsonb(new) - 'incident_hold_at' - 'incident_hold_reference')
     is distinct from (to_jsonb(old) - 'incident_hold_at' - 'incident_hold_reference')
     or old.mode is distinct from 'test' then
    raise exception 'card_provider_private_events: event facts are immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger card_events_guard
  before update or delete on app.card_provider_private_events
  for each row execute function app.card_events_guard();


-- ----------------------------------------------------------------------------
-- 5. Caller-authority RPCs (authenticated on both layers; the SQL proof is the gate).
-- ----------------------------------------------------------------------------
-- The terminal posture of one exact device (§4.30b / §4.55.9): NULL without a
-- configured / enabled / draining binding; else its lifecycle and mode and
-- whether new starts are admitted (revision ON within its window, binding
-- enabled, binding mode = revision mode).
create function app.card_terminal_posture(p_organization_id uuid, p_branch_id uuid, p_device_id uuid)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_row app.payment_terminals;
  v_rev app.card_payments_pilot_revisions;
begin
  select * into v_row from app.payment_terminals t
    where t.organization_id = p_organization_id and t.device_id = p_device_id
      and t.deleted_at is null and t.lifecycle in ('configured', 'enabled', 'draining');
  if not found then
    return null;
  end if;
  v_rev := app.card_pilot_revision_current();
  return jsonb_build_object('lifecycle', v_row.lifecycle, 'mode', v_row.mode,
    'enabled', coalesce(v_rev.enabled and v_rev.window_until > now()
                        and v_rev.organization_id = p_organization_id and v_rev.branch_id = p_branch_id
                        and v_row.branch_id = p_branch_id
                        and v_row.lifecycle = 'enabled' and v_row.mode = v_rev.mode, false));
end;
$$;

-- §4.55.2 / §4.55.10: the read-only context proof (its only write is the
-- device-session renewal of the precedent). Returns scope ids, role, the order
-- facts, the attempt's client-safe envelope and the exact device's terminal
-- posture; never a credential, terminal / credential reference, provider key,
-- provider reference, approval or voucher number. Its refusals are unaudited.
create function app.card_attempt_context(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_order_id uuid, p_attempt_id text)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_proof jsonb;
  v_order public.orders;
  v_order_json jsonb;
  v_resolved jsonb;
  v_attempt app.card_provider_attempts;
  v_attempt_json jsonb;
  v_posture jsonb;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_session');
  end if;
  -- §4.55.2 / D-059 point 5: a caller holding an ACTIVE platform support session
  -- (the server-resolved app.current_support_session of the verified JWT) cannot
  -- pass, whatever staff PIN and device inputs it carries; checked before any
  -- proof, renewal or read. A platform-admin grant alone confers nothing here.
  if app.current_support_session() is not null then
    return jsonb_build_object('ok', false, 'error', 'permission_denied');
  end if;
  if p_attempt_id is not null
     and p_attempt_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;
  v_proof := app.card_attempt_proof(p_pin_session_id, p_device_id, p_device_session_token, true);
  if (v_proof ->> 'ok') is distinct from 'true' then
    return jsonb_build_object('ok', false, 'error', coalesce(v_proof ->> 'error', 'invalid_session'));
  end if;
  if p_order_id is not null then
    select * into v_order from public.orders o
      where o.id = p_order_id and o.organization_id = (v_proof ->> 'organization_id')::uuid
        and o.branch_id = (v_proof ->> 'branch_id')::uuid and o.deleted_at is null;
    if found then
      v_order_json := jsonb_build_object('order_id', v_order.id, 'status', v_order.status,
        'grand_total_minor', v_order.grand_total_minor, 'currency_code', v_order.currency_code,
        'revision', v_order.revision,
        'active_claim', app.card_order_claim_active(v_order.organization_id, v_order.id),
        'settled', exists (select 1 from public.payments p
                            where p.organization_id = v_order.organization_id and p.order_id = v_order.id
                              and p.status = 'completed' and p.deleted_at is null)
                   or app.order_is_fully_settled(v_order.organization_id, v_order.id));
    end if;
  end if;
  if p_attempt_id is not null then
    v_resolved := app.card_attempt_resolve(v_proof, p_attempt_id);
    if v_resolved ->> 'error' = 'conflict' then
      return jsonb_build_object('ok', false, 'error', 'conflict');
    end if;
    if (v_resolved ->> 'ok')::boolean then
      select * into v_attempt from app.card_provider_attempts a where a.id = (v_resolved ->> 'attempt_row_id')::uuid;
      v_attempt_json := (app.card_attempt_envelope(v_attempt) - 'ok' - 'server_ts')
        || jsonb_build_object('mode', v_attempt.mode,
                              'own_device', v_attempt.device_id = (v_proof ->> 'device_id')::uuid);
    end if;
  end if;
  v_posture := app.card_terminal_posture((v_proof ->> 'organization_id')::uuid, (v_proof ->> 'branch_id')::uuid,
                                         (v_proof ->> 'device_id')::uuid);
  -- D-060 point 2: the original caller's binding for the adapter - the verified
  -- JWT subject (auth.users id) - passed unchanged to every service-only call of
  -- the same request.
  return jsonb_build_object('ok', true,
    'caller_auth_user_id', auth.uid(),
    'organization_id', (v_proof ->> 'organization_id')::uuid,
    'restaurant_id', (v_proof ->> 'restaurant_id')::uuid,
    'branch_id', (v_proof ->> 'branch_id')::uuid,
    'device_id', (v_proof ->> 'device_id')::uuid,
    'role', v_proof ->> 'role',
    'employee_profile_id', (v_proof ->> 'employee_profile_id')::uuid,
    'membership_id', (v_proof ->> 'resolved_membership_id')::uuid,
    'order', v_order_json,
    'attempt', v_attempt_json,
    'terminal', case when v_posture is null then null
                     else jsonb_build_object('lifecycle', v_posture ->> 'lifecycle', 'mode', v_posture ->> 'mode') end,
    'card_terminal_enabled', coalesce((v_posture ->> 'enabled')::boolean, false),
    'server_ts', clock_timestamp());
end;
$$;

create function public.card_attempt_context(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_order_id uuid, p_attempt_id text)
  returns jsonb
  language sql
  volatile
  security invoker
  set search_path = ''
as $$
  select app.card_attempt_context(p_pin_session_id, p_device_id, p_device_session_token, p_order_id, p_attempt_id);
$$;

-- §4.55.10 owner read: exactly the DOMAIN §8.4 allowlist, one mode at a time,
-- LIVE by default and TEST only through the explicit filter. JWT actor with an
-- active org_owner / restaurant_owner / manager / accountant membership covering
-- the scope (member rank only: a platform support session has none).
create function app.owner_card_attempts(
  p_organization_id uuid, p_restaurant_id uuid, p_branch_id uuid,
  p_from timestamptz, p_to timestamptz, p_mode text default 'live')
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_actor uuid := app.current_app_user_id();
  v_rows jsonb;
begin
  if v_actor is null then
    raise exception 'owner_card_attempts: authentication required' using errcode = '42501';
  end if;
  if p_organization_id is null then
    raise exception 'owner_card_attempts: organization is required' using errcode = '42501';
  end if;
  if p_mode is null or p_mode not in ('live', 'test') then
    raise exception 'owner_card_attempts: mode must be live or test' using errcode = '22023';
  end if;
  if p_from is null or p_to is null or p_from >= p_to or p_to - p_from > interval '93 days' then
    raise exception 'owner_card_attempts: a bounded range of at most 93 days is required' using errcode = '22023';
  end if;
  if app.actor_rank_in_scope(p_organization_id, p_restaurant_id, p_branch_id) = 0 then
    raise exception 'owner_card_attempts: caller has no active membership covering the requested scope'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.memberships m
     where m.app_user_id = v_actor
       and m.organization_id = p_organization_id
       and m.status = 'active'
       and m.deleted_at is null
       and m.role in ('manager', 'restaurant_owner', 'org_owner', 'accountant')
       and (m.restaurant_id is null or m.restaurant_id = p_restaurant_id)
       and (m.branch_id is null or m.branch_id = p_branch_id)
  ) then
    return jsonb_build_object('ok', false, 'error', 'permission_denied', 'entity', 'owner_card_attempts');
  end if;
  select coalesce(jsonb_agg(r.row_json order by r.created_at desc, r.id desc), '[]'::jsonb) into v_rows
  from (
    select a.created_at, a.id,
      jsonb_build_object(
        'id', a.id, 'local_operation_id', a.local_operation_id, 'organization_id', a.organization_id,
        'restaurant_id', a.restaurant_id, 'branch_id', a.branch_id, 'device_id', a.device_id,
        'order_id', a.order_id, 'mode', a.mode, 'state', a.state,
        'classification', d ->> 'classification', 'recorded', (d ->> 'recorded')::boolean,
        'payment_id', (d ->> 'payment_id')::uuid, 'reason', d ->> 'reason',
        'recoverable', (d ->> 'recoverable')::boolean,
        'amount_minor', a.amount_minor, 'currency_code', a.currency_code,
        'shift_id', a.shift_id, 'cash_drawer_session_id', a.cash_drawer_session_id,
        'initiated_by_employee_profile_id', a.initiated_by_employee_profile_id,
        'initiated_by_membership_id', a.initiated_by_membership_id,
        'provider_approved_at', a.provider_approved_at, 'card_last4', a.card_last4,
        'card_brand_code', a.card_brand_code, 'approval_type', a.approval_type,
        'provider_return_code', a.provider_return_code, 'provider_return_class', a.provider_return_class,
        'provider_status_code', a.provider_status_code, 'provider_anomaly_code', a.provider_anomaly_code,
        'charge_may_exist', a.charge_may_exist, 'refusal_code', a.refusal_code,
        'recording_refused_at', a.recording_refused_at, 'recording_resume_count', a.recording_resume_count,
        'recording_refusal_history', a.recording_refusal_history,
        'recording_resume_history', a.recording_resume_history,
        'release_requested_at', a.release_requested_at, 'released_at', a.released_at,
        'last_lookup_at', a.last_lookup_at, 'order_freed_at', a.order_freed_at,
        'order_freed_reason', a.order_freed_reason, 'confirmation_source', a.confirmation_source,
        'resolution', a.resolution, 'resolved_at', a.resolved_at, 'created_at', a.created_at,
        'finished_at', a.finished_at)
      || case when p_mode = 'test'
              then jsonb_build_object('retention_until', a.retention_until, 'incident_hold_at', a.incident_hold_at)
              else '{}'::jsonb end as row_json
    from app.card_provider_attempts a
    cross join lateral (select app.card_attempt_derive(a) as d) x
    where a.organization_id = p_organization_id
      and (p_restaurant_id is null or a.restaurant_id = p_restaurant_id)
      and (p_branch_id is null or a.branch_id = p_branch_id)
      and a.mode = p_mode
      and a.created_at >= p_from and a.created_at < p_to
    order by a.created_at desc, a.id desc
    limit 500
  ) r;
  return jsonb_build_object('ok', true, 'entity', 'owner_card_attempts', 'mode', p_mode,
    'rows', v_rows, 'count', jsonb_array_length(v_rows));
end;
$$;

create function public.owner_card_attempts(
  p_organization_id uuid, p_restaurant_id uuid, p_branch_id uuid,
  p_from timestamptz, p_to timestamptz, p_mode text default 'live')
  returns jsonb
  language sql
  stable
  security invoker
  set search_path = ''
as $$
  select app.owner_card_attempts(p_organization_id, p_restaurant_id, p_branch_id, p_from, p_to, p_mode);
$$;


-- ----------------------------------------------------------------------------
-- 6. Service-only RPCs (service_role on both layers; called by the 001E ledger
--    module only after the caller-scoped context proof returned ok).
-- ----------------------------------------------------------------------------
-- 6.1 The claim (§4.55.4 steps (3)–(4)). Lock order: terminal lock → shared
-- purge barrier → the proof's identity-row locks → full-identity lock →
-- lock-free identity reads → orders → shifts → cash_drawer_sessions → insert.
-- D-060 point 2: p_caller_auth_user_id is the original caller's binding (early
-- check before any lock; re-checked after the full-identity lock and, for LIVE,
-- after the orders / shifts / drawers locks, before the refusal evidence or the
-- insert).
create function app.card_attempt_claim(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_attempt_id text,
  p_mode text, p_amount_minor bigint, p_currency_code text, p_order_id uuid, p_expected_revision integer,
  p_environment text, p_terminals jsonb, p_credentials jsonb, p_key_format_version text,
  p_caller_auth_user_id uuid)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_org uuid;
  v_proof jsonb;
  v_rest uuid;
  v_branch uuid;
  v_emp uuid;
  v_membership uuid;
  v_rev app.card_payments_pilot_revisions;
  v_map app.payment_terminals;
  v_mismatch text;
  v_existing app.card_provider_attempts;
  v_status_digest bytea;
  v_dup_digest bytea;
  v_query_key text;
  v_dup_key text;
  v_order public.orders;
  v_shift_id uuid;
  v_drawer_id uuid;
  v_tenant_currency text;
  v_row app.card_provider_attempts;
  v_constraint text;
  v_refusal text;
  v_detail text;
  v_denial text;
begin
  -- (0) request shape — no lock, no write.
  if p_attempt_id is null
     or p_attempt_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     or p_mode is null or p_mode not in ('test', 'live')
     or p_amount_minor is null or p_amount_minor not between 1 and 99999999999
     or p_currency_code is null or p_currency_code !~ '^[A-Z]{3}$'
     or (p_mode = 'test' and (p_order_id is not null or p_expected_revision is not null))
     or (p_mode = 'live' and (p_order_id is null or p_expected_revision is null)) then
    return jsonb_build_object('ok', false, 'error', 'invalid_request', 'server_ts', clock_timestamp());
  end if;
  -- (0b) D-060 point 2, early: the original caller's binding - before any lock,
  --      proof, evidence write or renewal.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  -- (1) the key formatter must be one of the closed candidate set (M7): an
  --     unknown or unselected version is refused before any lock or row.
  if p_key_format_version is null
     or p_key_format_version not in ('alpha16-l20-v1', 'alpha16-l24-v1', 'alpha16-l32-v1') then
    return jsonb_build_object('ok', false, 'error', 'provider_unavailable', 'server_ts', clock_timestamp());
  end if;
  -- (2) terminal / device admission lock first (organization read lock-free
  --     from the device row; the proof re-verifies the scope), then the shared
  --     purge barrier.
  select d.organization_id into v_org from public.devices d where d.id = p_device_id;
  if v_org is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_session', 'server_ts', clock_timestamp());
  end if;
  perform app.card_terminal_lock(v_org, p_device_id);
  perform pg_advisory_xact_lock_shared(hashtextextended('card-purge/v1', 0));
  -- (3) the write-time proof (no JWT gate, no renewal).
  v_proof := app.card_attempt_proof(p_pin_session_id, p_device_id, p_device_session_token, false);
  if (v_proof ->> 'ok') is distinct from 'true' then
    if v_proof ->> 'error' = 'permission_denied' and (v_proof ->> 'proven_scope')::boolean then
      perform app.card_denial_evidence(p_mode, (v_proof ->> 'organization_id')::uuid,
        (v_proof ->> 'restaurant_id')::uuid, (v_proof ->> 'branch_id')::uuid,
        (v_proof ->> 'employee_profile_id')::uuid, p_device_id, null, 'claim', 'permission_denied');
    end if;
    return jsonb_build_object('ok', false, 'error', coalesce(v_proof ->> 'error', 'invalid_session'),
                              'server_ts', clock_timestamp());
  end if;
  if (v_proof ->> 'organization_id')::uuid <> v_org then
    return jsonb_build_object('ok', false, 'error', 'invalid_session', 'server_ts', clock_timestamp());
  end if;
  v_rest := (v_proof ->> 'restaurant_id')::uuid;
  v_branch := (v_proof ->> 'branch_id')::uuid;
  v_emp := (v_proof ->> 'employee_profile_id')::uuid;
  v_membership := (v_proof ->> 'resolved_membership_id')::uuid;
  -- (4) the full-identity lock, before the replay, the identity reads and any
  --     orders lock (D-058 point 5).
  perform app.card_identity_lock(v_org, p_device_id, p_attempt_id);
  -- (4b) D-060 point 2: the caller check again after the terminal, barrier and
  --      identity lock waits, before the configuration events and the replay.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  -- (5) configuration checks (§4.55.4 step (3)).
  v_rev := app.card_pilot_revision_current();
  if v_rev.revision is null or not v_rev.enabled or v_rev.window_until <= now()
     or v_rev.organization_id <> v_org or v_rev.restaurant_id <> v_rest or v_rev.branch_id <> v_branch
     or v_rev.mode <> p_mode then
    return jsonb_build_object('ok', false, 'error', 'card_payments_disabled', 'server_ts', clock_timestamp());
  end if;
  select * into v_map from app.payment_terminals t
    where t.organization_id = v_org and t.device_id = p_device_id
      and t.deleted_at is null and t.lifecycle <> 'retired';
  if not found or v_map.lifecycle <> 'enabled' then
    return jsonb_build_object('ok', false, 'error', 'card_payments_disabled', 'server_ts', clock_timestamp());
  end if;
  v_mismatch := case when v_map.mode <> p_mode then 'mapping_mode'
                     else app.card_config_mismatch(p_mode, v_rest, v_map.terminal_ref, v_map.credential_ref,
                                                   p_environment, p_terminals, p_credentials) end;
  if v_mismatch is not null then
    perform app.card_private_event_write(v_org, v_rest, v_branch, null, p_mode,
      'security.card_credential_mismatch', 'employee', 'employee', null, null, v_emp, p_device_id, null,
      jsonb_build_object('check', v_mismatch, 'source', 'claim'));
    return jsonb_build_object('ok', false, 'error', 'card_payments_disabled', 'server_ts', clock_timestamp());
  end if;
  if p_mode = 'test' then
    if v_rev.max_test_amount_minor is null then
      return jsonb_build_object('ok', false, 'error', 'card_payments_disabled', 'server_ts', clock_timestamp());
    end if;
    select coalesce(r.currency_override, o.default_currency)::text into v_tenant_currency
      from public.restaurants r join public.organizations o on o.id = r.organization_id
      where r.id = v_rest and r.organization_id = v_org;
    v_detail := case when p_currency_code is distinct from v_tenant_currency then 'currency_not_supported'
                     when p_amount_minor > v_rev.max_test_amount_minor then 'max_test_amount_exceeded' end;
    if v_detail is not null then
      perform app.card_denial_evidence('test', v_org, v_rest, v_branch, v_emp, p_device_id, null, 'claim', v_detail);
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', v_detail,
                                'server_ts', clock_timestamp());
    end if;
  elsif v_rev.max_live_amount_minor is null then
    return jsonb_build_object('ok', false, 'error', 'card_payments_disabled', 'server_ts', clock_timestamp());
  end if;
  -- (6) the idempotent replay: an existing attempt of the identity answers its
  --     own state; different frozen fields are a conflict (no ledger change).
  select * into v_existing from app.card_provider_attempts a
    where a.organization_id = v_org and a.device_id = p_device_id and a.local_operation_id = p_attempt_id;
  if found then
    if v_existing.mode <> p_mode or v_existing.order_id is distinct from p_order_id
       or v_existing.amount_minor <> p_amount_minor or v_existing.currency_code <> p_currency_code then
      return jsonb_build_object('ok', false, 'error', 'conflict', 'attempt_id', v_existing.local_operation_id,
                                'attempt_state', v_existing.state, 'server_ts', clock_timestamp());
    end if;
    return app.card_attempt_envelope(v_existing) || jsonb_build_object(
      'claim_created', false, 'replayed', true, 'attempt_row_id', v_existing.id,
      'organization_id', v_existing.organization_id, 'restaurant_id', v_existing.restaurant_id,
      'device_id', v_existing.device_id, 'local_operation_id', v_existing.local_operation_id,
      'mode', v_existing.mode, 'terminal_ref', v_existing.terminal_ref, 'credential_ref', v_existing.credential_ref,
      'start_deadline_at', v_existing.start_deadline_at);
  end if;
  -- (7) the identity check (D-057 point 1; D-058 points 2 and 7): no sync row,
  --     payment or tombstone of the identity, no digest / key collision.
  v_status_digest := app.card_identity_digest('card-status-key/v1', v_org, p_device_id, p_attempt_id);
  v_dup_digest := app.card_identity_digest('card-duplicate-key/v1', v_org, p_device_id, p_attempt_id);
  v_query_key := app.card_provider_key(v_status_digest, p_key_format_version);
  v_dup_key := app.card_provider_key(v_dup_digest, p_key_format_version);
  if exists (select 1 from public.sync_operations so
              where so.organization_id = v_org and so.device_id = p_device_id and so.local_operation_id = p_attempt_id)
     or exists (select 1 from public.payments p
                 where p.device_id = p_device_id and p.local_operation_id = p_attempt_id)
     or exists (select 1 from app.card_attempt_identity_tombstones t
                 where (t.organization_id = v_org and t.device_id = p_device_id and t.local_operation_id = p_attempt_id)
                    or t.provider_status_digest in (v_status_digest, v_dup_digest)
                    or t.provider_duplicate_digest in (v_status_digest, v_dup_digest)
                    or t.provider_query_key in (v_query_key, v_dup_key)
                    or t.provider_duplicate_key in (v_query_key, v_dup_key))
     or exists (select 1 from app.card_provider_attempts a
                 where a.provider_status_digest in (v_status_digest, v_dup_digest)
                    or a.provider_duplicate_digest in (v_status_digest, v_dup_digest)
                    or a.provider_query_key in (v_query_key, v_dup_key)
                    or a.provider_duplicate_key in (v_query_key, v_dup_key)) then
    return jsonb_build_object('ok', false, 'error', 'conflict', 'detail', 'identity_in_use',
                              'server_ts', clock_timestamp());
  end if;
  -- (8) LIVE preconditions under the orders row FOR UPDATE (the lock
  --     app.record_payment takes first); each read is its own statement after
  --     the lock returned, so READ COMMITTED sees every committed payment.
  if p_mode = 'live' then
    select * into v_order from public.orders o
      where o.id = p_order_id and o.organization_id = v_org and o.branch_id = v_branch and o.deleted_at is null
      for update;
    if not found then
      v_refusal := 'precondition_failed'; v_detail := 'ineligible_order_state';
    elsif v_order.grand_total_minor <= 0 then
      v_refusal := 'order_not_chargeable';
    elsif exists (select 1 from public.payments p
                   where p.organization_id = v_org and p.order_id = p_order_id
                     and p.status = 'completed' and p.deleted_at is null) then
      v_refusal := 'order_already_settled';
    elsif app.order_is_fully_settled(v_org, p_order_id) then
      v_refusal := 'order_already_settled';
    elsif app.card_order_claim_active(v_org, p_order_id) then
      v_refusal := 'payment_in_progress';
    elsif v_order.status not in ('submitted', 'accepted', 'preparing', 'ready', 'served') then
      v_refusal := 'precondition_failed'; v_detail := 'ineligible_order_state';
    elsif v_order.revision <> p_expected_revision then
      v_refusal := 'conflict';
    elsif v_order.grand_total_minor <> p_amount_minor or v_order.currency_code <> p_currency_code then
      v_refusal := 'amount_mismatch';
    elsif p_amount_minor > v_rev.max_live_amount_minor then
      v_refusal := 'precondition_failed'; v_detail := 'max_live_amount_exceeded';
    end if;
    if v_refusal is null then
      select s.id into v_shift_id from public.shifts s
        where s.organization_id = v_org and s.branch_id = v_branch and s.device_id = p_device_id
          and s.status = 'open'
        for update limit 1;
      if v_shift_id is null then
        v_refusal := 'precondition_failed'; v_detail := 'no_open_shift';
      else
        select c.id into v_drawer_id from public.cash_drawer_sessions c
          where c.organization_id = v_org and c.shift_id = v_shift_id and c.status = 'active'
          for update limit 1;
        if v_drawer_id is null then
          v_refusal := 'precondition_failed'; v_detail := 'no_active_drawer';
        end if;
      end if;
    end if;
    -- (8b) D-060 point 2, final: after the orders / shifts / drawers lock waits,
    --      before the refusal evidence or the insert.
    v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
    if v_denial is not null then
      return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
    end if;
    if v_refusal is not null then
      if v_refusal = 'precondition_failed' then
        perform app.card_denial_evidence('live', v_org, v_rest, v_branch, v_emp, p_device_id, null, 'claim', v_detail);
      end if;
      return jsonb_build_object('ok', false, 'error', v_refusal, 'server_ts', clock_timestamp())
             || case when v_detail is not null then jsonb_build_object('detail', v_detail) else '{}'::jsonb end;
    end if;
  end if;
  -- (9) the claim: the fresh sent row with its digests, keys and frozen context.
  begin
    insert into app.card_provider_attempts as a (
      organization_id, restaurant_id, branch_id, device_id, local_operation_id, order_id, shift_id,
      cash_drawer_session_id, initiated_by_employee_profile_id, initiated_by_membership_id, mode, state,
      amount_minor, currency_code, expected_revision, terminal_ref, credential_ref,
      provider_status_digest, provider_duplicate_digest, provider_key_format_version,
      provider_query_key, provider_duplicate_key, retention_until, start_deadline_at)
    values (
      v_org, v_rest, v_branch, p_device_id, p_attempt_id, p_order_id, v_shift_id,
      v_drawer_id, v_emp, v_membership, p_mode, 'sent',
      p_amount_minor, p_currency_code, case when p_mode = 'live' then p_expected_revision end,
      v_map.terminal_ref, v_map.credential_ref,
      v_status_digest, v_dup_digest, p_key_format_version, v_query_key, v_dup_key,
      case when p_mode = 'test' then clock_timestamp() + interval '90 days' end,
      clock_timestamp() + interval '120 seconds')
    on conflict (organization_id, device_id, local_operation_id) do nothing
    returning a.* into v_row;
  exception when unique_violation then
    -- M9: only the key / digest constraints (identity_in_use) and the one
    -- claim per order (payment_in_progress) are mapped; anything else raises.
    get stacked diagnostics v_constraint = constraint_name;
    if v_constraint in ('card_attempts_status_digest_key', 'card_attempts_duplicate_digest_key',
                        'card_attempts_query_key_key', 'card_attempts_duplicate_key_key') then
      return jsonb_build_object('ok', false, 'error', 'conflict', 'detail', 'identity_in_use',
                                'server_ts', clock_timestamp());
    elsif v_constraint = 'card_attempts_one_claim_per_order' then
      return jsonb_build_object('ok', false, 'error', 'payment_in_progress', 'server_ts', clock_timestamp());
    end if;
    raise;
  end;
  if v_row.id is null then
    -- the identity backstop (a concurrent winner): answer its row as a replay.
    select * into v_existing from app.card_provider_attempts a
      where a.organization_id = v_org and a.device_id = p_device_id and a.local_operation_id = p_attempt_id;
    if v_existing.mode <> p_mode or v_existing.order_id is distinct from p_order_id
       or v_existing.amount_minor <> p_amount_minor or v_existing.currency_code <> p_currency_code then
      return jsonb_build_object('ok', false, 'error', 'conflict', 'attempt_id', v_existing.local_operation_id,
                                'attempt_state', v_existing.state, 'server_ts', clock_timestamp());
    end if;
    return app.card_attempt_envelope(v_existing) || jsonb_build_object(
      'claim_created', false, 'replayed', true, 'attempt_row_id', v_existing.id,
      'organization_id', v_existing.organization_id, 'restaurant_id', v_existing.restaurant_id,
      'device_id', v_existing.device_id, 'local_operation_id', v_existing.local_operation_id,
      'mode', v_existing.mode, 'terminal_ref', v_existing.terminal_ref, 'credential_ref', v_existing.credential_ref,
      'start_deadline_at', v_existing.start_deadline_at);
  end if;
  if p_mode = 'live' then
    perform app.card_audit_write(v_org, v_rest, v_branch, v_emp, p_device_id, 'card_attempt.started',
      jsonb_build_object('attempt_state', 'sent', 'mode', 'live',
                         'amount_minor', p_amount_minor, 'currency_code', p_currency_code));
  end if;
  return app.card_attempt_envelope(v_row) || jsonb_build_object(
    'claim_created', true, 'replayed', false, 'attempt_row_id', v_row.id,
    'organization_id', v_row.organization_id, 'restaurant_id', v_row.restaurant_id,
    'device_id', v_row.device_id, 'local_operation_id', v_row.local_operation_id,
    'mode', v_row.mode, 'terminal_ref', v_row.terminal_ref, 'credential_ref', v_row.credential_ref,
    'start_deadline_at', v_row.start_deadline_at,
    'provider_key_format_version', v_row.provider_key_format_version,
    'provider_query_key', v_row.provider_query_key,
    'provider_duplicate_key', v_row.provider_duplicate_key);
end;
$$;

create function public.card_attempt_claim(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_attempt_id text,
  p_mode text, p_amount_minor bigint, p_currency_code text, p_order_id uuid, p_expected_revision integer,
  p_environment text, p_terminals jsonb, p_credentials jsonb, p_key_format_version text,
  p_caller_auth_user_id uuid)
  returns jsonb
  language sql
  volatile
  security invoker
  set search_path = ''
as $$
  select app.card_attempt_claim(p_pin_session_id, p_device_id, p_device_session_token, p_attempt_id,
    p_mode, p_amount_minor, p_currency_code, p_order_id, p_expected_revision,
    p_environment, p_terminals, p_credentials, p_key_format_version, p_caller_auth_user_id);
$$;


-- 6.2 The adapter's read of one attempt (§4.55.5 / §4.55.6). For an attempt
-- the adapter may still call the provider for (sent / unknown / released, no
-- resolution) it re-validates the FROZEN terminal and credential references
-- against the passed configuration maps; a missing or mismatched record writes
-- security.card_credential_mismatch and answers provider_unavailable.
-- D-060 point 2: p_caller_auth_user_id is the original caller's binding (early
-- check before the proof; final check after the proof's lock waits - the attempt
-- read takes no lock - before the attempt lookup, the credential event and the
-- answer).
create function app.card_attempt_adapter_read(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_attempt_id text,
  p_environment text, p_terminals jsonb, p_credentials jsonb, p_caller_auth_user_id uuid)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_proof jsonb;
  v_resolved jsonb;
  a app.card_provider_attempts;
  v_mismatch text;
  v_denial text;
begin
  if p_attempt_id is null
     or p_attempt_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request', 'server_ts', clock_timestamp());
  end if;
  -- D-060 point 2, early: the original caller's binding.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  v_proof := app.card_attempt_proof(p_pin_session_id, p_device_id, p_device_session_token, false);
  if (v_proof ->> 'ok') is distinct from 'true' then
    return jsonb_build_object('ok', false, 'error', coalesce(v_proof ->> 'error', 'invalid_session'),
                              'server_ts', clock_timestamp());
  end if;
  -- D-060 point 2, final: after the proof's lock waits (the attempt read below takes no lock), before
  -- any attempt lookup, the credential event and the answer.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  v_resolved := app.card_attempt_resolve(v_proof, p_attempt_id);
  if not (v_resolved ->> 'ok')::boolean then
    return jsonb_build_object('ok', false, 'error', v_resolved ->> 'error', 'server_ts', clock_timestamp());
  end if;
  select * into a from app.card_provider_attempts x where x.id = (v_resolved ->> 'attempt_row_id')::uuid;
  if a.state in ('sent', 'unknown', 'released') and a.resolution is null then
    v_mismatch := app.card_config_mismatch(a.mode, a.restaurant_id, a.terminal_ref, a.credential_ref,
                                           p_environment, p_terminals, p_credentials);
    if v_mismatch is not null then
      perform app.card_private_event_write(a.organization_id, a.restaurant_id, a.branch_id, a.id, a.mode,
        'security.card_credential_mismatch', 'employee', 'employee', null, null,
        (v_proof ->> 'employee_profile_id')::uuid, (v_proof ->> 'device_id')::uuid, null,
        jsonb_build_object('check', v_mismatch, 'source', 'adapter_read'));
      return jsonb_build_object('ok', false, 'error', 'provider_unavailable', 'attempt_id', a.local_operation_id,
                                'attempt_state', a.state, 'server_ts', clock_timestamp());
    end if;
  end if;
  return app.card_attempt_envelope(a) || jsonb_build_object(
    'attempt_row_id', a.id, 'organization_id', a.organization_id, 'restaurant_id', a.restaurant_id,
    'device_id', a.device_id, 'local_operation_id', a.local_operation_id, 'mode', a.mode,
    'terminal_ref', a.terminal_ref, 'credential_ref', a.credential_ref,
    'provider_key_format_version', a.provider_key_format_version,
    'provider_query_key', a.provider_query_key, 'provider_duplicate_key', a.provider_duplicate_key,
    'start_deadline_at', a.start_deadline_at, 'start_deadline_passed', a.start_deadline_at <= clock_timestamp(),
    'auto_poll_count', a.auto_poll_count, 'last_lookup_at', a.last_lookup_at,
    'release_requested_at', a.release_requested_at);
end;
$$;

create function public.card_attempt_adapter_read(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_attempt_id text,
  p_environment text, p_terminals jsonb, p_credentials jsonb, p_caller_auth_user_id uuid)
  returns jsonb
  language sql
  volatile
  security invoker
  set search_path = ''
as $$
  select app.card_attempt_adapter_read(p_pin_session_id, p_device_id, p_device_session_token, p_attempt_id,
    p_environment, p_terminals, p_credentials, p_caller_auth_user_id);
$$;

-- 6.3 The provider's fact (§4.55.4 – §4.55.6), scope-bound (D-056 point 4): no
-- session proof (the provider fact must survive a lapsed session); the row is
-- addressed by its server id and written only when the organization, device,
-- identity, mode, amount and currency equal the claim / adapter-read values of
-- the same request. Field rules of D-058 point 10; M1 / M2 / M3 of the packet.
create function app.card_attempt_finish(
  p_attempt_row_id uuid, p_organization_id uuid, p_device_id uuid, p_local_operation_id text,
  p_mode text, p_amount_minor bigint, p_currency_code text, p_source text, p_outcome text,
  p_provider_fields jsonb, p_poll_source text)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  a app.card_provider_attempts;
  n app.card_provider_attempts;
  v_f jsonb := case when jsonb_typeof(p_provider_fields) = 'object' then p_provider_fields else '{}'::jsonb end;
  v_now timestamptz := clock_timestamp();
  v_key text;
  v_val jsonb;
  v_text text;
  v_rule text;
  v_canon text;
  v_test_discard constant text[] := array['provider_reference', 'approval_number', 'voucher_number', 'deposit_id',
                                          'card_last4', 'card_brand_code', 'pan_entry_mode', 'payment_method_code'];
  v_stored jsonb := '{}'::jsonb;
  v_essential_failed boolean := false;
  v_tip_failed boolean := false;
  v_error_flag boolean;
  v_return_code integer;
  v_approval_type text;
  v_phone boolean;
  v_status_code text;
  v_amount bigint;
  v_currency text;
  v_tip bigint;
  v_class text;
  v_target text;
  v_anomaly text;
  v_refusal text;
  v_before jsonb;
  v_after jsonb;
  v_updated integer;
begin
  if p_attempt_row_id is null or p_source is null or p_outcome is null
     or not ((p_source = 'commit' and p_outcome in ('approved', 'declined', 'unknown', 'anomaly'))
             or (p_source = 'lookup' and p_outcome in ('approved', 'declined', 'anomaly', 'not_found', 'pending', 'failed'))
             or (p_source = 'release' and p_outcome in ('released', 'release_failed')))
     or (p_poll_source is not null and p_poll_source not in ('auto', 'operator')) then
    return jsonb_build_object('ok', false, 'error', 'invalid_request', 'server_ts', clock_timestamp());
  end if;
  select * into a from app.card_provider_attempts x where x.id = p_attempt_row_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'attempt_not_found', 'server_ts', clock_timestamp());
  end if;
  if a.organization_id is distinct from p_organization_id or a.device_id is distinct from p_device_id
     or a.local_operation_id is distinct from p_local_operation_id or a.mode is distinct from p_mode
     or a.amount_minor is distinct from p_amount_minor or a.currency_code is distinct from p_currency_code then
    perform app.card_private_event_write(a.organization_id, a.restaurant_id, a.branch_id, a.id, a.mode,
      'security.card_finish_scope_mismatch', 'adapter', 'card_adapter', null, null, null, a.device_id, null,
      jsonb_build_object(
        'organization_id', a.organization_id is distinct from p_organization_id,
        'device_id', a.device_id is distinct from p_device_id,
        'local_operation_id', a.local_operation_id is distinct from p_local_operation_id,
        'mode', a.mode is distinct from p_mode,
        'amount_minor', a.amount_minor is distinct from p_amount_minor,
        'currency_code', a.currency_code is distinct from p_currency_code));
    return jsonb_build_object('ok', false, 'error', 'conflict', 'detail', 'attempt_scope_mismatch',
                              'server_ts', clock_timestamp());
  end if;
  if a.resolution is not null then
    -- A resolved attempt is final: a provider fact still reaching it is evidence
    -- only (a lookup that got no reply carries no provider fact).
    if p_outcome <> 'failed' then
      perform app.card_private_event_write(a.organization_id, a.restaurant_id, a.branch_id, a.id, a.mode,
        'security.card_resolution_contradicted', 'adapter', 'card_adapter', null, null, null, a.device_id, null,
        jsonb_build_object('source', p_source, 'outcome', p_outcome));
    end if;
    return app.card_attempt_envelope(a);
  end if;
  if a.state not in ('sent', 'unknown', 'released') or (p_source = 'commit' and a.state <> 'sent') then
    -- approved / declined are final; a commit reply finishes only a still-sent row.
    return app.card_attempt_envelope(a);
  end if;
  v_before := app.card_attempt_derive(a);
  n := a;

  -- (1) Field rules (D-058 point 10). Absent, JSON null or empty after the
  -- canonical trim = absent (no event). A failing present field writes one
  -- security.card_provider_field_dropped (deduplicated per attempt, field, rule).
  foreach v_key in array array['provider_reference', 'approval_number', 'voucher_number', 'deposit_id',
                               'card_last4', 'card_brand_code', 'pan_entry_mode', 'payment_method_code',
                               'approval_type', 'provider_status_code', 'provider_return_code',
                               'provider_saved_at', 'error_flag', 'phone_authorization', 'tip_amount',
                               'provider_amount', 'provider_currency'] loop
    v_val := v_f -> v_key;
    if v_val is null or v_val = 'null'::jsonb
       or (jsonb_typeof(v_val) = 'string' and app.card_text_absent(v_val #>> '{}')) then
      continue;
    end if;
    if a.mode = 'test' and v_key = any (v_test_discard) then
      continue;
    end if;
    v_rule := null;
    v_text := case when jsonb_typeof(v_val) = 'string' then v_val #>> '{}' end;
    case v_key
      when 'error_flag', 'phone_authorization' then
        if jsonb_typeof(v_val) <> 'boolean' then v_rule := 'format'; end if;
      when 'provider_return_code' then
        if jsonb_typeof(v_val) <> 'number' or (v_val #>> '{}') !~ '^-?[0-9]{1,6}$' then v_rule := 'format'; end if;
      when 'provider_amount', 'tip_amount' then
        if v_text is null or v_text !~ '^(0|[1-9][0-9]{0,8})\.[0-9]{2}$' then v_rule := 'format'; end if;
      when 'provider_currency' then
        if v_text is null or v_text !~ '^[A-Z]{3}$' then v_rule := 'format'; end if;
      when 'provider_saved_at' then
        -- ISO-8601 / RFC 3339 date-time with an explicit offset (up to nine
        -- fraction digits, rounded to microseconds); never a special literal
        -- ('now', 'epoch', 'infinity' ...) or a zone-less local time.
        if v_text is null
           or v_text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[Tt ][0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,9})?([Zz]|[+-][0-9]{2}(:?[0-9]{2})?)$'
           or not pg_input_is_valid(v_text, 'timestamptz') then
          v_rule := 'format';
        end if;
      else
        if v_text is null then
          v_rule := 'format';
        else
          v_rule := app.card_safe_text_failure(v_text, v_key);
          if v_rule is null and v_key = 'card_last4' and app.card_text_canonical(v_text) !~ '^[0-9]{4}$' then
            v_rule := 'charset';
          end if;
        end if;
    end case;
    if v_rule is not null then
      perform app.card_private_event_write(a.organization_id, a.restaurant_id, a.branch_id, a.id, a.mode,
        'security.card_provider_field_dropped', 'adapter', 'card_adapter', null, null, null, a.device_id, null,
        jsonb_build_object('field', v_key, 'rule', v_rule, 'source', p_source));
      if v_key in ('error_flag', 'provider_return_code', 'approval_type', 'phone_authorization',
                   'provider_status_code', 'provider_amount', 'provider_currency') then
        v_essential_failed := true;
      elsif v_key = 'tip_amount' then
        v_tip_failed := true;
      end if;
      continue;
    end if;
    case v_key
      when 'error_flag' then v_error_flag := (v_val #>> '{}')::boolean;
      when 'phone_authorization' then v_phone := (v_val #>> '{}')::boolean;
      when 'provider_return_code' then v_return_code := (v_val #>> '{}')::integer;
      when 'provider_amount' then
        v_amount := split_part(v_text, '.', 1)::bigint * 100 + split_part(v_text, '.', 2)::bigint;
      when 'tip_amount' then
        v_tip := split_part(v_text, '.', 1)::bigint * 100 + split_part(v_text, '.', 2)::bigint;
      when 'provider_currency' then v_currency := v_text;
      when 'provider_saved_at' then v_stored := v_stored || jsonb_build_object(v_key, v_text::timestamptz);
      else
        v_canon := app.card_text_canonical(v_text);
        v_stored := v_stored || jsonb_build_object(v_key, v_canon);
        if v_key = 'approval_type' then v_approval_type := v_canon; end if;
        if v_key = 'provider_status_code' then v_status_code := v_canon; end if;
    end case;
  end loop;
  -- M3: the informational class; never decides anything.
  if v_f ? 'provider_return_class' and v_f -> 'provider_return_class' <> 'null'::jsonb
     and not (jsonb_typeof(v_f -> 'provider_return_class') = 'string'
              and app.card_text_absent(v_f ->> 'provider_return_class')) then
    v_class := case when jsonb_typeof(v_f -> 'provider_return_class') = 'string'
                         and (v_f ->> 'provider_return_class') in ('approved', 'declined', 'error', 'pending', 'not_found',
                                                                     'duplicate', 'phone_authorization', 'unclassified')
                    then v_f ->> 'provider_return_class' else 'unclassified' end;
  end if;

  -- (2) The outcome, validated against the essential inputs (M2): missing
  -- approval input never approves; a found / charge-bearing lookup that is not
  -- readable becomes the out_of_contract anomaly, never a decline.
  if p_source = 'commit' then
    if p_outcome = 'anomaly' then
      v_anomaly := case when v_essential_failed or v_tip_failed then 'out_of_contract'
                        when (v_f ->> 'anomaly_code') in ('amount_mismatch', 'currency_mismatch', 'preauthorization',
                                                            'partial_refund', 'refunded', 'voided', 'out_of_contract')
                        then v_f ->> 'anomaly_code' else 'out_of_contract' end;
    elsif v_tip_failed then
      v_anomaly := 'out_of_contract';
    elsif v_essential_failed then
      v_target := 'unknown';
    elsif p_outcome = 'approved' then
      if v_error_flag is false and v_return_code = 0 and v_approval_type is not null
         and v_phone is not true then
        if coalesce(v_tip, 0) <> 0 then
          v_anomaly := 'amount_mismatch';
        elsif v_amount is not null and v_amount <> a.amount_minor then
          v_anomaly := 'amount_mismatch';
        elsif v_currency is not null and v_currency <> a.currency_code then
          v_anomaly := 'currency_mismatch';
        else
          v_target := 'approved';
        end if;
      else
        v_target := 'unknown';
      end if;
    elsif p_outcome = 'declined' then
      v_target := case when v_approval_type is not null then 'declined' else 'unknown' end;
    else
      v_target := 'unknown';
    end if;
  elsif p_source = 'lookup' then
    if p_outcome = 'anomaly' then
      v_anomaly := case when v_essential_failed or v_tip_failed then 'out_of_contract'
                        when (v_f ->> 'anomaly_code') in ('amount_mismatch', 'currency_mismatch', 'preauthorization',
                                                            'partial_refund', 'refunded', 'voided', 'out_of_contract')
                        then v_f ->> 'anomaly_code' else 'out_of_contract' end;
    elsif p_outcome in ('approved', 'declined') and (v_essential_failed or v_tip_failed) then
      v_anomaly := 'out_of_contract';
    elsif p_outcome = 'approved' then
      if v_status_code is not null and v_amount is not null and v_currency is not null
         and v_error_flag is not true and v_phone is not true then
        if v_amount <> a.amount_minor or coalesce(v_tip, 0) <> 0 then
          v_anomaly := 'amount_mismatch';
        elsif v_currency <> a.currency_code then
          v_anomaly := 'currency_mismatch';
        else
          v_target := 'approved';
        end if;
      else
        v_anomaly := 'out_of_contract';
      end if;
    elsif p_outcome = 'declined' then
      if v_approval_type is not null then
        v_target := 'declined';
      else
        v_anomaly := 'out_of_contract';
      end if;
    end if;
    n.last_lookup_at := v_now;
    if p_poll_source = 'auto' then
      n.auto_poll_count := a.auto_poll_count + 1;
    end if;
  else
    if p_outcome = 'released' and a.state = 'sent' and a.start_deadline_at > v_now then
      v_target := 'released';
    elsif p_outcome = 'release_failed' then
      v_refusal := 'release_failed';
    end if;
  end if;
  -- A sent row past its start deadline with no conclusive outcome is unknown.
  if v_target is null and v_anomaly is null and a.state = 'sent' and a.start_deadline_at <= v_now then
    v_target := 'unknown';
  end if;

  -- (3) Apply. An anomaly moves a sent row to unknown and leaves unknown /
  -- released as they are; a later exact approved / declined clears
  -- charge_may_exist and keeps the anomaly code as history.
  if v_anomaly is not null then
    n.provider_anomaly_code := v_anomaly;
    n.charge_may_exist := true;
    if a.state = 'sent' then
      n.state := 'unknown';
    end if;
  elsif v_target is not null and v_target <> a.state then
    n.state := v_target;
    if v_target in ('approved', 'declined') then
      n.charge_may_exist := false;
    end if;
    if v_target = 'approved' then
      n.provider_approved_at := v_now;
    elsif v_target = 'released' then
      n.released_at := v_now;
    end if;
  end if;
  if v_refusal is not null then
    n.refusal_code := v_refusal;
  end if;
  if a.state = 'sent' and n.state <> 'sent' and a.finished_at is null then
    n.finished_at := v_now;
  end if;
  if v_class is not null then
    n.provider_return_class := v_class;
  end if;
  if v_return_code is not null then
    n.provider_return_code := v_return_code;
  end if;
  n.provider_reference := coalesce(v_stored ->> 'provider_reference', a.provider_reference);
  n.approval_number := coalesce(v_stored ->> 'approval_number', a.approval_number);
  n.voucher_number := coalesce(v_stored ->> 'voucher_number', a.voucher_number);
  n.deposit_id := coalesce(v_stored ->> 'deposit_id', a.deposit_id);
  n.card_last4 := coalesce(v_stored ->> 'card_last4', a.card_last4);
  n.card_brand_code := coalesce(v_stored ->> 'card_brand_code', a.card_brand_code);
  n.pan_entry_mode := coalesce(v_stored ->> 'pan_entry_mode', a.pan_entry_mode);
  n.payment_method_code := coalesce(v_stored ->> 'payment_method_code', a.payment_method_code);
  n.approval_type := coalesce(v_stored ->> 'approval_type', a.approval_type);
  n.provider_status_code := coalesce(v_stored ->> 'provider_status_code', a.provider_status_code);
  n.provider_saved_at := coalesce((v_stored ->> 'provider_saved_at')::timestamptz, a.provider_saved_at);
  update app.card_provider_attempts x set
    state = n.state, provider_anomaly_code = n.provider_anomaly_code, charge_may_exist = n.charge_may_exist,
    provider_approved_at = n.provider_approved_at, released_at = n.released_at, refusal_code = n.refusal_code,
    finished_at = n.finished_at, last_lookup_at = n.last_lookup_at, auto_poll_count = n.auto_poll_count,
    provider_return_class = n.provider_return_class, provider_return_code = n.provider_return_code,
    provider_reference = n.provider_reference, approval_number = n.approval_number,
    voucher_number = n.voucher_number, deposit_id = n.deposit_id, card_last4 = n.card_last4,
    card_brand_code = n.card_brand_code, pan_entry_mode = n.pan_entry_mode,
    payment_method_code = n.payment_method_code, approval_type = n.approval_type,
    provider_status_code = n.provider_status_code, provider_saved_at = n.provider_saved_at
  where x.id = a.id
  returning x.* into n;
  get diagnostics v_updated = row_count;
  if v_updated = 0 then
    select * into n from app.card_provider_attempts x where x.id = a.id;
    return app.card_attempt_envelope(n);
  end if;

  -- (4) Tenant audit, LIVE only: a state or classification change, an anomaly
  -- change, a release_failed refusal — never a stamp- or counter-only write.
  if a.mode = 'live' then
    v_after := app.card_attempt_derive(n);
    if n.state <> a.state or (v_after ->> 'classification') is distinct from (v_before ->> 'classification')
         and (n.provider_anomaly_code is not distinct from a.provider_anomaly_code
              and n.charge_may_exist = a.charge_may_exist) then
      perform app.card_audit_write(n.organization_id, n.restaurant_id, n.branch_id,
        n.initiated_by_employee_profile_id, n.device_id, 'card_attempt.' || n.state,
        jsonb_strip_nulls(jsonb_build_object('attempt_state', n.state, 'refusal_code', n.refusal_code,
          'anomaly_code', n.provider_anomaly_code, 'release_requested', n.release_requested_at is not null)));
    end if;
    if n.provider_anomaly_code is distinct from a.provider_anomaly_code or n.charge_may_exist <> a.charge_may_exist then
      perform app.card_audit_write(n.organization_id, n.restaurant_id, n.branch_id,
        n.initiated_by_employee_profile_id, n.device_id, 'card_attempt.provider_anomaly',
        jsonb_strip_nulls(jsonb_build_object('attempt_state', n.state, 'refusal_code', n.refusal_code,
          'anomaly_code', n.provider_anomaly_code, 'release_requested', n.release_requested_at is not null)));
    end if;
    if v_refusal = 'release_failed' then
      perform app.card_audit_write(n.organization_id, n.restaurant_id, n.branch_id,
        n.initiated_by_employee_profile_id, n.device_id, 'card_attempt.release_failed',
        jsonb_build_object('attempt_state', n.state));
    end if;
  end if;
  return app.card_attempt_envelope(n);
end;
$$;

create function public.card_attempt_finish(
  p_attempt_row_id uuid, p_organization_id uuid, p_device_id uuid, p_local_operation_id text,
  p_mode text, p_amount_minor bigint, p_currency_code text, p_source text, p_outcome text,
  p_provider_fields jsonb, p_poll_source text)
  returns jsonb
  language sql
  volatile
  security invoker
  set search_path = ''
as $$
  select app.card_attempt_finish(p_attempt_row_id, p_organization_id, p_device_id, p_local_operation_id,
    p_mode, p_amount_minor, p_currency_code, p_source, p_outcome, p_provider_fields, p_poll_source);
$$;

-- 6.4 The release request mark (§4.55.6): stamps release_requested_at on each
-- release request of a sent / unknown attempt without a resolution (audited
-- card_attempt.release_requested for LIVE); otherwise answers the envelope.
-- D-060 point 2: p_caller_auth_user_id is the original caller's binding (early
-- check before the proof; again after the proof's lock waits, before the attempt
-- lookup; final check after the attempt row lock).
create function app.card_attempt_mark_release_requested(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_attempt_id text,
  p_caller_auth_user_id uuid)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_proof jsonb;
  v_resolved jsonb;
  a app.card_provider_attempts;
  v_denial text;
begin
  if p_attempt_id is null
     or p_attempt_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request', 'server_ts', clock_timestamp());
  end if;
  -- D-060 point 2, early: the original caller's binding.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  v_proof := app.card_attempt_proof(p_pin_session_id, p_device_id, p_device_session_token, false);
  if (v_proof ->> 'ok') is distinct from 'true' then
    perform app.card_proof_denial_evidence(v_proof, p_device_id, p_attempt_id, 'mark_release_requested');
    return jsonb_build_object('ok', false, 'error', coalesce(v_proof ->> 'error', 'invalid_session'),
                              'server_ts', clock_timestamp());
  end if;
  -- D-060 point 2: again after the proof's lock waits, before any attempt lookup.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  v_resolved := app.card_attempt_resolve(v_proof, p_attempt_id);
  if not (v_resolved ->> 'ok')::boolean then
    return jsonb_build_object('ok', false, 'error', v_resolved ->> 'error', 'server_ts', clock_timestamp());
  end if;
  select * into a from app.card_provider_attempts x where x.id = (v_resolved ->> 'attempt_row_id')::uuid for update;
  -- D-060 point 2, final: after the attempt row lock, before the stamp, audit and envelope.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  if a.state in ('sent', 'unknown') and a.resolution is null then
    update app.card_provider_attempts x set release_requested_at = clock_timestamp()
      where x.id = a.id returning x.* into a;
    if a.mode = 'live' then
      perform app.card_audit_write(a.organization_id, a.restaurant_id, a.branch_id,
        (v_proof ->> 'employee_profile_id')::uuid, (v_proof ->> 'device_id')::uuid,
        'card_attempt.release_requested', jsonb_build_object('attempt_state', a.state));
    end if;
  end if;
  return app.card_attempt_envelope(a);
end;
$$;

create function public.card_attempt_mark_release_requested(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_attempt_id text,
  p_caller_auth_user_id uuid)
  returns jsonb
  language sql
  volatile
  security invoker
  set search_path = ''
as $$
  select app.card_attempt_mark_release_requested(p_pin_session_id, p_device_id, p_device_session_token, p_attempt_id,
    p_caller_auth_user_id);
$$;


-- 6.5 The recording result (§4.55.7): LIVE only. Proves the identity's sync row
-- is the attempt's own canonical recording leg, derives the stored refusal
-- token server-side (the client's code is a hint, never stored), and audits
-- card_attempt.recording_refused only after the refusal is persisted.
-- D-060 point 2: p_caller_auth_user_id is the original caller's binding (early
-- check before the proof; again after the proof's lock waits, before the attempt
-- lookup and the first envelope answer; final check after the sync_operations ->
-- attempt row locks, before any write).
create function app.card_attempt_mark_recording_result(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_attempt_id text, p_refusal_code text,
  p_caller_auth_user_id uuid)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_proof jsonb;
  v_resolved jsonb;
  a app.card_provider_attempts;
  v_so public.sync_operations;
  v_canonical jsonb;
  v_own boolean;
  v_token text;
  v_written app.card_provider_attempts;
  v_denial text;
begin
  if p_attempt_id is null
     or p_attempt_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request', 'server_ts', clock_timestamp());
  end if;
  -- D-060 point 2, early: the original caller's binding.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  v_proof := app.card_attempt_proof(p_pin_session_id, p_device_id, p_device_session_token, false);
  if (v_proof ->> 'ok') is distinct from 'true' then
    perform app.card_proof_denial_evidence(v_proof, p_device_id, p_attempt_id, 'mark_recording_result');
    return jsonb_build_object('ok', false, 'error', coalesce(v_proof ->> 'error', 'invalid_session'),
                              'server_ts', clock_timestamp());
  end if;
  -- D-060 point 2: again after the proof's lock waits, before any attempt lookup and the first
  -- envelope answer.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  v_resolved := app.card_attempt_resolve(v_proof, p_attempt_id);
  if not (v_resolved ->> 'ok')::boolean then
    return jsonb_build_object('ok', false, 'error', v_resolved ->> 'error', 'server_ts', clock_timestamp());
  end if;
  select * into a from app.card_provider_attempts x where x.id = (v_resolved ->> 'attempt_row_id')::uuid;
  if a.mode <> 'live' or a.state <> 'approved' or a.resolution is not null
     or app.card_attempt_payment_id(a) is not null then
    return app.card_attempt_envelope(a);
  end if;
  -- Lock order: the identity's sync row, then the attempt row.
  select * into v_so from public.sync_operations so
    where so.organization_id = a.organization_id and so.device_id = a.device_id
      and so.local_operation_id = a.local_operation_id
    for update;
  select * into a from app.card_provider_attempts x where x.id = a.id for update;
  -- D-060 point 2, final: after the sync_operations -> attempt row locks, before any write.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  if a.state <> 'approved' or a.resolution is not null or app.card_attempt_payment_id(a) is not null then
    return app.card_attempt_envelope(a);
  end if;
  v_canonical := jsonb_build_object('order_id', a.order_id::text, 'tender_type', 'card',
                                    'amount_tendered_minor', a.amount_minor);
  if v_so.id is not null then
    v_own := v_so.operation_type = 'payment.create'
             and v_so.payload = v_canonical
             and v_so.payload_fingerprint = md5('payment.create' || '|' || v_canonical::text);
  end if;
  if v_so.id is null or (v_own and v_so.status in ('pending', 'in_flight', 'created')) then
    perform app.card_denial_evidence('live', a.organization_id, a.restaurant_id, a.branch_id,
      (v_proof ->> 'employee_profile_id')::uuid, (v_proof ->> 'device_id')::uuid, a.id,
      'mark_recording_result', 'no_recording_attempt');
    return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'no_recording_attempt',
                              'attempt_id', a.local_operation_id, 'attempt_state', a.state,
                              'server_ts', clock_timestamp());
  end if;
  if not v_own then
    v_token := 'nonrecoverable_refusal';
  elsif v_so.status = 'conflict' then
    v_token := 'conflict';
  elsif v_so.status = 'rejected' then
    v_token := v_so.rejection_reason;
    if v_so.result ->> 'detail' in ('precondition_failed', 'revoked_employee', 'revoked_device') then
      v_token := v_so.result ->> 'detail';
    end if;
    if v_token is null or v_token not in ('order_not_chargeable', 'conflict', 'precondition_failed',
                                          'revoked_employee', 'permission_denied', 'revoked_device',
                                          'amount_mismatch', 'payment_in_progress', 'card_context_lost',
                                          'provider_recording_refused', 'nonrecoverable_refusal') then
      v_token := 'nonrecoverable_refusal';
    end if;
  else
    -- dead, applied without the strict-join payment, or any other status.
    v_token := 'nonrecoverable_refusal';
  end if;
  if a.refusal_code is distinct from v_token or a.recording_refused_at is null
     or (v_token in ('precondition_failed', 'revoked_employee', 'permission_denied')
         and (a.recording_refused_at < v_so.updated_at
              or a.recording_refused_at
                 < coalesce((a.recording_resume_history -> -1 ->> 'at')::timestamptz, '-infinity'))) then
    update app.card_provider_attempts x
      set refusal_code = v_token, recording_refused_at = clock_timestamp()
      where x.id = a.id
      returning x.* into v_written;
    if v_written.id is not null then
      a := v_written;
      perform app.card_audit_write(a.organization_id, a.restaurant_id, a.branch_id,
        (v_proof ->> 'employee_profile_id')::uuid, (v_proof ->> 'device_id')::uuid,
        'card_attempt.recording_refused', jsonb_build_object('refusal_code', v_token));
    end if;
  end if;
  return app.card_attempt_envelope(a);
end;
$$;

create function public.card_attempt_mark_recording_result(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_attempt_id text, p_refusal_code text,
  p_caller_auth_user_id uuid)
  returns jsonb
  language sql
  volatile
  security invoker
  set search_path = ''
as $$
  select app.card_attempt_mark_recording_result(p_pin_session_id, p_device_id, p_device_session_token,
    p_attempt_id, p_refusal_code, p_caller_auth_user_id);
$$;

-- 6.6 free_order (§4.55.6; D-058 point 9): a manager's evidence-bound free of a
-- LIVE unknown / released attempt with no charge risk, behind the service
-- boundary. Role first (no attempt detail, no evidence); field rules before
-- any attempt lookup (no write); then the attempt under orders → attempt locks.
-- D-060 point 2: p_caller_auth_user_id is the original caller's binding (early
-- check before the proof; again after the proof's lock waits, before the role
-- check and the attempt lookup; final check after the orders -> attempt row
-- locks).
create function app.card_attempt_free_order(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_attempt_id text,
  p_reason text, p_confirmation_source text, p_confirmation_reference text, p_caller_auth_user_id uuid)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_proof jsonb;
  v_resolved jsonb;
  a app.card_provider_attempts;
  v_reason text;
  v_reference text;
  v_detail text;
  v_emp uuid;
  v_device uuid;
  v_denial text;
begin
  if p_attempt_id is null
     or p_attempt_id !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request', 'server_ts', clock_timestamp());
  end if;
  -- D-060 point 2, early: the original caller's binding.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  v_proof := app.card_attempt_proof(p_pin_session_id, p_device_id, p_device_session_token, false);
  if (v_proof ->> 'ok') is distinct from 'true' then
    return jsonb_build_object('ok', false, 'error', coalesce(v_proof ->> 'error', 'invalid_session'),
                              'server_ts', clock_timestamp());
  end if;
  -- D-060 point 2: again after the proof's lock waits, before any attempt lookup.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  if v_proof ->> 'role' not in ('manager', 'restaurant_owner', 'org_owner') then
    return jsonb_build_object('ok', false, 'error', 'permission_denied', 'server_ts', clock_timestamp());
  end if;
  v_emp := (v_proof ->> 'employee_profile_id')::uuid;
  v_device := (v_proof ->> 'device_id')::uuid;
  if (not app.card_text_absent(p_reason) and not app.card_safe_text_ok(p_reason, 'reason'))
     or (not app.card_text_absent(p_confirmation_reference)
         and not app.card_safe_text_ok(p_confirmation_reference, 'confirmation_reference')) then
    return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'out_of_contract',
                              'server_ts', clock_timestamp());
  end if;
  v_reason := case when p_reason is null then null else app.card_text_canonical(p_reason) end;
  v_reference := case when p_confirmation_reference is null then null
                      else app.card_text_canonical(p_confirmation_reference) end;
  v_resolved := app.card_attempt_resolve(v_proof, p_attempt_id);
  if not (v_resolved ->> 'ok')::boolean then
    return jsonb_build_object('ok', false, 'error', v_resolved ->> 'error', 'server_ts', clock_timestamp());
  end if;
  select * into a from app.card_provider_attempts x where x.id = (v_resolved ->> 'attempt_row_id')::uuid;
  if a.mode = 'live' then
    perform 1 from public.orders o where o.organization_id = a.organization_id and o.id = a.order_id for update;
  end if;
  select * into a from app.card_provider_attempts x where x.id = a.id for update;
  -- D-060 point 2, final: after the orders -> attempt row locks, before the envelope, the
  -- evidence and the free.
  v_denial := app.card_caller_binding_denial(p_caller_auth_user_id);
  if v_denial is not null then
    return jsonb_build_object('ok', false, 'error', v_denial, 'server_ts', clock_timestamp());
  end if;
  if a.order_freed_at is not null then
    return app.card_attempt_envelope(a);
  end if;
  v_detail := case
    when a.mode = 'test' or a.state not in ('unknown', 'released') or a.resolution is not null then 'attempt_not_freeable'
    when a.charge_may_exist then 'charge_may_exist'
    when a.last_lookup_at is null or p_confirmation_source is null
         or p_confirmation_source not in ('provider_report', 'provider_back_office')
         or v_reference is null or v_reason is null then 'confirmation_required'
  end;
  if v_detail is not null then
    perform app.card_denial_evidence(a.mode, a.organization_id, a.restaurant_id, a.branch_id, v_emp, v_device,
      a.id, 'free_order', v_detail);
    return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', v_detail,
                              'attempt_id', a.local_operation_id, 'attempt_state', a.state,
                              'server_ts', clock_timestamp());
  end if;
  update app.card_provider_attempts x
    set order_freed_at = clock_timestamp(), order_freed_reason = 'manager_confirmed',
        confirmation_source = p_confirmation_source, confirmation_reference = v_reference,
        order_freed_note = v_reason
    where x.id = a.id
    returning x.* into a;
  perform app.card_audit_write(a.organization_id, a.restaurant_id, a.branch_id, v_emp, v_device,
    'card_attempt.order_freed', jsonb_build_object('attempt_state', a.state,
                                                   'confirmation_source', a.confirmation_source));
  return app.card_attempt_envelope(a);
end;
$$;

create function public.card_attempt_free_order(
  p_pin_session_id uuid, p_device_id uuid, p_device_session_token text, p_attempt_id text,
  p_reason text, p_confirmation_source text, p_confirmation_reference text, p_caller_auth_user_id uuid)
  returns jsonb
  language sql
  volatile
  security invoker
  set search_path = ''
as $$
  select app.card_attempt_free_order(p_pin_session_id, p_device_id, p_device_session_token, p_attempt_id,
    p_reason, p_confirmation_source, p_confirmation_reference, p_caller_auth_user_id);
$$;


-- ----------------------------------------------------------------------------
-- 7. Internal app.sync_push guards (no client role, no wrapper).
-- ----------------------------------------------------------------------------
-- 7.1 The claim guard (§4.55.3), called inside six dispatch arms immediately
-- before the dispatched RPC. NULL = dispatch unchanged. Authorization first:
-- when the RPC is certain to deny the session it defers (NULL) so the RPC's own
-- refusal answers. For payment.create the identity-first provider recording
-- gate decides a provider identity whatever order its payload names; a
-- non-provider identity meets the claim exclusion and the manual-card rule.
-- Every refusal carries server_ts and the operation's own payload key, never an
-- attempt fact.
create function app.card_claim_guard(
  p_pin_session_id uuid, p_device_id uuid, p_order_id uuid, p_local_operation_id text,
  p_operation_type text, p_tender_type text, p_shift_id uuid)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_pin public.pin_sessions;
  a app.card_provider_attempts;
  v_order public.orders;
  v_shift public.shifts;
  v_drawer public.cash_drawer_sessions;
  v_found boolean;
  v_detail text;
  v_refusal text;
begin
  if p_operation_type is null or p_operation_type not in
       ('payment.create', 'order.discount', 'order.edit', 'order.items_add', 'order.void', 'shift.close') then
    return null;
  end if;
  select * into v_pin from public.pin_sessions ps where ps.id = p_pin_session_id;
  if not found then
    return null;
  end if;
  if app.card_dispatch_certain_deny(p_pin_session_id, p_device_id, p_operation_type, p_shift_id) then
    return null;
  end if;

  if p_operation_type = 'shift.close' then
    if p_shift_id is null then
      return null;
    end if;
    select true into v_found from public.shifts s
      where s.id = p_shift_id and s.organization_id = v_pin.organization_id and s.branch_id = v_pin.branch_id
      for update;
    if not coalesce(v_found, false) then
      return null;
    end if;
    if app.card_shift_close_blocked(v_pin.organization_id, p_shift_id) then
      return jsonb_build_object('ok', false, 'error', 'card_payment_in_progress',
                                'server_ts', clock_timestamp(), 'shift_id', p_shift_id);
    end if;
    return null;
  end if;

  if p_operation_type = 'payment.create' then
    select * into a from app.card_provider_attempts x
      where x.organization_id = v_pin.organization_id and x.device_id = p_device_id
        and x.local_operation_id = p_local_operation_id;
    if a.id is not null then
      if a.mode = 'test' then
        -- defensive: app.sync_push refuses a TEST identity before its ledger step.
        return jsonb_build_object('ok', false, 'error', 'test_attempt_not_recordable',
                                  'server_ts', clock_timestamp(), 'order_id', p_order_id);
      end if;
      -- The recording leg under the §4.55.3 lock order: orders, then the
      -- frozen shift and drawer session, then the attempt row.
      select * into v_order from public.orders o
        where o.organization_id = a.organization_id and o.id = a.order_id for update;
      select * into v_shift from public.shifts s
        where s.organization_id = a.organization_id and s.id = a.shift_id for update;
      select * into v_drawer from public.cash_drawer_sessions c
        where c.organization_id = a.organization_id and c.id = a.cash_drawer_session_id for update;
      select * into a from app.card_provider_attempts x where x.id = a.id for update;
      v_detail := case
        when a.resolution is not null then 'attempt_resolved'
        when a.order_freed_at is not null then 'attempt_freed'
        when a.charge_may_exist then 'provider_anomaly'
        when a.state <> 'approved' then 'attempt_not_approved'
        when p_order_id is distinct from a.order_id then 'order_mismatch'
        when p_tender_type is distinct from 'card' then 'tender_mismatch'
        when exists (select 1 from public.payments p
                      where p.device_id = a.device_id and p.local_operation_id = a.local_operation_id)
          then 'payment_exists'
      end;
      if v_detail is not null then
        return jsonb_build_object('ok', false, 'error', 'provider_recording_refused', 'detail', v_detail,
                                  'server_ts', clock_timestamp(), 'order_id', p_order_id);
      end if;
      if v_order.id is null or v_order.grand_total_minor <> a.amount_minor
         or v_order.currency_code <> a.currency_code then
        return jsonb_build_object('ok', false, 'error', 'amount_mismatch',
                                  'server_ts', clock_timestamp(), 'order_id', p_order_id);
      end if;
      if v_shift.id is null or v_shift.status <> 'open' or v_shift.device_id <> a.device_id
         or v_shift.deleted_at is not null
         or v_drawer.id is null or v_drawer.status <> 'active' or v_drawer.shift_id <> a.shift_id
         or v_drawer.deleted_at is not null then
        return jsonb_build_object('ok', false, 'error', 'card_context_lost',
                                  'server_ts', clock_timestamp(), 'order_id', p_order_id);
      end if;
      if not app.card_order_claim_active(a.organization_id, a.order_id) then
        return jsonb_build_object('ok', false, 'error', 'provider_recording_refused', 'detail', 'claim_inactive',
                                  'server_ts', clock_timestamp(), 'order_id', p_order_id);
      end if;
      return null;
    end if;
  end if;

  -- A non-provider operation on an order: resolved under the session's scope
  -- exactly as the dispatched RPC (a foreign or missing order defers to the
  -- RPC's own anti-oracle refusal), locked FOR UPDATE.
  if p_order_id is null then
    return null;
  end if;
  select * into v_order from public.orders o
    where o.id = p_order_id and o.organization_id = v_pin.organization_id and o.branch_id = v_pin.branch_id
    for update;
  if not found then
    return null;
  end if;
  if app.card_order_claim_active(v_pin.organization_id, p_order_id) then
    return jsonb_build_object('ok', false, 'error', 'payment_in_progress', 'detail', 'card_attempt_active',
                              'server_ts', clock_timestamp(), 'order_id', p_order_id);
  end if;
  if p_operation_type = 'payment.create' and p_tender_type = 'card'
     and exists (select 1 from app.payment_terminals t
                  where t.organization_id = v_pin.organization_id and t.device_id = p_device_id
                    and t.mode = 'live' and t.lifecycle in ('configured', 'enabled', 'draining')
                    and t.deleted_at is null) then
    return jsonb_build_object('ok', false, 'error', 'card_terminal_required',
                              'server_ts', clock_timestamp(), 'order_id', p_order_id);
  end if;
  return null;
end;
$$;

-- 7.2 The D-054 Resume recording guard (§4.55.7; D-057 point 3; D-058 point 11;
-- M10). Called by the valid-device ledger-claim step for a rejected
-- payment.create row (already locked FOR UPDATE) resent with recording_resume.
-- Returns {reopen:true} after atomically reopening the row (count + histories
-- written only then), or {reopen:false, resume_denied} / {reopen:false} with
-- nothing changed. Bounded evidence: an authorized dispatch, and a refused
-- request of an active manager+ once per (attempt, Resume count, reason).
create function app.card_recording_resume_guard(
  p_pin_session_id uuid, p_device_id uuid, p_sync_operation_id uuid, p_recording_resume integer,
  p_target_entity text, p_target_id uuid, p_client_created_at timestamptz, p_payload jsonb)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_so public.sync_operations;
  v_pin public.pin_sessions;
  a app.card_provider_attempts;
  v_order public.orders;
  v_shift public.shifts;
  v_drawer public.cash_drawer_sessions;
  v_actor text;
  v_denied text;
  v_token text;
  v_now timestamptz := clock_timestamp();
begin
  select * into v_so from public.sync_operations so where so.id = p_sync_operation_id;
  if not found or v_so.operation_type <> 'payment.create' or v_so.status <> 'rejected' then
    return jsonb_build_object('reopen', false);
  end if;
  select * into a from app.card_provider_attempts x
    where x.organization_id = v_so.organization_id and x.device_id = v_so.device_id
      and x.local_operation_id = v_so.local_operation_id and x.mode = 'live';
  if not found then
    return jsonb_build_object('reopen', false);
  end if;
  select * into v_pin from public.pin_sessions ps where ps.id = p_pin_session_id;
  -- (1) the active-manager proof, re-run here (never inferred from the role).
  v_actor := app.card_active_manager_denial(p_pin_session_id, p_device_id);
  if v_actor in ('actor_not_active', 'not_manager') then
    return jsonb_build_object('reopen', false, 'resume_denied', v_actor);
  end if;
  -- (2) the §4.55.3 lock order: orders, the frozen shift and drawer, the attempt.
  select * into v_order from public.orders o
    where o.organization_id = a.organization_id and o.id = a.order_id for update;
  select * into v_shift from public.shifts s
    where s.organization_id = a.organization_id and s.id = a.shift_id for update;
  select * into v_drawer from public.cash_drawer_sessions c
    where c.organization_id = a.organization_id and c.id = a.cash_drawer_session_id for update;
  select * into a from app.card_provider_attempts x where x.id = a.id for update;
  v_token := v_so.rejection_reason;
  if v_so.result ->> 'detail' in ('precondition_failed', 'revoked_employee', 'revoked_device') then
    v_token := v_so.result ->> 'detail';
  end if;
  v_denied := case
    when v_actor is not null then v_actor
    -- (3) M10: the explicit, NULL-safe stored-versus-resent comparison.
    when v_so.target_entity is distinct from p_target_entity
      or v_so.target_id is distinct from p_target_id
      or v_so.client_created_at is distinct from p_client_created_at
      or v_so.payload is distinct from p_payload
      or v_so.payload_fingerprint is distinct from md5('payment.create' || '|' || p_payload::text)
      then 'operation_mismatch'
    -- at 3 the guard answers resume_limit before any resume_stale check (§4.14).
    when a.recording_resume_count >= 3 then 'resume_limit'
    when a.recording_resume_count <> p_recording_resume then 'resume_stale'
    when a.state <> 'approved' or (v_so.payload ->> 'order_id') is distinct from a.order_id::text
      then 'not_recoverable'
    when exists (select 1 from public.payments p
                  where p.device_id = a.device_id and p.local_operation_id = a.local_operation_id)
      then 'payment_exists'
    when a.order_freed_at is not null or a.resolution is not null or a.charge_may_exist
      or not app.card_order_claim_active(a.organization_id, a.order_id)
      then 'claim_inactive'
    when v_order.id is null or v_order.status not in ('submitted', 'accepted', 'preparing', 'ready', 'served')
      or v_order.grand_total_minor <= 0 or app.order_is_fully_settled(a.organization_id, a.order_id)
      or exists (select 1 from public.payments p
                  where p.organization_id = a.organization_id and p.order_id = a.order_id
                    and p.status = 'completed' and p.deleted_at is null)
      then 'order_not_chargeable'
    when v_shift.id is null or v_shift.status <> 'open' or v_shift.device_id <> a.device_id
      or v_shift.deleted_at is not null
      or v_drawer.id is null or v_drawer.status <> 'active' or v_drawer.shift_id <> a.shift_id
      or v_drawer.deleted_at is not null
      then 'context_lost'
    when v_order.grand_total_minor <> a.amount_minor or v_order.currency_code <> a.currency_code
      then 'amount_mismatch'
    -- the refusal of THIS sync row must have been reported (§4.55.7): a report stamped
    -- before the row's latest rejection, or before the last authorized Resume, is stale.
    when a.recording_refused_at is null or a.refusal_code is distinct from v_token
      or a.recording_refused_at < v_so.updated_at
      or a.recording_refused_at < coalesce((a.recording_resume_history -> -1 ->> 'at')::timestamptz, '-infinity')
      then 'refusal_not_recorded'
    when v_token not in ('precondition_failed', 'revoked_employee', 'permission_denied')
      then 'not_recoverable'
  end;
  if v_denied is not null then
    if not exists (
      select 1 from public.audit_events e
       where e.organization_id = a.organization_id and e.device_id = a.device_id
         and e.action = 'card_attempt.recording_resume_requested'
         and e.new_values ->> 'local_operation_id' = a.local_operation_id
         and e.new_values ->> 'outcome' = 'refused'
         and e.new_values ->> 'resume_count' = a.recording_resume_count::text
         and e.new_values ->> 'denied_reason' = v_denied) then
      perform app.card_audit_write(a.organization_id, a.restaurant_id, a.branch_id, v_pin.employee_profile_id,
        p_device_id, 'card_attempt.recording_resume_requested',
        jsonb_build_object('attempt_state', a.state, 'prior_refusal_code', a.refusal_code,
          'resume_count', a.recording_resume_count, 'outcome', 'refused', 'denied_reason', v_denied,
          'local_operation_id', a.local_operation_id));
    end if;
    return jsonb_build_object('reopen', false, 'resume_denied', v_denied);
  end if;
  -- (4) authorized: reopen the SAME row for one dispatch. The guard writes only
  -- recording_resume_count, recording_refusal_history and recording_resume_history
  -- (§4.55.2); the prior refusal stays stored and a later refusal of the re-dispatch
  -- must be reported again (the freshness check above).
  update public.sync_operations so
    set status = 'in_flight', result = null, rejection_reason = null, last_error_code = null,
        last_error_class = null, conflict_info = null, updated_at = v_now
    where so.id = v_so.id;
  update app.card_provider_attempts x
    set recording_resume_count = a.recording_resume_count + 1,
        recording_refusal_history = a.recording_refusal_history
          || jsonb_build_array(jsonb_build_object('refusal_code', a.refusal_code, 'refused_at', a.recording_refused_at)),
        recording_resume_history = a.recording_resume_history
          || jsonb_build_array(jsonb_build_object('employee_profile_id', v_pin.employee_profile_id,
               'membership_id', v_pin.resolved_membership_id, 'at', v_now, 'resume_count', a.recording_resume_count))
    where x.id = a.id;
  perform app.card_audit_write(a.organization_id, a.restaurant_id, a.branch_id, v_pin.employee_profile_id,
    p_device_id, 'card_attempt.recording_resume_requested',
    jsonb_build_object('attempt_state', a.state, 'prior_refusal_code', a.refusal_code,
      'resume_count', a.recording_resume_count, 'outcome', 'dispatched', 'local_operation_id', a.local_operation_id));
  return jsonb_build_object('reopen', true);
end;
$$;


-- ----------------------------------------------------------------------------
-- 8. Operator-only RPCs (no wrapper, no grant to any app role; an attested
--    owner approver is required and the database executor — session_user,
--    never the definer's current_user — is recorded; every action is a private
--    event, never a tenant audit row). Refusals are RETURNed and write nothing.
-- ----------------------------------------------------------------------------
-- 8.1 The operator revision (§4.55.9; D-056 point 9; D-057 point 8; M6: caps
-- are validated only when enabling, so an authorized OFF is always recordable).
create function app.set_card_payments_pilot(
  p_enabled boolean, p_mode text, p_window_until timestamptz, p_max_test_amount_minor bigint,
  p_max_live_amount_minor bigint, p_reason text, p_operator_reference text, p_actor_app_user_id uuid)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_reason text;
  v_reference text;
  v_window timestamptz;
  v_test_cap bigint;
  v_live_cap bigint;
  v_revision bigint;
begin
  if p_enabled is null or p_mode is null or p_mode not in ('test', 'live') then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;
  if app.card_text_absent(p_operator_reference) or not app.card_attested_approver_ok(p_actor_app_user_id) then
    return jsonb_build_object('ok', false, 'error', 'permission_denied');
  end if;
  if p_reason is null or not coalesce(app.card_safe_text_ok(p_reason, 'reason'), false)
     or not coalesce(app.card_safe_text_ok(p_operator_reference, 'operator_reference'), false) then
    return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'out_of_contract');
  end if;
  v_reason := app.card_text_canonical(p_reason);
  v_reference := app.card_text_canonical(p_operator_reference);
  v_window := coalesce(p_window_until, now() + interval '12 hours');
  v_test_cap := case when p_max_test_amount_minor between 1 and 99999999999 then p_max_test_amount_minor end;
  v_live_cap := case when p_max_live_amount_minor between 1 and 99999999999 then p_max_live_amount_minor end;
  if p_enabled then
    if v_window <= now() then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'out_of_contract');
    end if;
    if p_mode = 'test' and v_test_cap is null then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'max_test_amount_missing');
    end if;
    if (p_max_test_amount_minor is not null and v_test_cap is null)
       or (p_max_live_amount_minor is not null and v_live_cap is null) then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'out_of_contract');
    end if;
  end if;
  -- The revision is drawn under the exclusive pilot-scope lock (§4.55.9), taken
  -- only after every refusal above, so a refused call holds no lock.
  perform pg_advisory_xact_lock(hashtextextended(
    'card-pilot-revision/v1:20605c2b-3145-4803-a990-bbec3d9c1096:2847c0be-3e31-45a5-957c-508729f1971e', 0));
  insert into app.card_payments_pilot_revisions (organization_id, restaurant_id, branch_id, enabled, mode,
      window_until, max_test_amount_minor, max_live_amount_minor, reason, operator_reference,
      actor_app_user_id, executor_principal)
    values ('20605c2b-3145-4803-a990-bbec3d9c1096', 'de3bbc64-edad-4ff4-bccd-c2ef217c1d56',
      '2847c0be-3e31-45a5-957c-508729f1971e', p_enabled, p_mode, v_window, v_test_cap, v_live_cap,
      v_reason, v_reference, p_actor_app_user_id, session_user)
    returning revision into v_revision;
  perform app.card_private_event_write('20605c2b-3145-4803-a990-bbec3d9c1096', 'de3bbc64-edad-4ff4-bccd-c2ef217c1d56',
    '2847c0be-3e31-45a5-957c-508729f1971e', null, null, 'operator.card_payments_pilot_updated',
    'attested_owner_approver', v_reference, p_actor_app_user_id, session_user, null, null, v_reason,
    jsonb_build_object('enabled', p_enabled, 'mode', p_mode, 'window_until', v_window,
                       'max_test_amount_minor', v_test_cap, 'max_live_amount_minor', v_live_cap));
  return jsonb_build_object('ok', true, 'revision', v_revision, 'enabled', p_enabled, 'mode', p_mode,
    'window_until', v_window, 'max_test_amount_minor', v_test_cap, 'max_live_amount_minor', v_live_cap);
end;
$$;

-- 8.2 The terminal binding (§4.55.9; D-057 point 4; D-058 point 6). The only
-- writer of app.payment_terminals, under the device's terminal admission lock
-- taken first; gates re-evaluated under it. Operator-only result details:
-- binding_exists | lifecycle_transition | payment_create_pending |
-- attempt_unresolved | admitting_binding_exists.
create function app.set_payment_terminal(
  p_device_id uuid, p_mode text, p_terminal_ref text, p_credential_ref text, p_lifecycle text,
  p_reason_code text, p_reason text, p_operator_reference text, p_actor_app_user_id uuid)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_device public.devices;
  v_reason text;
  v_reference text;
  v_current app.payment_terminals;
  v_new app.payment_terminals;
  v_backlog boolean;
  v_unresolved boolean;
  v_unresolved_live boolean;
  v_inactive boolean;
begin
  if p_device_id is null or p_mode is null or p_mode not in ('test', 'live')
     or p_lifecycle is null or p_lifecycle not in ('configured', 'enabled', 'draining', 'retired')
     or p_reason_code is null or p_reason_code not in ('test_setup', 'test_end', 'live_activation', 'incident',
                                                       'rotation', 'end_of_pilot') then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;
  if app.card_text_absent(p_operator_reference) or not app.card_attested_approver_ok(p_actor_app_user_id) then
    return jsonb_build_object('ok', false, 'error', 'permission_denied');
  end if;
  if p_terminal_ref is null or p_credential_ref is null
     or p_terminal_ref !~ '^[a-z0-9_-]{1,64}$' or p_credential_ref !~ '^[a-z0-9_-]{1,64}$'
     or not app.card_safe_text_ok(p_terminal_ref, 'terminal_ref')
     or not app.card_safe_text_ok(p_credential_ref, 'credential_ref')
     or p_terminal_ref = p_credential_ref
     or p_reason is null or not coalesce(app.card_safe_text_ok(p_reason, 'reason'), false)
     or not coalesce(app.card_safe_text_ok(p_operator_reference, 'operator_reference'), false) then
    return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'out_of_contract');
  end if;
  select * into v_device from public.devices d where d.id = p_device_id;
  if not found or v_device.organization_id <> '20605c2b-3145-4803-a990-bbec3d9c1096'::uuid
     or v_device.restaurant_id <> 'de3bbc64-edad-4ff4-bccd-c2ef217c1d56'::uuid
     or v_device.branch_id <> '2847c0be-3e31-45a5-957c-508729f1971e'::uuid
     or v_device.device_type <> 'pos' then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;
  -- D-059 point 2: stopping a till never depends on it being active - an inactive
  -- or management-revoked pilot device may still be drained or retired (the normal
  -- gates below apply); creating, enabling, re-enabling or replacing a binding
  -- needs an active device.
  v_inactive := not v_device.is_active or v_device.deleted_at is not null;
  if v_inactive and p_lifecycle not in ('draining', 'retired') then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;
  v_reason := app.card_text_canonical(p_reason);
  v_reference := app.card_text_canonical(p_operator_reference);
  -- The terminal / device admission lock first, then the device's mapping rows.
  perform app.card_terminal_lock(v_device.organization_id, p_device_id);
  perform 1 from app.payment_terminals t
    where t.organization_id = v_device.organization_id and t.device_id = p_device_id
    order by t.id for update;
  select * into v_current from app.payment_terminals t
    where t.organization_id = v_device.organization_id and t.device_id = p_device_id
      and t.deleted_at is null and t.lifecycle <> 'retired';
  v_backlog := exists (select 1 from public.sync_operations so
                        where so.organization_id = v_device.organization_id and so.device_id = p_device_id
                          and so.operation_type = 'payment.create' and so.status in ('pending', 'in_flight'));
  select coalesce(bool_or((app.card_attempt_derive(a) ->> 'unresolved')::boolean), false),
         coalesce(bool_or(a.mode = 'live' and (app.card_attempt_derive(a) ->> 'unresolved')::boolean), false)
    into v_unresolved, v_unresolved_live
    from app.card_provider_attempts a
    where a.organization_id = v_device.organization_id and a.device_id = p_device_id;

  if v_current.id is null then
    if p_lifecycle <> 'configured' then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'lifecycle_transition');
    end if;
    if p_mode = 'live' and v_backlog then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'payment_create_pending');
    end if;
    insert into app.payment_terminals (organization_id, restaurant_id, branch_id, device_id, terminal_ref,
        credential_ref, mode, lifecycle)
      values (v_device.organization_id, v_device.restaurant_id, v_device.branch_id, p_device_id,
        app.card_text_canonical(p_terminal_ref), app.card_text_canonical(p_credential_ref), p_mode, 'configured')
      returning * into v_new;
    perform app.card_private_event_write(v_new.organization_id, v_new.restaurant_id, v_new.branch_id, null, null,
      'operator.payment_terminal_updated', 'attested_owner_approver', v_reference, p_actor_app_user_id,
      session_user, null, p_device_id, v_reason,
      jsonb_build_object('binding_mode', v_new.mode, 'prior_lifecycle', null, 'new_lifecycle', 'configured',
                         'starts_admitted', false, 'reason_code', p_reason_code));
    return jsonb_build_object('ok', true, 'changed', true, 'binding_mode', v_new.mode,
                              'prior_lifecycle', null, 'new_lifecycle', 'configured');
  end if;

  if v_current.mode = p_mode and v_current.terminal_ref = p_terminal_ref and v_current.credential_ref = p_credential_ref then
    if v_current.lifecycle = p_lifecycle then
      return jsonb_build_object('ok', true, 'changed', false, 'binding_mode', v_current.mode,
                                'prior_lifecycle', v_current.lifecycle, 'new_lifecycle', v_current.lifecycle);
    end if;
    if not ((v_current.lifecycle = 'configured' and p_lifecycle in ('enabled', 'retired'))
            or (v_current.lifecycle = 'enabled' and p_lifecycle = 'draining')
            or (v_current.lifecycle = 'draining' and p_lifecycle in ('enabled', 'retired'))) then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'lifecycle_transition');
    end if;
    if p_lifecycle = 'enabled' and p_mode = 'live' and v_unresolved then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'attempt_unresolved');
    end if;
    if p_lifecycle = 'enabled' and p_mode = 'live' and v_backlog then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'payment_create_pending');
    end if;
    if p_lifecycle = 'retired' and v_unresolved then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'attempt_unresolved');
    end if;
    if p_lifecycle = 'retired' and v_backlog then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'payment_create_pending');
    end if;
    if p_lifecycle in ('enabled', 'draining') and exists (
         select 1 from app.payment_terminals t
          where t.organization_id = v_current.organization_id and t.id <> v_current.id
            and t.lifecycle in ('enabled', 'draining')) then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'admitting_binding_exists');
    end if;
    update app.payment_terminals t set lifecycle = p_lifecycle where t.id = v_current.id returning * into v_new;
    perform app.card_private_event_write(v_new.organization_id, v_new.restaurant_id, v_new.branch_id, null, null,
      'operator.payment_terminal_updated', 'attested_owner_approver', v_reference, p_actor_app_user_id,
      session_user, null, p_device_id, v_reason,
      jsonb_build_object('binding_mode', v_new.mode, 'prior_lifecycle', v_current.lifecycle,
                         'new_lifecycle', v_new.lifecycle, 'starts_admitted', v_new.lifecycle = 'enabled',
                         'reason_code', p_reason_code));
    return jsonb_build_object('ok', true, 'changed', true, 'binding_mode', v_new.mode,
                              'prior_lifecycle', v_current.lifecycle, 'new_lifecycle', v_new.lifecycle);
  end if;

  -- A new binding while one exists: only the atomic same-mode replacement of a
  -- draining row (credential rotation) — no retirement or creation gate.
  if p_lifecycle = 'configured' and v_current.lifecycle = 'draining' and v_current.mode = p_mode then
    update app.payment_terminals t set lifecycle = 'retired' where t.id = v_current.id;
    insert into app.payment_terminals (organization_id, restaurant_id, branch_id, device_id, terminal_ref,
        credential_ref, mode, lifecycle)
      values (v_device.organization_id, v_device.restaurant_id, v_device.branch_id, p_device_id,
        app.card_text_canonical(p_terminal_ref), app.card_text_canonical(p_credential_ref), p_mode, 'configured')
      returning * into v_new;
    perform app.card_private_event_write(v_current.organization_id, v_current.restaurant_id, v_current.branch_id,
      null, null, 'operator.payment_terminal_updated', 'attested_owner_approver', v_reference, p_actor_app_user_id,
      session_user, null, p_device_id, v_reason,
      jsonb_build_object('binding_mode', v_current.mode, 'prior_lifecycle', 'draining', 'new_lifecycle', 'retired',
                         'starts_admitted', false, 'reason_code', p_reason_code));
    perform app.card_private_event_write(v_new.organization_id, v_new.restaurant_id, v_new.branch_id, null, null,
      'operator.payment_terminal_updated', 'attested_owner_approver', v_reference, p_actor_app_user_id,
      session_user, null, p_device_id, v_reason,
      jsonb_build_object('binding_mode', v_new.mode, 'prior_lifecycle', null, 'new_lifecycle', 'configured',
                         'starts_admitted', false, 'reason_code', p_reason_code));
    return jsonb_build_object('ok', true, 'changed', true, 'replaced', true, 'binding_mode', v_new.mode,
                              'prior_lifecycle', 'draining', 'new_lifecycle', 'configured');
  end if;
  return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'binding_exists');
end;
$$;

-- 8.3 The orphan / anomaly resolution and the TEST closure (§4.55.7; D-057
-- point 4). LIVE: provider_voided / provider_refunded on an orphan_approved
-- attempt or a LIVE provider_anomaly, freeing the order (unless an earlier
-- manager free stamped it). TEST: test_closed on a TEST attempt still sent
-- after its deadline, unknown or released. No tenant audit.
create function app.card_attempt_resolve_orphan(
  p_attempt_row_id uuid, p_resolution text, p_resolution_reference text, p_reason text,
  p_operator_reference text, p_actor_app_user_id uuid)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  a app.card_provider_attempts;
  v_reason text;
  v_reference text;
  v_resolution_reference text;
  v_class text;
begin
  if p_attempt_row_id is null or p_resolution is null
     or p_resolution not in ('provider_voided', 'provider_refunded', 'test_closed') then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;
  if app.card_text_absent(p_operator_reference) or not app.card_attested_approver_ok(p_actor_app_user_id) then
    return jsonb_build_object('ok', false, 'error', 'permission_denied');
  end if;
  if p_resolution_reference is null
     or not coalesce(app.card_safe_text_ok(p_resolution_reference, 'resolution_reference'), false)
     or p_reason is null or not coalesce(app.card_safe_text_ok(p_reason, 'reason'), false)
     or not coalesce(app.card_safe_text_ok(p_operator_reference, 'operator_reference'), false) then
    return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'out_of_contract');
  end if;
  select * into a from app.card_provider_attempts x where x.id = p_attempt_row_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'attempt_not_found');
  end if;
  if a.mode = 'live' then
    perform 1 from public.orders o where o.organization_id = a.organization_id and o.id = a.order_id for update;
  end if;
  select * into a from app.card_provider_attempts x where x.id = a.id for update;
  v_reason := app.card_text_canonical(p_reason);
  v_reference := app.card_text_canonical(p_operator_reference);
  v_resolution_reference := app.card_text_canonical(p_resolution_reference);
  if a.mode = 'live' then
    v_class := app.card_attempt_derive(a) ->> 'classification';
    if p_resolution not in ('provider_voided', 'provider_refunded') or a.resolution is not null
       or not (v_class = 'orphan_approved' or (a.state in ('unknown', 'released') and a.charge_may_exist)) then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'attempt_not_resolvable');
    end if;
    update app.card_provider_attempts x
      set resolution = p_resolution, resolution_reference = v_resolution_reference, resolved_at = clock_timestamp(),
          order_freed_at = coalesce(a.order_freed_at, clock_timestamp()),
          order_freed_reason = coalesce(a.order_freed_reason, 'orphan_resolved')
      where x.id = a.id
      returning x.* into a;
    perform app.card_private_event_write(a.organization_id, a.restaurant_id, a.branch_id, a.id, null,
      'operator.card_attempt_orphan_resolved', 'attested_owner_approver', v_reference, p_actor_app_user_id,
      session_user, null, a.device_id, v_reason,
      jsonb_build_object('resolution', p_resolution, 'attempt_state', a.state));
  else
    if p_resolution <> 'test_closed' or a.resolution is not null
       or not ((a.state = 'sent' and a.start_deadline_at <= clock_timestamp()) or a.state in ('unknown', 'released')) then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'attempt_not_resolvable');
    end if;
    update app.card_provider_attempts x
      set resolution = 'test_closed', resolution_reference = v_resolution_reference, resolved_at = clock_timestamp()
      where x.id = a.id
      returning x.* into a;
    perform app.card_private_event_write(a.organization_id, a.restaurant_id, a.branch_id, a.id, null,
      'operator.card_attempt_test_closed', 'attested_owner_approver', v_reference, p_actor_app_user_id,
      session_user, null, a.device_id, v_reason,
      jsonb_build_object('resolution', 'test_closed', 'attempt_state', a.state));
  end if;
  return app.card_attempt_envelope(a) || jsonb_build_object('attempt_row_id', a.id);
end;
$$;

-- 8.4 The TEST incident hold (D-053 point 4; D-057 point 8): on a mode='test'
-- attempt row or one mode='test' private event; the purge skips held targets.
create function app.card_attempt_set_incident_hold(
  p_target_kind text, p_target_id uuid, p_hold boolean, p_hold_reference text, p_reason text,
  p_operator_reference text, p_actor_app_user_id uuid)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  a app.card_provider_attempts;
  e app.card_provider_private_events;
  v_reason text;
  v_reference text;
  v_hold_reference text;
begin
  if p_target_kind is null or p_target_kind not in ('attempt', 'event') or p_target_id is null or p_hold is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;
  if app.card_text_absent(p_operator_reference) or not app.card_attested_approver_ok(p_actor_app_user_id) then
    return jsonb_build_object('ok', false, 'error', 'permission_denied');
  end if;
  if (p_hold and (p_hold_reference is null
                  or not coalesce(app.card_safe_text_ok(p_hold_reference, 'incident_hold_reference'), false)))
     or p_reason is null or not coalesce(app.card_safe_text_ok(p_reason, 'reason'), false)
     or not coalesce(app.card_safe_text_ok(p_operator_reference, 'operator_reference'), false) then
    return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'out_of_contract');
  end if;
  v_reason := app.card_text_canonical(p_reason);
  v_reference := app.card_text_canonical(p_operator_reference);
  v_hold_reference := case when p_hold then app.card_text_canonical(p_hold_reference) end;
  if p_target_kind = 'attempt' then
    select * into a from app.card_provider_attempts x where x.id = p_target_id for update;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'attempt_not_found');
    end if;
    if a.mode <> 'test' then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'attempt_not_test');
    end if;
    update app.card_provider_attempts x
      set incident_hold_at = case when p_hold then clock_timestamp() end, incident_hold_reference = v_hold_reference
      where x.id = a.id;
    perform app.card_private_event_write(a.organization_id, a.restaurant_id, a.branch_id, a.id, null,
      'operator.card_test_attempt_hold_updated', 'attested_owner_approver', v_reference, p_actor_app_user_id,
      session_user, null, a.device_id, v_reason, jsonb_build_object('target_kind', 'attempt', 'hold', p_hold));
  else
    select * into e from app.card_provider_private_events x where x.id = p_target_id for update;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'event_not_found');
    end if;
    if e.mode is distinct from 'test' then
      return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'event_not_test');
    end if;
    update app.card_provider_private_events x
      set incident_hold_at = case when p_hold then clock_timestamp() end, incident_hold_reference = v_hold_reference
      where x.id = e.id;
    perform app.card_private_event_write(e.organization_id, e.restaurant_id, e.branch_id, e.attempt_row_id, null,
      'operator.card_test_attempt_hold_updated', 'attested_owner_approver', v_reference, p_actor_app_user_id,
      session_user, null, e.device_id, v_reason, jsonb_build_object('target_kind', 'event', 'hold', p_hold));
  end if;
  return jsonb_build_object('ok', true, 'target_kind', p_target_kind, 'hold', p_hold);
end;
$$;

-- 8.5 The TEST purge (D-053 point 4; D-057 point 8; D-058 point 7; D-059 point 3):
-- a bounded batch. The cut-off is fixed first; the batch selects, in device order,
-- the devices holding an expired, unheld TEST attempt or a deletable expired TEST
-- event (at most p_max_devices of them), takes their terminal locks, then the
-- exclusive purge barrier, then deletes - re-checked under the row locks - only
-- that device set's expired unheld TEST attempts (each identity, its digests and
-- outbound keys kept as a tombstone) and only then its expired TEST events that
-- carry no hold of their own and whose attempt, if it still exists, is unheld. An
-- event belongs to its attempt's device while that attempt exists, else to its own
-- device (every TEST event names one, CHECK), so no TEST event is unlockable and a
-- held attempt's event never re-selects its device. What stays eligible outside
-- the set waits for a later batch and is reported as deferred. Never a LIVE row,
-- never an operator.* event.
create function app.purge_expired_test_card_attempts(
  p_reason text, p_operator_reference text, p_actor_app_user_id uuid, p_max_devices integer default null)
  returns jsonb
  language plpgsql
  volatile
  security definer
  set search_path = ''
as $$
declare
  v_cutoff timestamptz := clock_timestamp();
  v_reason text;
  v_reference text;
  v_device record;
  v_locked uuid[] := '{}';
  v_attempts integer := 0;
  v_events integer := 0;
  v_attempts_deferred integer := 0;
  v_events_deferred integer := 0;
begin
  if p_max_devices is not null and (p_max_devices < 1 or p_max_devices > 1000) then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;
  if app.card_text_absent(p_operator_reference) or not app.card_attested_approver_ok(p_actor_app_user_id) then
    return jsonb_build_object('ok', false, 'error', 'permission_denied');
  end if;
  if p_reason is null or not coalesce(app.card_safe_text_ok(p_reason, 'reason'), false)
     or not coalesce(app.card_safe_text_ok(p_operator_reference, 'operator_reference'), false) then
    return jsonb_build_object('ok', false, 'error', 'precondition_failed', 'detail', 'out_of_contract');
  end if;
  v_reason := app.card_text_canonical(p_reason);
  v_reference := app.card_text_canonical(p_operator_reference);
  for v_device in
    select d.organization_id, d.device_id from (
      select a.organization_id, a.device_id from app.card_provider_attempts a
       where a.mode = 'test' and a.retention_until <= v_cutoff and a.incident_hold_at is null
      union
      select e.organization_id, coalesce(a.device_id, e.device_id) from app.card_provider_private_events e
        left join app.card_provider_attempts a on a.id = e.attempt_row_id
       where e.mode = 'test' and e.retention_until <= v_cutoff and e.incident_hold_at is null
         and a.incident_hold_at is null
         and coalesce(a.device_id, e.device_id) is not null
    ) d
    order by d.device_id, d.organization_id
    limit p_max_devices
  loop
    perform app.card_terminal_lock(v_device.organization_id, v_device.device_id);
    v_locked := v_locked || v_device.device_id;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('card-purge/v1', 0));
  -- Only attempts of the devices locked above (an attempt whose hold was cleared
  -- meanwhile is purged by the next run).
  with doomed as (
    select a.* from app.card_provider_attempts a
     where a.mode = 'test' and a.retention_until <= v_cutoff and a.incident_hold_at is null
       and a.device_id = any (v_locked)
     order by a.id
     for update
  ), kept as (
    insert into app.card_attempt_identity_tombstones (organization_id, device_id, local_operation_id,
        provider_status_digest, provider_duplicate_digest, provider_key_format_version,
        provider_query_key, provider_duplicate_key)
      select d.organization_id, d.device_id, d.local_operation_id, d.provider_status_digest,
             d.provider_duplicate_digest, d.provider_key_format_version, d.provider_query_key,
             d.provider_duplicate_key
        from doomed d
      returning 1
  )
  select count(*) into v_attempts from kept;
  delete from app.card_provider_attempts a
   where a.mode = 'test' and a.retention_until <= v_cutoff and a.incident_hold_at is null
     and a.device_id = any (v_locked)
     and exists (select 1 from app.card_attempt_identity_tombstones t
                  where t.organization_id = a.organization_id and t.device_id = a.device_id
                    and t.local_operation_id = a.local_operation_id);
  -- Events only of the locked device set: an event whose attempt still exists
  -- belongs to that attempt's device (and waits while the attempt is held), an
  -- event without one to its own device.
  delete from app.card_provider_private_events e
   where e.mode = 'test' and e.retention_until <= v_cutoff and e.incident_hold_at is null
     and not exists (select 1 from app.card_provider_attempts a
                      where a.id = e.attempt_row_id
                        and (a.incident_hold_at is not null or not (a.device_id = any (v_locked))))
     and (exists (select 1 from app.card_provider_attempts a
                   where a.id = e.attempt_row_id and a.device_id = any (v_locked))
          or (not exists (select 1 from app.card_provider_attempts a where a.id = e.attempt_row_id)
              and e.device_id = any (v_locked)));
  get diagnostics v_events = row_count;
  -- Deferred: what stays eligible under the same cut-off for a later batch.
  select count(*) into v_attempts_deferred from app.card_provider_attempts a
   where a.mode = 'test' and a.retention_until <= v_cutoff and a.incident_hold_at is null;
  select count(*) into v_events_deferred from app.card_provider_private_events e
   where e.mode = 'test' and e.retention_until <= v_cutoff and e.incident_hold_at is null
     and not exists (select 1 from app.card_provider_attempts a
                      where a.id = e.attempt_row_id and a.incident_hold_at is not null);
  perform app.card_private_event_write('20605c2b-3145-4803-a990-bbec3d9c1096', 'de3bbc64-edad-4ff4-bccd-c2ef217c1d56',
    '2847c0be-3e31-45a5-957c-508729f1971e', null, null, 'operator.card_test_attempts_purged',
    'attested_owner_approver', v_reference, p_actor_app_user_id, session_user, null, null, v_reason,
    jsonb_build_object('attempts_purged', v_attempts, 'events_purged', v_events,
                       'attempts_deferred', v_attempts_deferred, 'events_deferred', v_events_deferred,
                       'devices_locked', cardinality(v_locked), 'cutoff', v_cutoff));
  return jsonb_build_object('ok', true, 'attempts_purged', v_attempts, 'events_purged', v_events,
                            'attempts_deferred', v_attempts_deferred, 'events_deferred', v_events_deferred,
                            'devices_locked', cardinality(v_locked), 'cutoff', v_cutoff);
end;
$$;


-- ----------------------------------------------------------------------------
-- 9.1 app.sync_push — re-emitted from its LIVE body (20261008170200 L39-954)
--     with EXACTLY the seven 001D changes (API §4.14; DEPLOYMENT §18.2), each
--     marked "BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change N" (change 6 as
--     "Change 6 (D-058 point 7)" inside the change-5 block). Every other byte
--     (the historical mis-encoded comment bytes included) is preserved.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION app.sync_push(p_pin_session_id uuid, p_device_id uuid, p_operations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_org          uuid;
  v_rest         uuid;
  v_branch       uuid;
  v_dsid         uuid;
  v_emp          uuid;
  v_membership   uuid;
  v_ds_device    uuid;
  v_ds_active    boolean;
  v_ds_revoked   timestamptz;
  v_pairing      text;
  v_op           jsonb;
  v_local_op     text;
  v_op_type      text;
  v_payload      jsonb;
  v_depends      jsonb;
  v_target_ent   text;
  v_target_id    uuid;
  v_client_ts    timestamptz;
  v_fingerprint  text;
  v_dep          text;
  v_dep_ok       boolean;
  v_ex_status    text;
  v_ex_result    jsonb;
  v_ex_optype    text;
  v_ex_fp        text;
  -- PSC-001C correction (Finding 1): the existing row's id when the atomic
  -- ledger claim loses, and whether this request ADOPTED a stale non-terminal
  -- row (the only case that bumps retry_count â€” the pre-fix contract).
  v_ex_id        uuid;
  v_adopted      boolean;
  v_so_id        uuid;
  v_dispatch     jsonb;
  v_dispatch_ok  boolean;
  v_caught_state text;
  v_caught_msg   text;
  v_results      jsonb := '[]'::jsonb;
  v_op_result    jsonb;
  v_device_revoked boolean := false;
  v_customer_name text;
  v_customer_phone text;
  v_ack_order    uuid;
  v_ack_ok       boolean;
  -- KITCHEN-DISPATCH-ENFORCE-001: the REQUESTED order.submit dispatch mode
  -- (defaulted, so an absent key is the deployed 'kds' contract) and the
  -- AUTHORITATIVE branch kitchen workflow mode read under a FOR SHARE lock.
  v_requested_dispatch  text;
  v_branch_kitchen_mode text;
  -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D: the six card-present changes.
  v_has_payment_create  boolean;
  v_card_sensitive      boolean;
  v_recording_resume    integer;
  v_resume              jsonb;
  v_test_attempt        app.card_provider_attempts;
  v_test_tombstone      boolean;
begin
  -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 7 (D-060 point 1): a request made in
  -- an ACTIVE platform support session (app.current_support_session() of the
  -- verified JWT caller) is refused before everything else - the batch checks, the
  -- PIN / device proof, any lock, both paths, any ledger claim, replay, Resume or
  -- dispatch - with this entrypoint's request-level refusal (SQLSTATE 42501).
  -- Support mode is read-only; requests outside an active support session are
  -- unchanged.
  if app.current_support_session() is not null then
    raise exception 'sync_push: permission denied (active support session)' using errcode = '42501';
  end if;
  -- (0) batch shape + a conservative size cap (no frozen limit in docs; 100 is the
  --     interim cap, surfaced here and in the tests â€” keeps a push transaction bounded).
  if p_operations is null or jsonb_typeof(p_operations) <> 'array' then
    raise exception 'sync_push: p_operations must be a JSON array' using errcode = '42501';
  end if;
  if jsonb_array_length(p_operations) > 100 then
    raise exception 'sync_push: batch too large (max 100 operations, got %)', jsonb_array_length(p_operations) using errcode = '42501';
  end if;

  -- (a) PIN session + backing device session/pairing. Scope is derived here. The PIN
  --     session must exist + be valid (offline-window bounded, Q-009); a missing session
  --     or expired PIN still raises (cannot key/record safely without a session/window).
  select ps.organization_id, ps.restaurant_id, ps.branch_id, ps.device_session_id,
         ps.employee_profile_id, ps.resolved_membership_id
    into v_org, v_rest, v_branch, v_dsid, v_emp, v_membership
    from public.pin_sessions ps where ps.id = p_pin_session_id;
  if not found then
    raise exception 'sync_push: PIN session not found' using errcode = '42501';
  end if;
  if not app.is_pin_session_valid(p_pin_session_id) then
    raise exception 'sync_push: PIN session is not valid (inactive/ended/expired)' using errcode = '42501';
  end if;
  select ds.device_id, ds.is_active, ds.revoked_at, dp.status
    into v_ds_device, v_ds_active, v_ds_revoked, v_pairing
    from public.device_sessions ds join public.device_pairings dp on dp.id = ds.device_pairing_id
    where ds.id = v_dsid;
  if not found then
    raise exception 'sync_push: backing device session not found' using errcode = '42501';
  end if;
  if v_ds_device <> p_device_id then
    raise exception 'sync_push: device_id does not match the PIN session device' using errcode = '42501';
  end if;
  -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 5 (D-058 point 6): a call that
  -- holds a payment.create takes the device's terminal admission lock once,
  -- before any operation of either path is processed.
  v_has_payment_create := exists (select 1 from jsonb_array_elements(p_operations) e
                                   where jsonb_typeof(e) = 'object' and e ->> 'operation_type' = 'payment.create');
  if v_has_payment_create then
    perform app.card_terminal_lock(v_org, p_device_id);
  end if;
  -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 3 (D-056 point 8): a card-sensitive
  -- operation (shift.close; a payment.create whose identity is a provider attempt
  -- or which carries recording_resume) must be the only operation of its call;
  -- otherwise every operation is answered single_operation_required (retryable,
  -- no ledger row, no audit row, no business write), in either path.
  if jsonb_array_length(p_operations) > 1 and exists (
       select 1 from jsonb_array_elements(p_operations) e
        where jsonb_typeof(e) = 'object'
          and (e ->> 'operation_type' = 'shift.close'
               or (e ->> 'operation_type' = 'payment.create'
                   and (e ? 'recording_resume'
                        or exists (select 1 from app.card_provider_attempts ca
                                    where ca.organization_id = v_org and ca.device_id = p_device_id
                                      and ca.local_operation_id = e ->> 'local_operation_id'))))) then
    select coalesce(jsonb_agg(jsonb_build_object('local_operation_id', t.e ->> 'local_operation_id',
             'operation_type', t.e ->> 'operation_type', 'ok', false, 'error', 'single_operation_required',
             'retryable', true, 'status', 'pending', 'idempotency_replay', false) order by t.n), '[]'::jsonb)
      into v_results
      from jsonb_array_elements(p_operations) with ordinality as t(e, n);
    return jsonb_build_object('ok', true, 'results', v_results, 'server_ts', now())
           || case when not (v_ds_active and v_ds_revoked is null and v_pairing = 'active')
                   then jsonb_build_object('device_revoked', true) else '{}'::jsonb end;
  end if;
  -- RF061-A1: a REVOKED / inactive device session or pairing no longer fails the whole
  -- batch with a silent raise. Instead each pushed op is RECORDED as rejected
  -- (revoked_device) and surfaced, so the offline-queued operations are not lost (R-007;
  -- AC1). Authorization is INGEST-TIME (the device is revoked NOW); client timestamps are
  -- never trusted. A previously-APPLIED op still replays its stored result (idempotency).
  if not (v_ds_active and v_ds_revoked is null and v_pairing = 'active') then
    v_device_revoked := true;
    for v_op in select * from jsonb_array_elements(p_operations)
    loop
      v_local_op   := v_op ->> 'local_operation_id';
      v_op_type    := v_op ->> 'operation_type';
      v_payload    := v_op -> 'payload';
      v_depends    := coalesce(v_op -> 'depends_on', '[]'::jsonb);
      v_target_ent := v_op ->> 'target_entity';
      -- PSC-001D correction (F3) + PSC-001C: for the three IDENTITY-HARDENED
      -- operations (order.void_ack, order.items_add, order.round_status) the
      -- target id is parsed inside a PROTECTED boundary â€” a malformed uuid
      -- must reject only ITS operation, never abort the whole batch. The 12
      -- prior operations keep their exact existing parse semantics.
      if v_op_type in ('order.void_ack', 'order.items_add', 'order.round_status', 'order.edit', 'order.edit_ack') then
        begin
          v_target_id := nullif(v_op ->> 'target_id', '')::uuid;
        exception when others then
          v_target_id := null;
        end;
      else
        v_target_id := nullif(v_op ->> 'target_id', '')::uuid;
      end if;
      v_client_ts  := nullif(v_op ->> 'client_created_at', '')::timestamptz;

      -- envelope validation (same as the valid path): malformed -> rejected result, NO ledger row
      if v_local_op is null or btrim(v_local_op) = '' then
        v_results := v_results || jsonb_build_object('ok', false, 'error', 'invalid_envelope',
          'detail', 'local_operation_id is required', 'status', 'rejected', 'idempotency_replay', false);
        continue;
      end if;
      if v_op_type is null or v_op_type not in ('shift.open', 'order.submit', 'order.discount', 'payment.create', 'shift.close', 'order.status', 'order.void', 'order.table_move', 'menu.availability_set', 'table.status_set', 'table.link', 'table.unlink', 'order.void_ack', 'order.items_add', 'order.round_status', 'cash_drawer.no_sale_open', 'order.edit', 'order.edit_ack') then
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'ok', false,
          'error', 'unknown_operation_type', 'detail', coalesce(v_op_type, '<null>'), 'status', 'rejected', 'idempotency_replay', false);
        continue;
      end if;
      if v_payload is null or jsonb_typeof(v_payload) <> 'object' then
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type,
          'ok', false, 'error', 'invalid_payload', 'detail', 'payload must be a JSON object', 'status', 'rejected', 'idempotency_replay', false);
        continue;
      end if;
      -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 2 (D-058 point 11): the protected
      -- recording_resume parse at the per-operation boundary, before the
      -- fingerprint and ledger steps. Malformed control data (another operation
      -- type, a non-integer, a value outside 0..3, beside a depends_on that is not
      -- an empty array) is refused per operation with no ledger row. This path
      -- never reopens.
      if v_op ? 'recording_resume' then
        if v_op_type <> 'payment.create'
           or jsonb_typeof(v_op -> 'recording_resume') <> 'number'
           or (v_op ->> 'recording_resume') !~ '^[0-3]$'
           or (case when jsonb_typeof(v_depends) = 'array' then jsonb_array_length(v_depends) > 0 else true end) then
          v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type,
            'ok', false, 'error', 'invalid_payload', 'detail', 'recording_resume', 'status', 'rejected', 'idempotency_replay', false);
          continue;
        end if;
      end if;

      -- PSC-001D correction (final pass) + PSC-001C: the SAME canonical
      -- identity contract as the valid path for ALL THREE hardened operations,
      -- enforced BEFORE the fingerprint, the terminal-replay lookup, the
      -- idempotency-conflict comparison and the ledger write. A revoked device
      -- must not gain permission to submit ambiguous or contradictory
      -- operation identity: a missing, malformed or CONTRADICTORY
      -- target/payload-identity pair (payload.order_id for order.void_ack and
      -- order.items_add; payload.round_id for order.round_status) is a hostile
      -- or malformed envelope â€” rejected with NO ledger row (the malformed-
      -- envelope convention), the batch continues. Only that op is affected.
      if v_op_type in ('order.void_ack', 'order.items_add', 'order.round_status', 'order.edit', 'order.edit_ack') then
        v_ack_ok := v_target_id is not null;
        begin
          v_ack_order := nullif(v_payload ->> (case when v_op_type = 'order.round_status' then 'round_id' else 'order_id' end), '')::uuid;
        exception when others then
          v_ack_order := null;
        end;
        if v_ack_order is null or not v_ack_ok or v_target_id <> v_ack_order then
          v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type,
            'ok', false, 'error', 'invalid_payload',
            'detail', v_op_type || ' requires matching uuid target_id and payload.'
                      || (case when v_op_type = 'order.round_status' then 'round_id' else 'order_id' end),
            'status', 'rejected', 'idempotency_replay', false);
          continue;
        end if;
      end if;

      -- PSC-001D correction (F2 + final pass) + PSC-001C: the SAME target-
      -- bound fingerprint SHAPE as the valid path for all three hardened
      -- operations â€” the target component is the PARSED uuid's text
      -- (guaranteed non-null and equal to the parsed payload identity by the
      -- check above), so a legitimately-applied op still replays its stored
      -- result after a revocation (identical identity -> identical
      -- fingerprint), while the 12 prior operations are unchanged.
      if v_op_type in ('order.void_ack', 'order.items_add', 'order.round_status', 'order.edit', 'order.edit_ack') then
        v_fingerprint := md5(v_op_type || '|' || v_payload::text || '|' || v_target_id::text);
      else
        -- POS-CUSTOMER-PHONE-DINEIN-CLOSE-001 (Finding 4): customer_phone is DATA
        -- ONLY on an order.submit â€” carried in the payload for persistence but
        -- EXCLUDED from the operation identity, so re-sending the same op with only
        -- a different phone is an idempotent replay, not a conflict. Removing an
        -- absent key is a no-op, so a phone-less op keeps its EXACT prior
        -- fingerprint (backward compatible); every other field and every other
        -- operation type is unchanged.
        v_fingerprint := md5(v_op_type || '|' || (case when v_op_type = 'order.submit' then v_payload - 'customer_phone' else v_payload end)::text);
      end if;

      -- dedup/replay (PSC-001C correction, Finding 1 â€” ATOMIC CLAIM): the
      -- rejected/revoked_device recording is now claimed with ONE
      -- INSERT .. ON CONFLICT DO NOTHING on the transport identity. When the
      -- claim loses, the existing row is LOCKED (waiting out any concurrent
      -- claimant's COMMIT) and decided from its COMMITTED state: a TERMINAL
      -- row replays its stored result (a legitimately-APPLIED op before
      -- revocation is NOT re-rejected â€” and can no longer be OVERWRITTEN by
      -- this path racing a valid-device apply); a different identity is a
      -- conflict; only a genuinely stale NON-terminal row is re-recorded as
      -- rejected (the pre-fix retry contract, bump included).
      -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 5 (D-058 point 5): the
      -- full-identity lock immediately before a payment.create's ledger claim.
      if v_op_type = 'payment.create' then
        perform app.card_identity_lock(v_org, p_device_id, v_local_op);
      end if;
      v_so_id := null;
      insert into public.sync_operations as so (
        organization_id, restaurant_id, branch_id, device_id, local_operation_id, operation_type,
        target_entity, target_id, payload, payload_fingerprint, depends_on, status,
        last_error_code, last_error_class, rejection_reason,
        result, client_created_at)
      values (v_org, v_rest, v_branch, p_device_id, v_local_op, v_op_type,
              v_target_ent, v_target_id, v_payload, v_fingerprint, v_depends, 'rejected',
              'revoked_device', 'permanent', 'revoked_device',
              jsonb_build_object('ok', false, 'error', 'rejected', 'detail', 'revoked_device'), v_client_ts)
      on conflict (organization_id, device_id, local_operation_id) do nothing
      returning so.id into v_so_id;
      if v_so_id is null then
        select so.id, so.status, so.result, so.operation_type, so.payload_fingerprint
          into v_ex_id, v_ex_status, v_ex_result, v_ex_optype, v_ex_fp
          from public.sync_operations so
          where so.organization_id = v_org and so.device_id = p_device_id and so.local_operation_id = v_local_op
          for update;
        if v_ex_optype <> v_op_type or v_ex_fp <> v_fingerprint then
          insert into public.audit_events (organization_id, restaurant_id, branch_id, actor_app_user_id, actor_employee_profile_id, device_id, action, reason, old_values, new_values)
          values (v_org, v_rest, v_branch, null, v_emp, p_device_id, 'sync.operation_conflict', null, null,
                  jsonb_build_object('local_operation_id', v_local_op, 'stored_operation_type', v_ex_optype, 'pushed_operation_type', v_op_type,
                                     'stored_status', v_ex_status, 'reason', 'idempotency_key_reused_with_different_operation_or_payload'));
          v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'ok', false,
            'error', 'conflict', 'detail', 'idempotency key already used for a different operation/payload', 'status', 'conflict', 'idempotency_replay', false);
          continue;
        end if;
        if v_ex_status in ('applied', 'rejected', 'dead', 'conflict') then
          v_results := v_results || (coalesce(v_ex_result, '{}'::jsonb)
            || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'status', v_ex_status, 'idempotency_replay', true));
          continue;
        end if;
        -- a stale NON-terminal row: re-record it as rejected (revoked_device)
        -- under the held lock â€” the pre-fix on-conflict contract, verbatim.
        update public.sync_operations as so
          set status = 'rejected', last_error_code = 'revoked_device', last_error_class = 'permanent',
              rejection_reason = 'revoked_device',
              result = jsonb_build_object('ok', false, 'error', 'rejected', 'detail', 'revoked_device'),
              retry_count = so.retry_count + 1, updated_at = now()
          where so.id = v_ex_id;
      end if;
      insert into public.audit_events (organization_id, restaurant_id, branch_id, actor_app_user_id, actor_employee_profile_id, device_id, action, reason, old_values, new_values)
      values (v_org, v_rest, v_branch, null, v_emp, p_device_id, 'sync.operation_rejected', 'revoked_device', null,
              jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'reason', 'revoked_device'));
      v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'ok', false,
        'error', 'rejected', 'detail', 'revoked_device', 'status', 'rejected', 'idempotency_replay', false);
    end loop;
    return jsonb_build_object('ok', true, 'results', v_results, 'server_ts', now(), 'device_revoked', true);
  end if;

  -- (b) per-operation loop (ordered) â€” VALID device path (unchanged from RF-056)
  for v_op in select * from jsonb_array_elements(p_operations)
  loop
    v_caught_state := null;
    v_caught_msg   := null;
    v_dispatch     := null;
    v_dispatch_ok  := null;
    v_so_id        := null;

    v_local_op   := v_op ->> 'local_operation_id';
    v_op_type    := v_op ->> 'operation_type';
    v_payload    := v_op -> 'payload';
    v_depends    := coalesce(v_op -> 'depends_on', '[]'::jsonb);
    v_target_ent := v_op ->> 'target_entity';
    -- PSC-001D correction (F3) + PSC-001C: protected parse for the three
    -- identity-hardened operations â€” a malformed target uuid rejects only ITS
    -- operation (below), never the batch. The 12 prior operations keep their
    -- exact existing semantics.
    if v_op_type in ('order.void_ack', 'order.items_add', 'order.round_status', 'order.edit', 'order.edit_ack') then
      begin
        v_target_id := nullif(v_op ->> 'target_id', '')::uuid;
      exception when others then
        v_target_id := null;
      end;
    else
      v_target_id := nullif(v_op ->> 'target_id', '')::uuid;
    end if;
    v_client_ts  := nullif(v_op ->> 'client_created_at', '')::timestamptz;

    -- (b1) envelope shape validation. Malformed envelopes are returned rejected
    --      WITHOUT a ledger row (they cannot be keyed/stored safely); they never dispatch.
    if v_local_op is null or btrim(v_local_op) = '' then
      v_results := v_results || jsonb_build_object('ok', false, 'error', 'invalid_envelope',
        'detail', 'local_operation_id is required', 'status', 'rejected', 'idempotency_replay', false);
      continue;
    end if;
    if v_op_type is null or v_op_type not in ('shift.open', 'order.submit', 'order.discount', 'payment.create', 'shift.close', 'order.status', 'order.void', 'order.table_move', 'menu.availability_set', 'table.status_set', 'table.link', 'table.unlink', 'order.void_ack', 'order.items_add', 'order.round_status', 'cash_drawer.no_sale_open', 'order.edit', 'order.edit_ack') then
      v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'ok', false,
        'error', 'unknown_operation_type', 'detail', coalesce(v_op_type, '<null>'), 'status', 'rejected', 'idempotency_replay', false);
      continue;
    end if;
    if v_payload is null or jsonb_typeof(v_payload) <> 'object' then
      v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type,
        'ok', false, 'error', 'invalid_payload', 'detail', 'payload must be a JSON object', 'status', 'rejected', 'idempotency_replay', false);
      continue;
    end if;
    if jsonb_typeof(v_depends) <> 'array' then
      v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type,
        'ok', false, 'error', 'invalid_depends_on', 'detail', 'depends_on must be a JSON array', 'status', 'rejected', 'idempotency_replay', false);
      continue;
    end if;
    -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 2 (D-057 point 3; D-058 point 11):
    -- the protected recording_resume parse (a top-level sibling of payload, never
    -- part of the fingerprint): honoured on payment.create only, as a JSON
    -- integer 0..3 with an empty depends_on; anything else is refused per
    -- operation with no ledger row.
    v_recording_resume := null;
    if v_op ? 'recording_resume' then
      if v_op_type <> 'payment.create'
         or jsonb_typeof(v_op -> 'recording_resume') <> 'number'
         or (v_op ->> 'recording_resume') !~ '^[0-3]$'
         or jsonb_array_length(v_depends) > 0 then
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type,
          'ok', false, 'error', 'invalid_payload', 'detail', 'recording_resume', 'status', 'rejected', 'idempotency_replay', false);
        continue;
      end if;
      v_recording_resume := (v_op ->> 'recording_resume')::integer;
    end if;

    -- (b1+) PSC-001D correction (F2/F3) + PSC-001C: CANONICAL TARGET IDENTITY
    -- for the three hardened operations, enforced BEFORE the fingerprint, the
    -- terminal-replay lookup and the dispatch. The envelope MUST carry a
    -- parseable target_id AND a parseable payload identity (payload.order_id
    -- for order.void_ack and order.items_add; payload.round_id for
    -- order.round_status) and they MUST be the same uuid â€” a missing,
    -- malformed or CONTRADICTORY pair is a hostile/malformed envelope:
    -- rejected with NO ledger row (the malformed-envelope convention), so a
    -- replayed local_operation_id with a swapped target can never reach the
    -- stored terminal result, mutate anything, or learn anything about
    -- another order or round. Only that operation is affected.
    if v_op_type in ('order.void_ack', 'order.items_add', 'order.round_status', 'order.edit', 'order.edit_ack') then
      v_ack_ok := v_target_id is not null;
      begin
        v_ack_order := nullif(v_payload ->> (case when v_op_type = 'order.round_status' then 'round_id' else 'order_id' end), '')::uuid;
      exception when others then
        v_ack_order := null;
      end;
      if v_ack_order is null or not v_ack_ok or v_target_id <> v_ack_order then
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type,
          'ok', false, 'error', 'invalid_payload',
          'detail', v_op_type || ' requires matching uuid target_id and payload.'
                    || (case when v_op_type = 'order.round_status' then 'round_id' else 'order_id' end),
          'status', 'rejected', 'idempotency_replay', false);
        continue;
      end if;
    end if;

    -- PSC-001D correction (F2) + PSC-001C: the fingerprint of every hardened
    -- operation BINDS the canonical target identity, so a terminal replay is
    -- valid only for the same local_operation_id + operation + payload +
    -- TARGET. The 12 prior operations keep their exact existing fingerprint
    -- semantics.
    if v_op_type in ('order.void_ack', 'order.items_add', 'order.round_status', 'order.edit', 'order.edit_ack') then
      v_fingerprint := md5(v_op_type || '|' || v_payload::text || '|' || v_target_id::text);
    else
      -- POS-CUSTOMER-PHONE-DINEIN-CLOSE-001 (Finding 4): order.submit identity
      -- EXCLUDES customer_phone (data-only) â€” same canonical rule as the
      -- rejection path above, so both paths fingerprint an op identically. A
      -- phone-less op is byte-identical; all other fields/op-types unchanged.
      v_fingerprint := md5(v_op_type || '|' || (case when v_op_type = 'order.submit' then v_payload - 'customer_phone' else v_payload end)::text);
    end if;

    -- (b2) ATOMIC LEDGER CLAIM (PSC-001C correction, Finding 1). The pre-fix
    -- shape read the ledger and only LATER upserted it, so two concurrent
    -- requests with the SAME (org, device, local_operation_id) + fingerprint
    -- could both pass the read; the loser's upsert then dragged the winner's
    -- COMMITTED terminal row back to in_flight, re-dispatched (now an
    -- invalid_transition), and finalized the previously-successful row as
    -- rejected. The claim is now ONE INSERT .. ON CONFLICT DO NOTHING on the
    -- transport identity, computed AFTER envelope validation + identity
    -- canonicalization + the fingerprint:
    --   * claim WON  -> this transaction owns dispatch (fresh row, in_flight,
    --     retry_count 0) and finalizes it exactly once at (b6);
    --   * claim LOST -> the existing row is LOCKED (FOR UPDATE â€” waiting out a
    --     concurrent claimant's COMMIT) and decided from COMMITTED state: a
    --     fingerprint/op mismatch keeps the exact idempotency-conflict
    --     contract; a TERMINAL row replays its stored result (and can never be
    --     overwritten or reset to in_flight again); only a genuinely stale
    --     NON-terminal row (pending / crashed in_flight) is ADOPTED â€” the
    --     pre-fix retry contract, bump included. A losing concurrent caller
    --     therefore converges on the winner's stored terminal result.
    -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 5 (D-058 point 5): the
    -- full-identity lock immediately before a payment.create's ledger claim.
    -- Change 6 (D-058 point 7): under it, after the guard's payload-independent
    -- authorization check, an identity that is a TEST attempt or a purged TEST
    -- identity is refused before the ledger step — no sync row, no tenant
    -- audit, at most one private test.card_recording_refused per attempt.
    if v_op_type = 'payment.create' then
      perform app.card_identity_lock(v_org, p_device_id, v_local_op);
      select * into v_test_attempt from app.card_provider_attempts ca
        where ca.organization_id = v_org and ca.device_id = p_device_id
          and ca.local_operation_id = v_local_op and ca.mode = 'test';
      v_test_tombstone := exists (select 1 from app.card_attempt_identity_tombstones ct
                                   where ct.organization_id = v_org and ct.device_id = p_device_id
                                     and ct.local_operation_id = v_local_op);
      if v_test_attempt.id is not null or v_test_tombstone then
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type,
          'ok', false,
          'error', case when app.card_dispatch_certain_deny(p_pin_session_id, p_device_id, 'payment.create', null)
                        then 'permission_denied' else 'test_attempt_not_recordable' end,
          'status', 'rejected', 'idempotency_replay', false, 'server_ts', now(), 'order_id', v_payload -> 'order_id');
        if v_test_attempt.id is not null then
          perform app.card_private_event_write(v_test_attempt.organization_id, v_test_attempt.restaurant_id,
            v_test_attempt.branch_id, v_test_attempt.id, 'test', 'test.card_recording_refused', 'employee', 'employee',
            null, null, v_emp, p_device_id, null, '{}'::jsonb);
        end if;
        continue;
      end if;
    end if;
    v_adopted := false;
    v_so_id   := null;
    insert into public.sync_operations as so (
      organization_id, restaurant_id, branch_id, device_id, local_operation_id, operation_type,
      target_entity, target_id, payload, payload_fingerprint, depends_on, status, client_created_at)
    values (v_org, v_rest, v_branch, p_device_id, v_local_op, v_op_type,
            v_target_ent, v_target_id, v_payload, v_fingerprint, v_depends, 'in_flight', v_client_ts)
    on conflict (organization_id, device_id, local_operation_id) do nothing
    returning so.id into v_so_id;

    if v_so_id is null then
      select so.id, so.status, so.result, so.operation_type, so.payload_fingerprint
        into v_ex_id, v_ex_status, v_ex_result, v_ex_optype, v_ex_fp
        from public.sync_operations so
        where so.organization_id = v_org and so.device_id = p_device_id and so.local_operation_id = v_local_op
        for update;
      if v_ex_optype <> v_op_type or v_ex_fp <> v_fingerprint then
        insert into public.audit_events (organization_id, restaurant_id, branch_id, actor_app_user_id, actor_employee_profile_id, device_id, action, reason, old_values, new_values)
        values (v_org, v_rest, v_branch, null, v_emp, p_device_id, 'sync.operation_conflict', null, null,
                jsonb_build_object('local_operation_id', v_local_op, 'stored_operation_type', v_ex_optype, 'pushed_operation_type', v_op_type,
                                   'stored_status', v_ex_status, 'reason', 'idempotency_key_reused_with_different_operation_or_payload'));
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'ok', false,
          'error', 'conflict', 'detail', 'idempotency key already used for a different operation/payload', 'status', 'conflict', 'idempotency_replay', false);
        continue;
      end if;
      -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 2 (D-054; D-057 point 3; D-058
      -- point 11): a rejected payment.create resent with recording_resume goes
      -- to the Resume guard, which either reopens THIS row for one dispatch
      -- (through the adopt path below) or leaves it replayed with its
      -- resume_denied token.
      v_resume := null;
      if v_ex_status = 'rejected' and v_op_type = 'payment.create' and v_recording_resume is not null then
        v_resume := app.card_recording_resume_guard(p_pin_session_id, p_device_id, v_ex_id, v_recording_resume,
                                                    v_target_ent, v_target_id, v_client_ts, v_payload);
      end if;
      if v_ex_status in ('applied', 'rejected', 'dead', 'conflict')
         and not coalesce((v_resume ->> 'reopen')::boolean, false) then
        v_results := v_results || (coalesce(v_ex_result, '{}'::jsonb)
          || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'status', v_ex_status, 'idempotency_replay', true)
          || case when v_resume ? 'resume_denied' then jsonb_build_object('resume_denied', v_resume ->> 'resume_denied')
                  else '{}'::jsonb end);
        continue;
      end if;
      -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 2 (D-057 point 3): a row that a
      -- D-054 Resume reopened and that is back at pending is dispatched only under
      -- the active-manager proof; otherwise it stays pending, unaudited.
      if not coalesce((v_resume ->> 'reopen')::boolean, false)
         and v_op_type = 'payment.create'
         and exists (select 1 from app.card_provider_attempts ca
                      where ca.organization_id = v_org and ca.device_id = p_device_id
                        and ca.local_operation_id = v_local_op and ca.mode = 'live'
                        and ca.recording_resume_count > 0)
         and app.card_active_manager_denial(p_pin_session_id, p_device_id) is not null then
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'ok', false,
          'error', 'resume_authority_required', 'retryable', true, 'status', 'pending', 'idempotency_replay', false);
        continue;
      end if;
      v_so_id   := v_ex_id;
      v_adopted := true;
    end if;

    -- (b3) dependency guard (still BEFORE any dispatch; the claimed/adopted
    -- row is parked as pending exactly like the pre-fix contract â€” a fresh
    -- claim keeps retry_count 0, an adopted re-attempt bumps it).
    v_dep_ok := true;
    for v_dep in select jsonb_array_elements_text(v_depends)
    loop
      if not exists (
        select 1 from public.sync_operations so
        where so.organization_id = v_org and so.device_id = p_device_id
          and so.local_operation_id = v_dep and so.status = 'applied'
      ) then
        v_dep_ok := false;
        exit;
      end if;
    end loop;

    if not v_dep_ok then
      update public.sync_operations as so
        set status = 'pending', last_error_code = 'dependency_not_ready', last_error_class = 'transient',
            retry_count = so.retry_count + (case when v_adopted then 1 else 0 end),
            updated_at = now()
        where so.id = v_so_id;
      v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'ok', false,
        'error', 'dependency_not_ready', 'retryable', true, 'status', 'pending', 'idempotency_replay', false);
      continue;
    end if;

    -- (b4) an ADOPTED stale re-attempt returns to in_flight with the retry
    -- bump (the pre-fix on-conflict contract); a fresh claim is already
    -- in_flight and is never re-written here.
    if v_adopted then
      update public.sync_operations as so
        set status = 'in_flight', retry_count = so.retry_count + 1, updated_at = now()
        where so.id = v_so_id;
    end if;

    -- (b5) dispatch to the matching business RPC inside a per-op EXCEPTION subtransaction.
    begin
      case v_op_type
        when 'shift.open' then
          v_dispatch := app.open_shift(
            p_pin_session_id,
            (v_payload ->> 'shift_id')::uuid,
            (v_payload ->> 'cash_drawer_session_id')::uuid,
            p_device_id,
            v_local_op,
            (v_payload ->> 'opening_float_minor')::bigint);
        when 'order.submit' then
          -- POS-CUSTOMER-PHONE-DINEIN-CLOSE-001: validate the OPTIONAL customer
          -- phone UP FRONT. Empty/whitespace -> null (the order proceeds). A
          -- non-empty value that is not a valid phone (>32 chars / a disallowed
          -- character / fewer than 5 digits) REJECTS the whole op with a typed
          -- invalid_payload and creates NO order (the POS UI already blocks
          -- submit on an invalid phone; this is server-side defence in depth,
          -- and the DB CHECK is the final boundary). A valid/empty phone falls
          -- through to the UNCHANGED submit path; a valid phone is stamped after.
          v_customer_phone := btrim(coalesce(v_payload ->> 'customer_phone', ''));
          -- KITCHEN-DISPATCH-ENFORCE-001: resolve the REQUESTED dispatch mode
          -- (an absent key is the deployed 'kds' contract) and, ONLY for the
          -- privileged direct_print request, read the AUTHORITATIVE branch mode
          -- under a FOR SHARE row lock held to transaction end. The predicate is
          -- the same tenant-scoped one app.submit_order's dispatch gate uses and
          -- the scope comes from the SESSION (v_org/v_branch), never the payload.
          -- FOR SHARE conflicts with the FOR NO KEY UPDATE lock a
          -- kitchen_workflow_mode UPDATE takes, so a mode change cannot commit
          -- underneath an in-flight acceptance (and vice versa), while concurrent
          -- direct_print submits share the lock. The common absent/'kds' path
          -- reads nothing here and takes NO lock.
          v_requested_dispatch  := coalesce(v_payload ->> 'dispatch_mode', 'kds');
          v_branch_kitchen_mode := null;
          if v_requested_dispatch = 'direct_print' then
            select b.kitchen_workflow_mode
              into v_branch_kitchen_mode
              from public.branches b
              where b.id              = v_branch
                and b.organization_id = v_org
                and b.deleted_at is null
              for share;
          end if;
          -- Validation runs BEFORE app.submit_order, so every rejection below
          -- creates NO business rows at all (the shipped customer-phone guard
          -- precedent). Anything but an affirmative 'printer_only' â€” including a
          -- missing or tombstoned branch row â€” fails CLOSED.
          if v_customer_phone <> '' and not app.is_valid_customer_phone(v_customer_phone) then
            v_dispatch := jsonb_build_object(
              'ok', false, 'error', 'invalid_payload', 'detail', 'customer_phone');
          elsif v_requested_dispatch not in ('kds', 'direct_print') then
            v_dispatch := jsonb_build_object(
              'ok', false, 'error', 'invalid_payload', 'detail', 'dispatch_mode');
          elsif v_requested_dispatch = 'direct_print'
                and coalesce(v_branch_kitchen_mode, '') <> 'printer_only' then
            v_dispatch := jsonb_build_object(
              'ok', false, 'error', 'dispatch_mode_not_allowed',
              'detail', 'direct_print_requires_printer_only_branch');
          else
            v_dispatch := app.submit_order(
              p_pin_session_id,
              (v_payload ->> 'order_id')::uuid,
              p_device_id,
              v_local_op,
              v_payload ->> 'order_type',
              nullif(v_payload ->> 'table_id', '')::uuid,
              nullif(v_payload ->> 'shift_id', '')::uuid,
              v_payload ->> 'currency_code',
              v_payload ->> 'notes',
              v_payload -> 'order_items',
              (v_payload ->> 'subtotal_minor')::bigint,
              (v_payload ->> 'discount_total_minor')::bigint,
              (v_payload ->> 'tax_total_minor')::bigint,
              (v_payload ->> 'grand_total_minor')::bigint,
              v_client_ts);
            -- ORDER-CUSTOMER-001: stamp the OPTIONAL customer display name on the
            -- order app.submit_order just created. Kept OUT of submit_order so its
            -- validated INSERT stays byte-unchanged. Money-free display text: trim
            -- + empty->null + 80-char cap. Tenant-scoped by v_org; the
            -- `customer_name is null` guard makes it idempotent (a replay returns
            -- the same order_id, already stamped) and never overwrites.
            v_customer_name := left(btrim(coalesce(v_payload ->> 'customer_name', '')), 80);
            if v_customer_name <> '' then
              update public.orders
                set customer_name = v_customer_name
                where id = (v_dispatch ->> 'order_id')::uuid
                  and organization_id = v_org
                  and customer_name is null;
            end if;
            -- POS-CUSTOMER-PHONE-DINEIN-CLOSE-001: stamp the validated OPTIONAL
            -- customer phone parallel to customer_name. Tenant-scoped; the
            -- `customer_phone is null` guard makes an offline replay idempotent
            -- (a replay returns the same order_id, already stamped) and never
            -- overwrites. The value was validated BEFORE submit_order below.
            if v_customer_phone <> '' then
              update public.orders
                set customer_phone = v_customer_phone
                where id = (v_dispatch ->> 'order_id')::uuid
                  and organization_id = v_org
                  and customer_phone is null;
            end if;
            -- KITCHEN-MODE-001C1-CORRECTION-001: the initial kitchen dispatch
            -- payload is built inside app.submit_order BEFORE this stamp, so on
            -- the REAL push path customer_display_name was missing. Rebuild the
            -- COMPLETE normalized payload through the trusted internal server
            -- builder IN THIS SAME TRANSACTION â€” never by patching client JSON
            -- in, never after a client could have seen it (claimed / completed
            -- / superseded rows are left untouched; inside this first-apply
            -- transaction the row is not yet visible to any puller), never
            -- duplicating the dispatch or its audit row (no INSERT, no audit
            -- here). The row only exists for printer_only branches, so kds
            -- branches are a structural no-op; the guard trigger re-proves the
            -- rebuilt payload money-free on UPDATE.
            if v_customer_name <> '' then
              update public.kitchen_print_dispatches kd
                set money_free_payload = app.kitchen_dispatch_payload_initial(v_org, (v_dispatch ->> 'order_id')::uuid),
                    updated_at = now()
                where kd.organization_id = v_org
                  and kd.order_id = (v_dispatch ->> 'order_id')::uuid
                  and kd.dispatch_type = 'initial_order'
                  and kd.claimed_at is null
                  and kd.completed_at is null
                  and kd.superseded_by_dispatch_id is null;
            end if;
            -- KITCHEN-PRINT-DUAL-001C: a direct_print order is dispatched to the
            -- kitchen via the POS printer (no KDS device), IN THIS SAME transaction
            -- â€” a concurrent sync_pull can never observe an intermediate active
            -- state (sync_push commits once). app.submit_order already ran above, so
            -- the outcome here is CONDITIONAL, not an unconditional promotion:
            --   * CHARGEABLE printer_only order, still `submitted` -> the helper
            --     routes it OUT of the KDS active workflow: served +
            --     dispatch_mode=direct_print, dispatched=true; completion still
            --     waits for settlement.
            --   * ZERO-TOTAL printer_only order -> app.submit_order ALREADY
            --     completed it (a zero balance is settled on arrival), so the helper
            --     declines with dispatched=false / reason=not_eligible and the order
            --     stays completed / dispatch_mode='kds' / revision 2.
            -- Settlement is NEVER bypassed and physical print success NEVER completes
            -- an order; the POS local kitchen print is a separate best-effort client
            -- path and is not represented in this result. A 'kds' (default) order is
            -- a structural no-op here.
            if v_requested_dispatch = 'direct_print' then
              -- Merge the ADDITIVE outcome (order_status/revision/auto_completed)
              -- into the envelope so the client sees the FINAL committed state,
              -- exactly like the zero-total submit tail. A no-op replay merges only
              -- {dispatched:false} (submit_order's replay already re-reads the
              -- current revision), so the envelope stays correct.
              v_dispatch := v_dispatch || app.apply_direct_print_dispatch(
                v_org, v_rest, v_branch, (v_dispatch ->> 'order_id')::uuid,
                v_emp, v_membership, p_device_id, v_local_op);
            end if;
          end if;
        when 'order.discount' then
          -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 1 (§4.55.3): the claim guard;
          -- NULL lets the unchanged dispatch below run.
          v_dispatch := app.card_claim_guard(p_pin_session_id, p_device_id,
            case when pg_input_is_valid(v_payload ->> 'order_id', 'uuid') then (v_payload ->> 'order_id')::uuid end,
            v_local_op, v_op_type, null, null);
          if v_dispatch is null then
          v_dispatch := app.apply_discount(
            p_pin_session_id,
            (v_payload ->> 'order_id')::uuid,
            p_device_id,
            v_local_op,
            v_payload ->> 'scope',
            nullif(v_payload ->> 'order_item_id', '')::uuid,
            v_payload ->> 'discount_type',
            (v_payload ->> 'value')::bigint,
            v_payload ->> 'reason',
            nullif(v_payload ->> 'expected_revision', '')::integer);
          end if;
        when 'payment.create' then
          -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 1 (§4.55.3): the claim guard;
          -- NULL lets the unchanged dispatch below run.
          v_dispatch := app.card_claim_guard(p_pin_session_id, p_device_id,
            case when pg_input_is_valid(v_payload ->> 'order_id', 'uuid') then (v_payload ->> 'order_id')::uuid end,
            v_local_op, v_op_type, v_payload ->> 'tender_type', null);
          if v_dispatch is null then
          v_dispatch := app.record_payment(
            p_pin_session_id,
            (v_payload ->> 'order_id')::uuid,
            p_device_id,
            v_local_op,
            v_payload ->> 'tender_type',
            (v_payload ->> 'amount_tendered_minor')::bigint,
            nullif(v_payload ->> 'provisional_receipt_number', ''),
            nullif(v_payload ->> 'expected_revision', '')::integer);
          end if;
        when 'shift.close' then
          -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 1 (D-055): the shift-close
          -- exclusion of the claim guard; NULL lets the unchanged close run.
          v_dispatch := app.card_claim_guard(p_pin_session_id, p_device_id, null, v_local_op, v_op_type, null,
            case when pg_input_is_valid(v_payload ->> 'shift_id', 'uuid') then (v_payload ->> 'shift_id')::uuid end);
          if v_dispatch is null then
          v_dispatch := app.close_shift(
            p_pin_session_id,
            (v_payload ->> 'shift_id')::uuid,
            p_device_id,
            v_local_op,
            (v_payload ->> 'counted_amount_minor')::bigint,
            nullif(v_payload ->> 'reason', ''),
            nullif(v_payload ->> 'expected_revision', '')::integer);
          end if;
        -- MVP addition: KDS/POS order-status updates ride the SAME outbox/ledger
        -- (D-010/D-022). Scope/actor come from the pin session + device passed
        -- through (A8); the payload contributes ONLY {order_id, new_status}.
        when 'order.status' then
          v_dispatch := app.update_order_status(
            p_pin_session_id,
            p_device_id,
            (v_payload ->> 'order_id')::uuid,
            v_payload ->> 'new_status',
            v_local_op);
        when 'order.void' then
          -- MONEY-VOID-001: role-gated void of a wrong UNPAID order. Mirrors the
          -- order.discount branch - actor/org/branch come from the PIN session
          -- (never the payload) and the op's local_operation_id threads
          -- app.void_order's own idempotency (D-022). app.void_order (RF-053,
          -- hardened by RF-062) enforces manager/restaurant_owner/org_owner (or a
          -- cashier with permissions.void_order='true'), a mandatory reason, legal
          -- source states (submitted/accepted/preparing/ready/served), and the
          -- completed-payment block (an order with a live completed payment
          -- returns permission_denied) - so paid orders are refused server-side.
          -- Money-free: it only sets orders.status='voided' + void_reason +
          -- revision and cascades items -> voided; no payment/total is touched.
          -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 1 (§4.55.3): the claim guard;
          -- NULL lets the unchanged dispatch below run.
          v_dispatch := app.card_claim_guard(p_pin_session_id, p_device_id,
            case when pg_input_is_valid(v_payload ->> 'order_id', 'uuid') then (v_payload ->> 'order_id')::uuid end,
            v_local_op, v_op_type, null, null);
          if v_dispatch is null then
          v_dispatch := app.void_order(
            p_pin_session_id,
            (v_payload ->> 'order_id')::uuid,
            p_device_id,
            v_local_op,
            v_payload ->> 'reason',
            nullif(v_payload ->> 'expected_revision', '')::integer);
          end if;
        when 'order.table_move' then
          -- RESTAURANT-OPERATIONS-V1-001: atomic dine-in table move. Mirrors the
          -- order.void branch â€” actor/org/branch come from the PIN session
          -- (never the payload); the op's local_operation_id threads
          -- app.move_order_table's ORDER-BOUND idempotency (D-022); the payload
          -- contributes ONLY {order_id, table_id[, expected_revision]}. Typed
          -- refusals (table_not_allowed / invalid_transition+order_not_movable /
          -- table_not_available / permission_denied) RETURN through verbatim;
          -- a revision conflict raises 40001 -> the per-op 'conflict' status.
          -- Money-free: only orders.table_id + revision move.
          v_dispatch := app.move_order_table(
            p_pin_session_id,
            (v_payload ->> 'order_id')::uuid,
            p_device_id,
            v_local_op,
            nullif(v_payload ->> 'table_id', '')::uuid,
            nullif(v_payload ->> 'expected_revision', '')::integer);
        when 'menu.availability_set' then
          -- PILOT-OPERATIONS-CORRECTIONS-001: a cashier (default-ON
          -- manage_menu_availability) or manager+ sets a menu item's per-branch
          -- availability from the POS. Actor/org/branch derive from the PIN
          -- session (NEVER the payload); the capability is enforced inside. The
          -- payload contributes ONLY {menu_item_id, availability, reason}. The
          -- setter is naturally idempotent (no-change re-applies the same state
          -- with no audit) and transport dedup (sync_operations) guards replay.
          -- Typed RETURN refusals (permission_denied / not_found) survive
          -- verbatim. MONEY-FREE.
          v_dispatch := app.pos_set_item_availability(
            p_pin_session_id,
            p_device_id,
            (v_payload ->> 'menu_item_id')::uuid,
            v_payload ->> 'availability',
            nullif(v_payload ->> 'reason', ''));
        when 'table.status_set' then
          -- PILOT-OPERATIONS-CORRECTIONS-001: manual table floor-state from the
          -- POS (manage_table_operations). Scope/actor from the session; payload
          -- {table_id, status}. Typed refusals survive verbatim. MONEY-FREE.
          v_dispatch := app.pos_set_table_status(
            p_pin_session_id, p_device_id,
            (v_payload ->> 'table_id')::uuid,
            v_payload ->> 'status');
        when 'table.link' then
          -- Link two same-branch tables into an operational group (no order/bill
          -- merge). Payload {table_id_a, table_id_b}. Deterministic lock order.
          v_dispatch := app.pos_link_tables(
            p_pin_session_id, p_device_id,
            (v_payload ->> 'table_id_a')::uuid,
            (v_payload ->> 'table_id_b')::uuid);
        when 'table.unlink' then
          -- Dissolve the group a table belongs to (orders untouched). Payload
          -- {table_id}.
          v_dispatch := app.pos_unlink_tables(
            p_pin_session_id, p_device_id,
            (v_payload ->> 'table_id')::uuid);
        when 'cash_drawer.no_sale_open' then
          -- POS-CASH-DRAWER-MANUAL-OPEN-001: a MANUAL ("no-sale") drawer open
          -- recorded from the POS. Actor/org/branch/device come from the PIN
          -- session (NEVER the payload); the payload contributes ONLY the
          -- client's own occurrence time and, for a journaled offline open, the
          -- PIN session that made it (validated inside against THIS device +
          -- branch). A malformed occurrence time degrades to NULL rather than
          -- rejecting the record of a physical open. The permission is enforced
          -- inside; typed refusals (permission_denied / invalid_device_type /
          -- invalid_origin_session) RETURN through verbatim. Transport dedup
          -- (sync_operations) makes a replay return the stored result -- one
          -- open, one audit row. MONEY-FREE.
          v_dispatch := app.pos_record_drawer_no_sale(
            p_pin_session_id, p_device_id,
            case when pg_input_is_valid(v_payload ->> 'client_occurred_at', 'timestamptz')
                 then (v_payload ->> 'client_occurred_at')::timestamptz end,
            nullif(v_payload ->> 'origin_pin_session_id', '')::uuid);
        when 'order.void_ack' then
          -- PSC-001D: the kitchen's cancellation acknowledgement. Mirrors the
          -- order.status branch â€” actor/org/branch come from the PIN session
          -- (never the payload); the payload contributes ONLY {order_id}.
          -- app.kitchen_ack_void enforces the KDS-class device, the kitchen
          -- role set, the voided + ack-required state, and the idempotent
          -- already-acknowledged replay; its flat typed refusals
          -- (invalid_device_type / permission_denied / order_not_voided /
          -- acknowledgement_not_required) RETURN through verbatim. TARGET-ID
          -- CONSISTENCY is enforced at (b1+) BEFORE the fingerprint and the
          -- terminal replay â€” by the time this arm runs, target_id and
          -- payload.order_id are guaranteed present, valid and equal. The
          -- check below is pure defence-in-depth and unreachable. MONEY-FREE.
          if v_target_id is null
             or v_target_id <> (v_payload ->> 'order_id')::uuid then
            raise exception 'sync_push: order.void_ack target_id does not match payload.order_id' using errcode = '42501';
          end if;
          v_dispatch := app.kitchen_ack_void(
            p_pin_session_id,
            (v_payload ->> 'order_id')::uuid,
            p_device_id,
            v_local_op);
        when 'order.items_add' then
          -- PSC-001C: add items to an existing eligible dine-in order as ONE
          -- new authoritative service round. Actor/org/branch come from the
          -- PIN session; the payload contributes {order_id, order_items}.
          -- app.add_order_items enforces the POS-class device, the cashier+
          -- role set, eligibility (dine_in, open status, no completed
          -- payment), submit_order-parity pricing/sellability, and round-level
          -- idempotency; its flat typed refusals (invalid_device_type /
          -- permission_denied / order_not_dine_in / order_not_eligible /
          -- order_already_settled / item_unavailable / invalid_item_payload)
          -- RETURN through verbatim. TARGET-ID CONSISTENCY is enforced at
          -- (b1+) BEFORE the fingerprint and the terminal replay â€” the check
          -- below is pure defence-in-depth and unreachable.
          if v_target_id is null
             or v_target_id <> (v_payload ->> 'order_id')::uuid then
            raise exception 'sync_push: order.items_add target_id does not match payload.order_id' using errcode = '42501';
          end if;
          -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 1 (§4.55.3): the claim guard;
          -- NULL lets the unchanged dispatch below run.
          v_dispatch := app.card_claim_guard(p_pin_session_id, p_device_id,
            case when pg_input_is_valid(v_payload ->> 'order_id', 'uuid') then (v_payload ->> 'order_id')::uuid end,
            v_local_op, v_op_type, null, null);
          if v_dispatch is null then
          v_dispatch := app.add_order_items(
            p_pin_session_id,
            (v_payload ->> 'order_id')::uuid,
            p_device_id,
            v_local_op,
            v_payload -> 'order_items',
            v_client_ts);
          end if;
        when 'order.round_status' then
          -- PSC-001C: the additional service round's own single-step
          -- lifecycle. Actor/org/branch come from the PIN session; the
          -- payload contributes {round_id, new_status}. app.update_round_status
          -- enforces the LOCKED device/role matrix (production steps KDS-only;
          -- ready->served KDS kitchen set or POS cashier set), the parent
          -- guards, single-step legality, the WRITE-ONCE ready_at stamp and
          -- the completion chain; its flat typed refusals RETURN through
          -- verbatim. TARGET-ID CONSISTENCY (against payload.round_id) is
          -- enforced at (b1+) â€” the check below is pure defence-in-depth and
          -- unreachable. MONEY-FREE.
          if v_target_id is null
             or v_target_id <> (v_payload ->> 'round_id')::uuid then
            raise exception 'sync_push: order.round_status target_id does not match payload.round_id' using errcode = '42501';
          end if;
          v_dispatch := app.update_round_status(
            p_pin_session_id,
            (v_payload ->> 'round_id')::uuid,
            p_device_id,
            v_payload ->> 'new_status',
            v_local_op);
        when 'order.edit' then
          -- ORDER-EDIT-001A (D-043): edit a sent, open, unpaid order in place.
          -- An ONLINE-ONLY direct op (never the offline outbox). Actor/org/branch
          -- come from the PIN session; the payload contributes {order_id,
          -- reason_code?, reason_text?, bill_presented_at?, expected, changes}.
          -- app.edit_order decides EVERY refusal before its first write and
          -- RETURNs it verbatim (audited order.edit_denied); it RAISES only
          -- 42501 (structural / anti-oracle) and 40001 (operation id reused on
          -- another order). TARGET-ID CONSISTENCY is enforced at (b1+) - the
          -- check below is pure defence-in-depth and unreachable.
          if v_target_id is null
             or v_target_id <> (v_payload ->> 'order_id')::uuid then
            raise exception 'sync_push: order.edit target_id does not match payload.order_id' using errcode = '42501';
          end if;
          -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 1 (§4.55.3): the claim guard;
          -- NULL lets the unchanged dispatch below run.
          v_dispatch := app.card_claim_guard(p_pin_session_id, p_device_id,
            case when pg_input_is_valid(v_payload ->> 'order_id', 'uuid') then (v_payload ->> 'order_id')::uuid end,
            v_local_op, v_op_type, null, null);
          if v_dispatch is null then
          v_dispatch := app.edit_order(
            p_pin_session_id,
            (v_payload ->> 'order_id')::uuid,
            p_device_id,
            v_local_op,
            v_payload,
            v_client_ts);
          end if;
        when 'order.edit_ack' then
          -- ORDER-EDIT-001A (D-044): the kitchen's "Got it" for order edits.
          -- The payload contributes ONLY {order_id, up_to_edit_number}; a
          -- missing or malformed number reaches app.kitchen_ack_order_edit as
          -- NULL and is refused there (invalid_edit_number). Its flat typed
          -- refusals (invalid_device_type / permission_denied /
          -- invalid_edit_number / order_voided) RETURN through verbatim.
          -- TARGET-ID CONSISTENCY is enforced at (b1+) - the check below is pure
          -- defence-in-depth and unreachable. MONEY-FREE.
          if v_target_id is null
             or v_target_id <> (v_payload ->> 'order_id')::uuid then
            raise exception 'sync_push: order.edit_ack target_id does not match payload.order_id' using errcode = '42501';
          end if;
          v_dispatch := app.kitchen_ack_order_edit(
            p_pin_session_id,
            (v_payload ->> 'order_id')::uuid,
            p_device_id,
            v_local_op,
            case when jsonb_typeof(v_payload -> 'up_to_edit_number') = 'number'
                      and (v_payload ->> 'up_to_edit_number') ~ '^[0-9]{1,9}$'
                 then (v_payload ->> 'up_to_edit_number')::integer end);
      end case;
      v_dispatch_ok := coalesce((v_dispatch ->> 'ok')::boolean, false);
    exception
      when others then
        v_caught_state := SQLSTATE;
        v_caught_msg   := SQLERRM;
    end;

    -- (b6) finalize the operation outcome
    if v_caught_state is not null then
      -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D change 4 (D-057 point 8): an
      -- infrastructure or transaction failure inside the dispatch of a
      -- card-sensitive operation is never memoized as a permanent rejection;
      -- the dispatched RPC's own raises (exact prefixes record_payment: /
      -- close_shift:) keep today's handling.
      v_card_sensitive := v_op_type = 'shift.close'
        or (v_op_type = 'payment.create'
            and (v_recording_resume is not null
                 or exists (select 1 from app.card_provider_attempts ca
                             where ca.organization_id = v_org and ca.device_id = p_device_id
                               and ca.local_operation_id = v_local_op)));
      if v_card_sensitive and left(v_caught_state, 2) in ('08', '40', '53', '55', '57', '58', 'XX')
         and not starts_with(v_caught_msg, 'record_payment:') and not starts_with(v_caught_msg, 'close_shift:') then
        update public.sync_operations
          set status = 'pending', last_error_code = v_caught_state, last_error_class = 'transient', updated_at = now()
          where id = v_so_id;
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'ok', false,
          'error', 'transient_failure', 'retryable', true, 'status', 'pending', 'idempotency_replay', false);
      elsif v_caught_state = '40001' then
        update public.sync_operations
          set status = 'conflict', last_error_code = v_caught_state, last_error_class = 'conflict',
              conflict_info = jsonb_build_object('sqlstate', v_caught_state, 'message', v_caught_msg),
              result = jsonb_build_object('ok', false, 'error', 'conflict', 'sqlstate', v_caught_state), updated_at = now()
          where id = v_so_id;
        insert into public.audit_events (organization_id, restaurant_id, branch_id, actor_app_user_id, actor_employee_profile_id, device_id, action, reason, old_values, new_values)
        values (v_org, v_rest, v_branch, null, v_emp, p_device_id, 'sync.operation_conflict', v_caught_msg, null,
                jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'sqlstate', v_caught_state));
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'ok', false,
          'error', 'conflict', 'sqlstate', v_caught_state, 'status', 'conflict', 'idempotency_replay', false);
      elsif v_caught_state = 'RFDM0' then
        -- KITCHEN-DISPATCH-ENFORCE-001: the app.apply_direct_print_dispatch
        -- defensive belt fired. Normalize the DEDICATED internal SQLSTATE to the
        -- SAME terminal typed rejection the primary ingest guard returns â€” the
        -- ledger, the audit and the client envelope all carry
        -- `dispatch_mode_not_allowed` (class permanent) and NEVER a raw SQLSTATE
        -- or any internal branch-mode detail. The raise already rolled this
        -- operation's subtransaction back, so no business rows survive. The
        -- stored result is what a replay returns, so the rejection is idempotent.
        update public.sync_operations
          set status = 'rejected', last_error_code = 'dispatch_mode_not_allowed', last_error_class = 'permanent',
              rejection_reason = 'dispatch_mode_not_allowed',
              result = jsonb_build_object('ok', false, 'error', 'dispatch_mode_not_allowed',
                         'detail', 'direct_print_requires_printer_only_branch'), updated_at = now()
          where id = v_so_id;
        insert into public.audit_events (organization_id, restaurant_id, branch_id, actor_app_user_id, actor_employee_profile_id, device_id, action, reason, old_values, new_values)
        values (v_org, v_rest, v_branch, null, v_emp, p_device_id, 'sync.operation_rejected', 'dispatch_mode_not_allowed', null,
                jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'error', 'dispatch_mode_not_allowed'));
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'ok', false,
          'error', 'dispatch_mode_not_allowed', 'detail', 'direct_print_requires_printer_only_branch',
          'status', 'rejected', 'idempotency_replay', false);
      else
        -- STALE-TABLE-ORDER-RECOVERY-001 (error contract): a dispatched RPC's
        -- PRECONDITION refusal - the message carries '(precondition_failed)', e.g.
        -- record_payment with no open shift / no active drawer on the paying device -
        -- is classified as the stable detail token 'precondition_failed' so the POS
        -- can say exactly that (open a shift) instead of a generic failure. Every
        -- other message still collapses to the generic 'rejected' (never raw text).
        -- validation / state / business-rule failure -> permanent rejected. RF-061: a
        -- revoked-MEMBERSHIP op fails membership-active in the dispatched RPC; classify its
        -- rejection reason as 'revoked_employee' so the offline-revoked-employee case is clear.
        update public.sync_operations
          set status = 'rejected', last_error_code = v_caught_state, last_error_class = 'permanent',
              rejection_reason = case when v_caught_msg ilike '%resolved membership is not active%' then 'revoked_employee'
                                 when v_caught_msg ilike '%(precondition_failed)%' then 'precondition_failed'
                                 else v_caught_msg end,
              result = jsonb_build_object('ok', false, 'error', 'rejected', 'sqlstate', v_caught_state,
                         'detail', case when v_caught_msg ilike '%resolved membership is not active%' then 'revoked_employee'
                                 when v_caught_msg ilike '%(precondition_failed)%' then 'precondition_failed'
                                 else null end), updated_at = now()
          where id = v_so_id;
        insert into public.audit_events (organization_id, restaurant_id, branch_id, actor_app_user_id, actor_employee_profile_id, device_id, action, reason, old_values, new_values)
        values (v_org, v_rest, v_branch, null, v_emp, p_device_id, 'sync.operation_rejected',
                case when v_caught_msg ilike '%resolved membership is not active%' then 'revoked_employee'
                                 when v_caught_msg ilike '%(precondition_failed)%' then 'precondition_failed'
                                 else v_caught_msg end, null,
                jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'sqlstate', v_caught_state));
        v_results := v_results || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'ok', false,
          'error', 'rejected', 'sqlstate', v_caught_state,
          'detail', case when v_caught_msg ilike '%resolved membership is not active%' then 'revoked_employee'
                                 when v_caught_msg ilike '%(precondition_failed)%' then 'precondition_failed'
                                 else null end,
          'status', 'rejected', 'idempotency_replay', false);
      end if;
    elsif v_dispatch_ok then
      update public.sync_operations
        set status = 'applied', result = v_dispatch, applied_at = now(),
            target_id = coalesce(v_target_id, nullif(v_dispatch ->> 'order_id', '')::uuid, nullif(v_dispatch ->> 'shift_id', '')::uuid, nullif(v_dispatch ->> 'payment_id', '')::uuid),
            updated_at = now()
        where id = v_so_id;
      v_results := v_results || (v_dispatch
        || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'status', 'applied', 'idempotency_replay', false));
    else
      update public.sync_operations
        set status = 'rejected', last_error_code = coalesce(v_dispatch ->> 'error', 'rejected'), last_error_class = 'permanent',
            rejection_reason = coalesce(v_dispatch ->> 'error', 'rejected'), result = v_dispatch, updated_at = now()
        where id = v_so_id;
      insert into public.audit_events (organization_id, restaurant_id, branch_id, actor_app_user_id, actor_employee_profile_id, device_id, action, reason, old_values, new_values)
      values (v_org, v_rest, v_branch, null, v_emp, p_device_id, 'sync.operation_rejected', coalesce(v_dispatch ->> 'error', 'rejected'), null,
              jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'error', coalesce(v_dispatch ->> 'error', 'rejected')));
      v_results := v_results || (v_dispatch
        || jsonb_build_object('local_operation_id', v_local_op, 'operation_type', v_op_type, 'status', 'rejected', 'idempotency_replay', false));
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'results', v_results, 'server_ts', now());
end;
$function$;
-- ACL parity (CREATE OR REPLACE preserves grants; re-issued explicitly, verbatim).
revoke all on function app.sync_push(uuid, uuid, jsonb) from public;
revoke all on function app.sync_push(uuid, uuid, jsonb) from anon;
grant execute on function app.sync_push(uuid, uuid, jsonb) to authenticated;
do $do$
begin
  execute format('comment on function app.sync_push(uuid, uuid, jsonb) is %L',
    obj_description('app.sync_push(uuid, uuid, jsonb)'::regprocedure, 'pg_proc')
    || ' BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D: + the card-present admission (terminal and full-identity advisory locks), the single-operation and transient rules for card-sensitive operations, the pre-ledger TEST refusal, the protected recording_resume parse with the D-054 reopen, and app.card_claim_guard in the payment.create / order.discount / order.edit / order.items_add / order.void / shift.close arms; refuses a request made in an active platform support session (D-060); no operation type added.');
end;
$do$;


-- ----------------------------------------------------------------------------
-- 9.2 The read and Activity-log surfaces — each re-emitted from its LIVE body
--     (pin_session_capabilities 20261008190000 L1092-1221; pos_order_snapshots
--     20261008190000 L779-1076; audit_action_has_detail 20261008170200
--     L1334-1388; audit_safe_detail 20261008170200 L1401-1536;
--     owner_audit_events 20261008170200 L2045-2267; audit_category
--     20260725090000 L2797-2824) with ONLY the marked 001D additions; the
--     signatures, volatility, security, search_path and ACLs are unchanged
--     (ACLs re-stated verbatim); the public wrappers are untouched.
-- ----------------------------------------------------------------------------
create or replace function app.pin_session_capabilities(
  p_pin_session_id uuid,
  p_device_id      uuid
)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_org        uuid;
  v_rest       uuid;
  v_branch     uuid;
  v_dsid       uuid;
  v_membership uuid;
  v_ds_org     uuid;
  v_ds_rest    uuid;
  v_ds_branch  uuid;
  v_ds_device  uuid;
  v_ds_active  boolean;
  v_ds_revoked timestamptz;
  v_pairing    text;
  v_role       text;
  v_m_status   text;
  v_m_deleted  timestamptz;
  v_m_perms    jsonb;
  v_b_enabled  boolean;  -- ORDER-EDIT-001B: branches.order_edit_enabled
  v_b_ff       boolean;  -- ORDER-EDIT-001B: branches.order_edit_finished_food_manager_only
begin
  -- (a) THE CANONICAL PIN-SESSION PREAMBLE — the one app.apply_discount actually
  --     uses, not an approximation of it. EVERY failure below (unknown session,
  --     inactive, expired, dead device session, revoked device, inactive pairing,
  --     device mismatch, scope mismatch, dead membership) returns ONE
  --     INDISTINGUISHABLE envelope. A caller must never learn WHICH check failed —
  --     that would turn a capability probe into an existence/scope oracle across
  --     tenants (RISK R-003).
  select ps.organization_id, ps.restaurant_id, ps.branch_id,
         ps.device_session_id, ps.resolved_membership_id
    into v_org, v_rest, v_branch, v_dsid, v_membership
    from public.pin_sessions ps
    where ps.id = p_pin_session_id;
  -- app.is_pin_session_valid is the SHARED validity rule (active + not expired +
  -- not ended). Use the helper; do not re-implement its predicate here.
  if not found or not app.is_pin_session_valid(p_pin_session_id) then
    return jsonb_build_object('ok', false, 'error', 'invalid_session', 'entity', 'pin_session');
  end if;

  select ds.organization_id, ds.restaurant_id, ds.branch_id,
         ds.device_id, ds.is_active, ds.revoked_at, dp.status
    into v_ds_org, v_ds_rest, v_ds_branch,
         v_ds_device, v_ds_active, v_ds_revoked, v_pairing
    from public.device_sessions ds
    join public.device_pairings dp on dp.id = ds.device_pairing_id
    where ds.id = v_dsid;
  if not found
     or not (v_ds_active and v_ds_revoked is null and v_pairing = 'active')
     or v_ds_device is distinct from p_device_id
     -- The PIN session and its backing device session MUST agree on scope. They are
     -- FK-linked at creation so this cannot diverge today; a capability oracle is
     -- precisely the wrong place to take that on trust.
     or v_ds_org    is distinct from v_org
     or v_ds_rest   is distinct from v_rest
     or v_ds_branch is distinct from v_branch then
    return jsonb_build_object('ok', false, 'error', 'invalid_session', 'entity', 'pin_session');
  end if;

  -- The membership is resolved through the session's OWN resolved_membership_id --
  -- the authoritative pointer -- not by re-deriving it from employee_profiles.
  select m.role, m.status, m.deleted_at, m.permissions
    into v_role, v_m_status, v_m_deleted, v_m_perms
    from public.memberships m
    where m.id = v_membership and m.organization_id = v_org;
  if not found or v_m_status <> 'active' or v_m_deleted is not null then
    return jsonb_build_object('ok', false, 'error', 'invalid_session', 'entity', 'pin_session');
  end if;

  -- (a1) ORDER-EDIT-001B: the session branch's two edit switches (§4.45.8),
  --      read with app.edit_order's row predicate but without its share lock
  --      (this read is STABLE). An unreadable branch row leaves both NULL and
  --      they are reported FALSE (the POS hides "Edit order"); it never fails
  --      the probe, so the existing capabilities are unaffected.
  select b.order_edit_enabled, b.order_edit_finished_food_manager_only
    into v_b_enabled, v_b_ff
    from public.branches b
    where b.id = v_branch and b.organization_id = v_org and b.deleted_at is null;

  -- (b) EFFECTIVE rights -- byte-for-byte the predicates app.apply_discount enforces,
  --     so the client can never disagree with the server about what it may do. The
  --     capability MODEL is unchanged by this hotfix:
  --       apply_discount  = manager+ OR the DEFAULT-ON cashier capability (deny-only)
  --       apply_full_comp = manager+ OR the DEFAULT-OFF cashier grant (grant-only)
  --     Both resolvers are total and return BOOLEAN, never null: a missing override
  --     key resolves to false for apply_full_comp (grant-only => absence denies), and
  --     malformed permissions JSON fails closed in both.
  --     NOTHING here leaks: no permissions JSON, no membership/employee/session UUID,
  --     no PIN material, no money, no order data -- only the role and two booleans.
  return jsonb_build_object(
    'ok', true, 'entity', 'pin_session', 'role', v_role,
    'capabilities', jsonb_build_object(
      'apply_discount',
        (v_role in ('manager', 'restaurant_owner', 'org_owner'))
        or app.cashier_capability_allowed(v_role, v_m_perms, 'apply_discount'),
      'apply_full_comp',
        (v_role in ('manager', 'restaurant_owner', 'org_owner'))
        or app.cashier_capability_granted(v_role, v_m_perms, 'apply_full_comp'),
      'manage_menu_availability',
        (v_role in ('manager', 'restaurant_owner', 'org_owner'))
        or app.cashier_capability_allowed(v_role, v_m_perms, 'manage_menu_availability'),
      'manage_table_operations',
        (v_role in ('manager', 'restaurant_owner', 'org_owner'))
        or app.cashier_capability_allowed(v_role, v_m_perms, 'manage_table_operations'),
      -- POS-CASH-DRAWER-MANUAL-OPEN-001: manual drawer open. manager+ BY ROLE, or a
      -- cashier the owner explicitly GRANTED (grant-only => absence denies).
      'open_cash_drawer',
        (v_role in ('manager', 'restaurant_owner', 'org_owner'))
        or app.cashier_capability_granted(v_role, v_m_perms, 'open_cash_drawer'),
      -- ORDER-EDIT-001B (D-043): the effective void_order right, byte-for-byte
      -- the predicate app.void_order and app.edit_order's removal gate enforce
      -- (manager+ BY ROLE, or the DEFAULT-ON cashier capability, deny-only).
      'void_order',
        (v_role in ('manager', 'restaurant_owner', 'org_owner'))
        or app.cashier_capability_allowed(v_role, v_m_perms, 'void_order')),
    -- ORDER-EDIT-001B: the session branch's two switches, for every role; two
    -- money-free booleans of the caller's OWN branch (no identifier).
    'branch_features', jsonb_build_object(
      'order_edit_enabled',                    coalesce(v_b_enabled, false),
      'order_edit_finished_food_manager_only', coalesce(v_b_ff, false))
      -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (§4.30b): card_terminal_enabled and
      -- card_terminal_mode, present only while the session's exact device has a
      -- configured / enabled / draining binding (absent => the terminal action
      -- stays hidden; advisory, the server mapping and revision are authority).
      || coalesce((select jsonb_build_object('card_terminal_enabled', (t.p ->> 'enabled')::boolean,
                                             'card_terminal_mode', t.p ->> 'mode')
                     from (select app.card_terminal_posture(v_org, v_branch, p_device_id) as p) t
                    where t.p is not null), '{}'::jsonb));
end;
$$;
revoke all on function app.pin_session_capabilities(uuid, uuid) from public;
revoke all on function app.pin_session_capabilities(uuid, uuid) from anon;
grant execute on function app.pin_session_capabilities(uuid, uuid) to authenticated;

create or replace function app.pos_order_snapshots(
  p_pin_session_id uuid,
  p_device_id      uuid,
  p_since_at       timestamptz default null,
  p_since_id       uuid        default null,
  p_before_at      timestamptz default null,
  p_before_id      uuid        default null,
  p_order_ids      uuid[]      default null,
  p_limit          integer     default 50,
  p_window_days    integer     default 2
)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_org          uuid;
  v_branch       uuid;
  v_dsid         uuid;
  v_membership   uuid;
  v_ds_device    uuid;
  v_ds_active    boolean;
  v_ds_revoked   timestamptz;
  v_pairing      text;
  v_role         text;
  v_m_status     text;
  v_m_deleted    timestamptz;
  v_limit        integer;
  v_window_start timestamptz;
  v_rows         jsonb;
  v_count        integer;
  v_next_at      timestamptz;
  v_next_id      uuid;
  v_max_at       timestamptz;
  v_max_id       uuid;
  v_min_at       timestamptz;
  v_min_id       uuid;
  -- TRUE only for the INCREMENTAL change feed. The WINDOW pages DESCENDING.
  v_ascending    boolean;
begin
  -- (a) THE CANONICAL PIN-SESSION PREAMBLE (identical to app.apply_discount).
  --     Every failure -- bad session, expired, revoked device, wrong device,
  --     dead membership -- collapses to ONE indistinguishable envelope: a caller
  --     must not be able to probe WHICH check failed (RISK R-003).
  select ps.organization_id, ps.branch_id, ps.device_session_id, ps.resolved_membership_id
    into v_org, v_branch, v_dsid, v_membership
    from public.pin_sessions ps
    where ps.id = p_pin_session_id;
  if not found or not app.is_pin_session_valid(p_pin_session_id) then
    return jsonb_build_object('ok', false, 'error', 'invalid_session', 'entity', 'order_snapshot');
  end if;

  select ds.device_id, ds.is_active, ds.revoked_at, dp.status
    into v_ds_device, v_ds_active, v_ds_revoked, v_pairing
    from public.device_sessions ds
    join public.device_pairings dp on dp.id = ds.device_pairing_id
    where ds.id = v_dsid;
  if not found
     or not (v_ds_active and v_ds_revoked is null and v_pairing = 'active')
     or v_ds_device is distinct from p_device_id then
    return jsonb_build_object('ok', false, 'error', 'invalid_session', 'entity', 'order_snapshot');
  end if;

  select m.role, m.status, m.deleted_at
    into v_role, v_m_status, v_m_deleted
    from public.memberships m
    where m.id = v_membership and m.organization_id = v_org;
  if not found or v_m_status <> 'active' or v_m_deleted is not null then
    return jsonb_build_object('ok', false, 'error', 'invalid_session', 'entity', 'order_snapshot');
  end if;

  -- (b) INPUT VALIDATION -- FAIL CLOSED. A malformed cursor is REFUSED, never
  --     silently coerced into "start from the beginning": quietly restarting the
  --     cursor would re-deliver the whole window and look like success.
  if (p_since_at is null) <> (p_since_id is null) then
    return jsonb_build_object('ok', false, 'error', 'invalid_cursor', 'entity', 'order_snapshot');
  end if;
  if (p_before_at is null) <> (p_before_id is null) then
    return jsonb_build_object('ok', false, 'error', 'invalid_cursor', 'entity', 'order_snapshot');
  end if;
  -- The two cursors are DIFFERENT QUESTIONS and must never be asked at once: an
  -- ascending "what changed" and a descending "show me older" cannot both be honoured
  -- by one page, and silently picking one would give the caller a page it did not ask
  -- for while advancing a cursor it did not mean to move.
  if p_since_at is not null and p_before_at is not null then
    return jsonb_build_object('ok', false, 'error', 'invalid_cursor', 'entity', 'order_snapshot');
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    return jsonb_build_object('ok', false, 'error', 'invalid_limit', 'entity', 'order_snapshot');
  end if;
  if p_window_days is null or p_window_days < 1 or p_window_days > 14 then
    return jsonb_build_object('ok', false, 'error', 'invalid_window', 'entity', 'order_snapshot');
  end if;
  if p_order_ids is not null and array_length(p_order_ids, 1) > 100 then
    return jsonb_build_object('ok', false, 'error', 'invalid_limit', 'entity', 'order_snapshot');
  end if;
  v_limit        := p_limit;
  v_window_start := (now() at time zone 'utc')::date - make_interval(days => p_window_days - 1);

  -- MODE. Only an explicit `since` cursor asks the ASCENDING question ("what changed
  -- since I last looked"). Everything else -- including the very first, cursorless
  -- call -- is the WINDOW: newest first. That default is the whole fix. A cursorless
  -- call used to mean "ascend from the start of the window", which handed a busy
  -- branch its OLDEST rows and buried the newest order thousands of rows deep.
  v_ascending := (p_since_at is not null);

  -- (c) THE SNAPSHOT.
  --
  --     SCOPE: the PIN session's OWN organization_id AND branch_id, taken from the
  --     SERVER's session row -- never from anything the client sent. There is no
  --     parameter by which a caller could name another branch, restaurant or
  --     tenant, so a sibling-branch/sibling-restaurant/cross-tenant read is not
  --     "denied", it is UNREACHABLE.
  --
  --     SETTLEMENT: one LEFT JOIN on payments' UNIQUE partial index
  --     (payments_one_completed_per_order_uidx: at most ONE completed payment per
  --     order), so coverage is set-based -- no correlated subquery, no per-row
  --     aggregate, no N+1.
  --
  --     SYNC STAMP: greatest(o.updated_at, pay.updated_at). A payment does not
  --     touch the order row, so ordering on o.updated_at alone would never deliver
  --     a paid-but-not-yet-completed order to an incremental cursor.
  --
  --     ORDER-EDIT-001B: the stamp ALSO takes the newest updated_at of the
  --     order's service rounds and edits, for the same reason: a kitchen
  --     acknowledgement of an edit (§4.46) and a round status change write no
  --     orders row, so kitchen_edit_ack_pending and has_active_round would
  --     otherwise flip without ever reaching a POS. The max runs over EVERY
  --     round and edit row of the order (no status or tombstone filter), so the
  --     stamp never moves backwards; it is never lower than the old stamp. The
  --     two aggregates are bounded probes on (organization_id, order_id).
  with scoped as (
    select
      o.id,
      o.status,
      o.revision,
      o.order_type,
      o.created_at,
      o.updated_at,
      o.subtotal_minor,
      o.discount_total_minor,
      o.tax_total_minor,
      o.grand_total_minor,
      o.currency_code,
      o.edit_count,                                   -- ORDER-EDIT-001B
      -- The table's human LABEL, never its internal UUID (T-003 forbids projecting
      -- an internal id). `notes` and `customer_name` are deliberately NOT selected:
      -- private order notes are explicitly out of the safe set, and the POS already
      -- holds the customer name it typed -- a reconciliation read has no reason to
      -- ship personal data back.
      tbl.label as table_label,
      pay.amount_minor as covered_minor,
      -- ORDER-EDIT-001B: the order's live-round and pending-edit flags.
      rnd.active      as has_active_round,
      ed.ack_pending  as edit_ack_pending,
      -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (§4.30c; D-059 point 1): the
      -- active-claim flag and its delivery stamp. A claim, a state change, a
      -- free or a resolution writes only the private ledger, so the newest durable
      -- claim signal of the order's LIVE attempts joins the stamp (a poll counter,
      -- lookup stamp, mark, Resume counter or hold never advances it; the recording
      -- moves pay.updated_at).
      card.active     as card_attempt_in_progress,
      greatest(o.updated_at, coalesce(pay.updated_at, o.updated_at),
               coalesce(rnd.touched_at, o.updated_at),
               coalesce(ed.touched_at, o.updated_at),
               coalesce(card.touched_at, o.updated_at)) as sync_at
    from public.orders o
    left join public.tables tbl
      on  tbl.organization_id = o.organization_id
      and tbl.id              = o.table_id
    left join public.payments pay
      on  pay.organization_id = o.organization_id
      and pay.order_id        = o.id
      and pay.status          = 'completed'
      and pay.deleted_at is null
    -- ORDER-EDIT-001B: has_active_round = any live service round of the order
    -- in submitted..ready (the app.void_order live-round predicate).
    left join lateral (
      select max(r.updated_at) as touched_at,
             coalesce(bool_or(r.deleted_at is null
                              and r.status in ('submitted', 'accepted', 'preparing', 'ready')),
                      false) as active
        from public.order_service_rounds r
       where r.organization_id = o.organization_id
         and r.order_id        = o.id
    ) rnd on true
    -- ORDER-EDIT-001B: a required kitchen confirmation of an edit not yet
    -- given (the order_edits_pending_ack_idx predicate).
    left join lateral (
      select max(e.updated_at) as touched_at,
             coalesce(bool_or(e.deleted_at is null
                              and e.kitchen_ack_required
                              and e.kitchen_ack_at is null),
                      false) as ack_pending
        from public.order_edits e
       where e.organization_id = o.organization_id
         and e.order_id        = o.id
    ) ed on true
    -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (§4.55.3): an active claim = a LIVE
    -- attempt not freed and unresolved that is sent / unknown / released, or
    -- approved without its strict-join payment - counted over the order's own
    -- branch (D-059 point 1), the guard's set for every row the RPCs write.
    left join lateral (
      select max(ca.claim_signal_at) as touched_at,
             coalesce(bool_or(ca.order_freed_at is null and ca.resolution is null
                              and (ca.state in ('sent', 'unknown', 'released')
                                   or (ca.state = 'approved' and app.card_attempt_payment_id(ca) is null))),
                      false) as active
        from app.card_provider_attempts ca
       where ca.organization_id = o.organization_id
         and ca.branch_id       = o.branch_id
         and ca.order_id        = o.id
         and ca.mode            = 'live'
    ) card on true
    where o.organization_id = v_org
      and o.branch_id       = v_branch
      and o.deleted_at is null
      -- TARGETED mode ignores the window: a snapshot requested for a SPECIFIC
      -- order after a write must return it even if it sits outside the window.
      and (p_order_ids is not null or o.created_at >= v_window_start)
      and (p_order_ids is null or o.id = any (p_order_ids))
  ),
  stamped as (
    select
      s.*,
      case
        when s.grand_total_minor < 0  then 'unpaid'            -- FAIL CLOSED (money defect stays visible)
        when s.grand_total_minor = 0  then 'not_chargeable'    -- owes nothing; carries no payment row
        when coalesce(s.covered_minor, 0) >= s.grand_total_minor then 'paid'
        else 'unpaid'
      end as payment_status
    from scoped s
  ),
  -- THE PAGE. `v_ascending` is TRUE only for the INCREMENTAL feed; the WINDOW pages
  -- DESCENDING so the NEWEST order is the first row of the first page, whatever the
  -- volume. Both directions keyset on (sync_at, id) -- the ORDER ID is the
  -- tie-breaker, so rows sharing a sync_at to the microsecond cannot be duplicated
  -- across pages or skipped between them.
  page as (
    select *
    from stamped st
    where p_order_ids is not null
       or (v_ascending
             and (p_since_at is null
                  or (st.sync_at, st.id) > (p_since_at, p_since_id)))
       or ((not v_ascending)
             and (p_before_at is null
                  or (st.sync_at, st.id) < (p_before_at, p_before_id)))
    order by
      case when v_ascending then st.sync_at end asc,
      case when v_ascending then st.id      end asc,
      case when not v_ascending then st.sync_at end desc,
      case when not v_ascending then st.id      end desc
    limit v_limit
  )
  select
    coalesce(jsonb_agg(
      jsonb_build_object(
        'order_id',             p.id,
        -- The SAFE public reference, never the raw UUID (T-003).
        'order_code',           '#' || upper(right(replace(p.id::text, '-', ''), 6)),
        'revision',             p.revision,
        'status',               p.status,
        'order_type',           p.order_type,
        'table_label',          p.table_label,
        'currency_code',        p.currency_code,
        'created_at',           p.created_at,
        'updated_at',           p.updated_at,
        'sync_at',              p.sync_at,
        'subtotal_minor',       p.subtotal_minor,
        'discount_total_minor', p.discount_total_minor,
        'tax_total_minor',      p.tax_total_minor,
        'grand_total_minor',    p.grand_total_minor,
        'payment_status',       p.payment_status,
        -- ORDER-EDIT-001B (D-043 / D-044): money-free. A whole-order void
        -- supersedes every pending edit confirmation (§4.46).
        'edit_count',               p.edit_count,
        'kitchen_edit_ack_pending', (p.status <> 'voided' and p.edit_ack_pending),
        'has_active_round',         p.has_active_round
      ) || case when p.card_attempt_in_progress then jsonb_build_object('card_attempt_in_progress', true)
                else '{}'::jsonb end order by
        case when v_ascending then p.sync_at end asc,
        case when v_ascending then p.id      end asc,
        case when not v_ascending then p.sync_at end desc,
        case when not v_ascending then p.id      end desc
    ), '[]'::jsonb),
    count(*)::integer,
    -- The cursor to RESUME from is the LAST row of this page in ITS OWN direction:
    -- the greatest (sync_at, id) when ascending, the least when descending.
    (array_agg(p.sync_at order by p.sync_at desc, p.id desc))[1],
    (array_agg(p.id      order by p.sync_at desc, p.id desc))[1],
    (array_agg(p.sync_at order by p.sync_at asc,  p.id asc))[1],
    (array_agg(p.id      order by p.sync_at asc,  p.id asc))[1]
  into v_rows, v_count, v_max_at, v_max_id, v_min_at, v_min_id
  from page p;

  if v_ascending then
    v_next_at := v_max_at;  -- resume AFTER the newest row we just took
    v_next_id := v_max_id;
  else
    v_next_at := v_min_at;  -- resume BEFORE the oldest row we just took
    v_next_id := v_min_id;
  end if;

  -- A page that filled the limit MAY have more behind it; a short page is the end.
  -- A caller must NEVER read "this bounded page did not contain order X" as "order
  -- X was deleted" -- the envelope says so explicitly by never claiming completeness.
  return jsonb_build_object(
    'ok',            true,
    'entity',        'order_snapshot',
    'server_ts',     now(),
    'window_start',  v_window_start,
    'orders',        v_rows,
    'has_more',      (v_count = v_limit and p_order_ids is null),
    'next_cursor',   case
                       when v_count = v_limit and p_order_ids is null
                       then jsonb_build_object('at', v_next_at, 'id', v_next_id)
                       else null
                     end);
end;
$$;
revoke all on function app.pos_order_snapshots(uuid, uuid, timestamptz, uuid, timestamptz, uuid, uuid[], integer, integer) from public;
revoke all on function app.pos_order_snapshots(uuid, uuid, timestamptz, uuid, timestamptz, uuid, uuid[], integer, integer) from anon;
grant execute on function app.pos_order_snapshots(uuid, uuid, timestamptz, uuid, timestamptz, uuid, uuid[], integer, integer) to authenticated;

create or replace function app.audit_action_has_detail(p_action text)
  returns boolean
  language sql
  immutable
  set search_path = ''
as $$
  select coalesce(p_action, '') like 'order.void%'
      or p_action like 'order.discount%'
      or p_action like 'order.status%'
      or p_action =    'order.submitted'
      -- RESTAURANT-OPERATIONS-V1-001: table moves (order.table_moved +
      -- order.table_move_denied) carry before/after labels + denied reasons.
      or p_action like 'order.table_mov%'
      or p_action like 'staff.capabilities%'
      -- FULL-COMP-PERMISSION-001: staff.created was NOT projected, so the capabilities
      -- a cashier is PROVISIONED with were written to the append-only trail and then
      -- never shown. Granting "make orders free" invisibly is exactly what this ticket
      -- must not do, so the CREATE path is projected too.
      or p_action =    'staff.created'
      or p_action like 'membership.%'
      or p_action like 'shift.%'
      or p_action like 'cash_drawer.%'
      or p_action like 'payment.%'
      or p_action like 'settings.%'
      -- RESTAURANT-OPERATIONS-V1-001: branch availability changes/denials carry
      -- before/after availability + the item name (menu.* was previously
      -- metadata-only; ONLY the availability family gains detail).
      or p_action like 'menu.%.availability%'
      -- PILOT-OPERATIONS-CORRECTIONS-001: manual table status changes/denials
      -- (before/after floor status) and link/unlink (group label) carry detail.
      or p_action like 'table.status%'
      or p_action like 'table.tables_%'
      or p_action like 'table.link%'
      or p_action like 'table.unlink%'
      -- PSC-001C: order additions (round_number/added_item_count) and round
      -- status changes (round_number/from_status/to_status) carry safe detail.
      or p_action like 'order.items_add%'
      or p_action like 'order.round_status%'
      -- ORDER-EDIT-001A: sent-order edits and their kitchen confirmations
      -- (order.edited / order.edit_denied / order.edit_acknowledged /
      -- order.edit_ack_denied) carry safe scalars (edit number, counts,
      -- kitchen channel, reason code, denied reason, totals of order.edited).
      or p_action like 'order.edit%'
      -- KITCHEN-MODE-001B: printer configuration actions carry a safe scalar
      -- projection (display_name / role / paper_width / is_enabled /
      -- connection_type). connection_config stays a nested object, so the
      -- scalar-only allowlist can never surface host/port/addresses.
      or p_action like 'printer.%'
      -- KITCHEN-MODE-001C1: kitchen dispatch events carry safe scalars only
      -- (order_code / dispatch_type / membership) — never the payload.
      -- KITCHEN-MODE-001C3A: the same prefix covers the upcoming
      -- kitchen.dispatch_hold_resolved (001C3B) — no new pattern needed.
      or p_action like 'kitchen.%'
      -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (§4.33): the card_attempt.* family.
      or p_action like 'card_attempt.%'
      or p_action =    'pin_session.failed';
$$;
revoke all on function app.audit_action_has_detail(text) from public;
revoke all on function app.audit_action_has_detail(text) from anon;

create or replace function app.audit_safe_detail(p_action text, p_values jsonb)
  returns jsonb
  language plpgsql
  immutable
  set search_path = ''
as $$
declare
  v_out  jsonb := '{}'::jsonb;
  v_caps jsonb;
  v_key  text;
begin
  -- Unknown / unsupported action -> no payload details.
  if not app.audit_action_has_detail(p_action) then
    return '{}'::jsonb;
  end if;
  -- Malformed / missing / non-object payload -> empty safe detail (never throws).
  if p_values is null or jsonb_typeof(p_values) <> 'object' then
    return '{}'::jsonb;
  end if;
  -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (§4.33): the card_attempt.* family has
  -- its own per-action scalar allowlist (money keys only on .started) and never
  -- reaches the global list below, so no other action's projection changes.
  if p_action like 'card_attempt.%' then
    foreach v_key in array (case
      when p_action = 'card_attempt.started'
        then array['attempt_state', 'mode', 'amount_minor', 'currency_code']
      when p_action in ('card_attempt.approved', 'card_attempt.declined', 'card_attempt.unknown',
                        'card_attempt.released', 'card_attempt.provider_anomaly')
        then array['attempt_state', 'refusal_code', 'anomaly_code', 'release_requested']
      when p_action in ('card_attempt.release_requested', 'card_attempt.release_failed')
        then array['attempt_state']
      when p_action = 'card_attempt.recording_refused' then array['refusal_code']
      when p_action = 'card_attempt.order_freed' then array['attempt_state', 'confirmation_source']
      when p_action = 'card_attempt.recording_resume_requested'
        then array['attempt_state', 'prior_refusal_code', 'resume_count', 'outcome', 'denied_reason']
      when p_action = 'card_attempt.denied' then array['denied_reason']
      else array[]::text[] end)
    loop
      if p_values ? v_key and jsonb_typeof(p_values -> v_key) in ('string', 'number', 'boolean') then
        v_out := v_out || jsonb_build_object(v_key, p_values -> v_key);
      end if;
    end loop;
    return v_out;
  end if;

  -- Canonical SAFE SCALAR allowlist. A key is emitted ONLY when it is on this
  -- list AND its value is a scalar (string/number/boolean) — nested objects,
  -- arrays, and every un-listed key (secret OR merely unknown) are dropped.
  foreach v_key in array array[
    'status','order_status','scope','discount_type','value','attempted_action','order_type',
    'role','from_role','to_role','target_role',
    'discount_total_minor','grand_total_minor','subtotal_minor','line_total_minor','line_discount_minor',
    'amount_minor','tendered_minor','change_minor','opening_float_minor',
    'expected_cash_minor','counted_cash_minor','cash_variance_minor','variance_minor',
    'voided_item_count','failed_attempt_count','locked',
    'timezone','name','receipt_prefix',
    'order_code','payment_status',
    'dispatch_mode',   -- KITCHEN-PRINT-DUAL-001C: closed dispatch enum (kds|direct_print); money-free state (T-003)
    -- ORDER-AUTO-COMPLETION-001: how, and why, an order was completed. Both are
    -- STATES ('automatic'/'manual', 'order_served'/'payment_recorded'), not money
    -- and not identifiers — T-003 still holds.
    'completion_mode','completion_trigger',
    -- MONEY-SETTLEMENT-CONSISTENCY-001: WHY a mutation was denied. order.discount_denied
    -- and order.void_denied have always carried this, but it was never allowlisted — so
    -- the Activity Log showed THAT a discount was refused and never WHY. It is a closed
    -- enum of safe STATE tokens (order_has_completed_payment | full_comp_requires_manager),
    -- never money and never an identifier (T-003 holds).
    'denied_reason',
    -- FULL-COMP-PERMISSION-001: WHAT the mutation would have left the order as. A
    -- closed enum of STATE tokens ('not_chargeable') -- never money, never an
    -- identifier (T-003 holds).
    'resulting_charge_state',
    -- RESTAURANT-OPERATIONS-V1-001: branch availability (closed enums
    -- available|unavailable / sold_out|paused) + the menu item's display name,
    -- and table-move floor labels (human table names). Names/labels are tenant
    -- display text already shown on receipts/tickets — never money, never ids.
    'availability','availability_reason','item_name',
    'table_label','from_table_label','to_table_label',
    -- PILOT-OPERATIONS-CORRECTIONS-001: manual table status transition
    -- (closed enum available|reserved|occupied|out_of_service) + the combined
    -- group label (floor names). Never money, never identifiers (T-003 holds).
    'from_status','to_status','group_label',
    -- PSC-001D: void provenance + kitchen acknowledgement. voided_from_status
    -- is the closed order-status enum; device_type is the closed pos|kds enum;
    -- kitchen_ack_required is a boolean. Never money, never identifiers
    -- (T-003 holds).
    'voided_from_status','device_type','kitchen_ack_required',
    -- PSC-001C: service rounds. round_number and added_item_count are small
    -- integers (a position in the order and a line count) — never money,
    -- never identifiers (T-003 holds).
    'round_number','added_item_count',
    -- KITCHEN-MODE-001B: printer configuration scalars. display_name is tenant
    -- display text (the item_name/table_label class); the rest are closed
    -- enums/booleans. connection_config (host/port/addresses) is a NESTED
    -- OBJECT and is therefore structurally dropped by the scalar-only rule —
    -- endpoints never reach the Activity Log timeline.
    'display_name','paper_width','is_enabled','connection_type',
    -- KITCHEN-MODE-001C1: kitchen dispatch safe scalars (closed enum + the
    -- existing safe order_code class). The money_free_payload itself is
    -- NEVER projected into audit detail.
    'dispatch_type',
    -- KITCHEN-MODE-001C3A: the kitchen-mode family scalars. kitchen_workflow_mode
    -- is the closed kds|printer_only enum; kitchen_workflow_mode_revision is a
    -- small positive integer (never money, never an identifier — T-003 holds);
    -- resolution / reason_code are CLOSED safe state tokens written only by the
    -- future 001C3B owner setter + hold resolution (human-actor paths). NOTE:
    -- settings.branch.updated projects full branch-row snapshots, so the mode
    -- and revision now also surface there — both are safe display state, the
    -- timezone/name class.
    'kitchen_workflow_mode','kitchen_workflow_mode_revision','resolution','reason_code',
    -- POS-CASH-DRAWER-MANUAL-OPEN-001: a manual drawer open that reached the
    -- server LATE (made offline, journaled on the till). A boolean -- never
    -- money, never an identifier (T-003 holds).
    'recorded_offline',
    -- ORDER-EDIT-001A: sent-order edits. edit_number / up_to_edit_number are
    -- small positive integers (a position in the order's edit history) and
    -- removed_item_count / modified_item_count / acknowledged_count are line
    -- counts; kitchen_channel is the closed kds|paper enum; the two branch
    -- switches are booleans. Never money, never identifiers (T-003 holds).
    -- NOTE: settings.branch.updated projects full branch-row snapshots, so
    -- the two switches now also surface there — safe display state.
    'edit_number','up_to_edit_number','removed_item_count','modified_item_count',
    'acknowledged_count','kitchen_channel',
    'order_edit_enabled','order_edit_finished_food_manager_only'
  ] loop
    -- PSC-001C correction (Finding 6): the four service-round actions are
    -- MONEY-FREE by approved contract — any *_minor key (hostile, manual, or
    -- accidental) is dropped for EXACTLY these actions, action-specifically:
    -- the approved money-carrying actions (payments / discounts / shifts /
    -- order.submitted / completion) keep their allowlisted money keys.
    if (p_action like 'order.items_add%' or p_action like 'order.round_status%'
        -- KITCHEN-MODE-001B: printer configuration is MONEY-FREE by contract —
        -- the same hostile-key hardening applies to the whole printer family.
        or p_action like 'printer.%'
        -- KITCHEN-MODE-001C1: kitchen dispatch events are MONEY-FREE too.
        or p_action like 'kitchen.%')
       and v_key like '%\_minor' escape '\' then
      continue;
    end if;
    if p_values ? v_key
       and jsonb_typeof(p_values -> v_key) in ('string','number','boolean') then
      v_out := v_out || jsonb_build_object(v_key, p_values -> v_key);
    end if;
  end loop;

  -- The ONLY allowlisted nested object: `capabilities`, kept to its four
  -- canonical boolean capability keys (unknown nested keys dropped).
  if jsonb_typeof(p_values -> 'capabilities') = 'object' then
    select coalesce(jsonb_object_agg(k, p_values -> 'capabilities' -> k), '{}'::jsonb)
      into v_caps
      from unnest(array['apply_discount','void_order','close_shift','apply_full_comp','manage_menu_availability','manage_table_operations','open_cash_drawer']) as k
      where (p_values -> 'capabilities') ? k
        and jsonb_typeof(p_values -> 'capabilities' -> k) in ('string','number','boolean');
    if v_caps is distinct from '{}'::jsonb then
      v_out := v_out || jsonb_build_object('capabilities', v_caps);
    end if;
  end if;

  return v_out;
end;
$$;
revoke all on function app.audit_safe_detail(text, jsonb) from public;
revoke all on function app.audit_safe_detail(text, jsonb) from anon;

create or replace function app.owner_audit_events(
  p_organization_id           uuid,
  p_restaurant_id             uuid    default null,
  p_branch_id                 uuid    default null,
  p_range                     text    default 'today',
  p_category                  text    default null,
  p_action                    text    default null,
  p_sensitive_only            boolean default false,
  p_actor_app_user_id         uuid    default null,
  p_actor_employee_profile_id uuid    default null,
  p_limit                     int     default 25,
  p_cursor                    text    default null
)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = ''
as $$
declare
  v_actor      uuid    := app.current_app_user_id();
  v_rank       integer;
  v_currency   text;
  v_zone       text;
  v_span       integer;
  v_end_offset integer;
  v_limit      integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_cursor_ts  timestamptz;
  v_cursor_id  uuid;
  v_result     jsonb;
begin
  if v_actor is null then
    raise exception 'owner_audit_events: authentication required' using errcode = '42501';
  end if;
  if p_organization_id is null then
    raise exception 'owner_audit_events: organization_id is required' using errcode = '42501';
  end if;

  case p_range
    when 'today'     then v_span := 1;  v_end_offset := 0;
    when 'yesterday' then v_span := 1;  v_end_offset := 1;
    when 'last7'     then v_span := 7;  v_end_offset := 0;
    when 'last30'    then v_span := 30; v_end_offset := 0;
    else raise exception 'owner_audit_events: unknown range %', p_range using errcode = '22023';
  end case;

  -- 'settings' is now a first-class filter category (AUDIT-COVERAGE-002).
  if p_category is not null and p_category not in (
    'orders','voids','discounts','payments','shifts','staff',
    'access','devices','settings','menu','tables','organization','sync'
  ) then
    raise exception 'owner_audit_events: unknown category %', p_category using errcode = '22023';
  end if;

  v_rank := app.actor_rank_in_scope(p_organization_id, p_restaurant_id, p_branch_id);
  if v_rank = 0 then
    raise exception 'owner_audit_events: caller has no active membership covering the requested scope' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.memberships m
    where m.app_user_id     = v_actor
      and m.organization_id = p_organization_id
      and m.status          = 'active'
      and m.deleted_at is null
      and m.role in ('manager', 'restaurant_owner', 'org_owner')
      and (m.restaurant_id is null or m.restaurant_id = p_restaurant_id)
      and (m.branch_id     is null or m.branch_id     = p_branch_id)
  ) then
    return jsonb_build_object('ok', false, 'error', 'permission_denied', 'entity', 'owner_audit_events');
  end if;

  select o.default_currency into v_currency
    from public.organizations o
    where o.id = p_organization_id and o.deleted_at is null;
  if not found then
    raise exception 'owner_audit_events: organization not found (or deleted)' using errcode = '42501';
  end if;

  v_zone := coalesce(
    (select b.timezone from public.branches b
       where b.organization_id = p_organization_id and b.id = p_branch_id and b.deleted_at is null),
    (select r.timezone from public.restaurants r
       where r.organization_id = p_organization_id and r.id = p_restaurant_id and r.deleted_at is null),
    (select min(r2.timezone) from public.restaurants r2
       where r2.organization_id = p_organization_id and r2.deleted_at is null and r2.timezone is not null),
    'UTC'
  );

  if p_cursor is not null and btrim(p_cursor) <> '' then
    begin
      v_cursor_ts := split_part(p_cursor, '|', 1)::timestamptz;
      v_cursor_id := split_part(p_cursor, '|', 2)::uuid;
    exception when others then
      raise exception 'owner_audit_events: invalid cursor' using errcode = '22023';
    end;
  end if;

  with matched as (
    select ae.id,
           ae.action,
           ae.occurred_at,
           ae.reason,
           ae.restaurant_id,
           ae.branch_id,
           ae.actor_app_user_id,
           ae.actor_employee_profile_id,
           ae.device_id,
           cat.category,
           ez.zone as event_zone,
           coalesce(ep_actor.display_name, ep_appuser.display_name) as actor_name,
           r.name  as restaurant_name,
           b.name  as branch_name,
           dev.label as device_label,
           app.audit_safe_detail(ae.action, ae.old_values) as old_values_safe,
           app.audit_safe_detail(ae.action, ae.new_values) as new_values_safe
    from public.audit_events ae
    -- Single source of truth for classification (AUDIT-COVERAGE-002).
    cross join lateral (select app.audit_category(ae.action) as category) cat
    left join public.employee_profiles ep_actor
      on ep_actor.organization_id = ae.organization_id
     and ep_actor.id             = ae.actor_employee_profile_id
    left join lateral (
      select ep.display_name
      from public.employee_profiles ep
      where ep.organization_id = ae.organization_id
        and ae.actor_employee_profile_id is null
        and ae.actor_app_user_id is not null
        and ep.app_user_id = ae.actor_app_user_id
        and ep.deleted_at is null
      order by ep.created_at, ep.id
      limit 1
    ) ep_appuser on true
    left join public.restaurants r
      on r.organization_id = ae.organization_id and r.id = ae.restaurant_id and r.deleted_at is null
    left join public.branches b
      on b.organization_id = ae.organization_id and b.id = ae.branch_id and b.deleted_at is null
    left join public.devices dev
      on dev.organization_id = ae.organization_id and dev.id = ae.device_id and dev.deleted_at is null
    cross join lateral (
      select coalesce(b.timezone, r.timezone, v_zone) as zone
    ) ez
    where ae.organization_id = p_organization_id
      and (p_restaurant_id is null or ae.restaurant_id = p_restaurant_id)
      and (p_branch_id     is null or ae.branch_id     = p_branch_id)
      and (ae.occurred_at at time zone ez.zone)::date
          between ((now() at time zone ez.zone)::date - v_end_offset - (v_span - 1))
              and ((now() at time zone ez.zone)::date - v_end_offset)
      and (p_category is null or cat.category = p_category)
      and (p_action   is null or ae.action    = p_action)
      and (p_actor_app_user_id is null or ae.actor_app_user_id = p_actor_app_user_id)
      and (p_actor_employee_profile_id is null or ae.actor_employee_profile_id = p_actor_employee_profile_id)
      and (
        not p_sensitive_only
        or ae.action like '%denied'
        or ae.action like 'order.void%'
        or ae.action like 'order.discount%'
        -- ORDER-EDIT-001A: an applied sent-order edit can remove or void
        -- kitchen food on an unpaid order (TH-7) — sensitive like a void.
        or ae.action =    'order.edited'
        or ae.action like 'staff.capabilities%'
        or ae.action =    'staff.pin_set'
        or ae.action like 'membership.%'
        or ae.action like 'employee.revok%'
        or ae.action like 'device.revok%'
        or ae.action like 'shift.%'
        or ae.action like 'cash_drawer.%'
        or ae.action like 'payment.%'
        -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (§4.33): the sensitive card actions
        -- (card_attempt.denied already matches %denied).
        or ae.action in ('card_attempt.provider_anomaly', 'card_attempt.recording_refused',
                         'card_attempt.order_freed', 'card_attempt.recording_resume_requested')
      )
      and (
        p_cursor is null
        or v_cursor_ts is null
        or ae.occurred_at < v_cursor_ts
        or (ae.occurred_at = v_cursor_ts and ae.id < v_cursor_id)
      )
  ),
  page as (
    select m.*, m.occurred_at::text || '|' || m.id::text as cursor
    from matched m
    order by m.occurred_at desc, m.id desc
    limit v_limit + 1
  ),
  numbered as (
    select p.*, row_number() over (order by p.occurred_at desc, p.id desc) as rn
    from page p
  )
  select jsonb_build_object(
    'events', coalesce((
      select jsonb_agg(jsonb_build_object(
               'event_id',        n.id,
               'action',          n.action,
               'category',        n.category,
               'occurred_at',     to_char(n.occurred_at at time zone n.event_zone, 'YYYY-MM-DD HH24:MI'),
               'timezone',        n.event_zone,
               'actor_name',      n.actor_name,
               'restaurant_id',   n.restaurant_id,
               'restaurant_name', n.restaurant_name,
               'branch_id',       n.branch_id,
               'branch_name',     n.branch_name,
               'device_label',    n.device_label,
               'reason',          n.reason,
               'old_values',      n.old_values_safe,
               'new_values',      n.new_values_safe)
             order by n.rn)
      from numbered n
      where n.rn <= v_limit), '[]'::jsonb),
    'has_more',    (select count(*) from numbered) > v_limit,
    'next_cursor', case when (select count(*) from numbered) > v_limit
                        then (select cursor from numbered where rn = v_limit)
                        else null end,
    'count',       least((select count(*) from numbered), v_limit)
  ) into v_result;

  return jsonb_build_object(
    'ok', true,
    'entity', 'owner_audit_events',
    'currency_code', v_currency,
    'range', p_range,
    'limit', v_limit
  ) || v_result;
end;
$$;
revoke all on function app.owner_audit_events(uuid, uuid, uuid, text, text, text, boolean, uuid, uuid, int, text) from public;
revoke all on function app.owner_audit_events(uuid, uuid, uuid, text, text, text, boolean, uuid, uuid, int, text) from anon;
grant execute on function app.owner_audit_events(uuid, uuid, uuid, text, text, text, boolean, uuid, uuid, int, text) to authenticated;

create or replace function app.audit_category(p_action text)
  returns text
  language sql
  immutable
  set search_path = ''
as $$
  select case
    when p_action like 'order.discount%'                               then 'discounts'
    when p_action like 'order.void%'                                   then 'voids'
    when p_action like 'order.%'                                       then 'orders'
    when p_action like 'payment.%' or p_action like 'receipt_number.%' then 'payments'
    when p_action like 'shift.%'   or p_action like 'cash_drawer.%'    then 'shifts'
    when p_action like 'staff.%'                                       then 'staff'
    when p_action like 'membership.%' or p_action like 'employee.%'
         or p_action like 'pin_session.%'                             then 'access'
    when p_action like 'device.%'                                     then 'devices'
    when p_action like 'settings.%'                                   then 'settings'
    -- KITCHEN-MODE-001B: printer configuration IS settings work.
    when p_action like 'printer.%'                                    then 'settings'
    -- KITCHEN-MODE-001C1: kitchen dispatch events are ORDER work.
    when p_action like 'kitchen.%'                                    then 'orders'
    when p_action like 'menu.%'                                       then 'menu'
    when p_action like 'table.%'                                      then 'tables'
    when p_action like 'organization.%'                               then 'organization'
    when p_action like 'sync.%'                                       then 'sync'
    -- BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (§4.33): provider attempts are PAYMENTS work.
    when p_action like 'card_attempt.%'                               then 'payments'
    else 'other'
  end;
$$;
revoke all on function app.audit_category(text) from public;

do $do$
begin
  execute format('comment on function app.pin_session_capabilities(uuid, uuid) is %L',
    obj_description('app.pin_session_capabilities(uuid, uuid)'::regprocedure, 'pg_proc')
    || ' BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D: + branch_features.card_terminal_enabled / card_terminal_mode, present only while the exact device has a configured, enabled or draining card-terminal binding (absent => hidden).');
  execute format('comment on function app.pos_order_snapshots(uuid, uuid, timestamptz, uuid, timestamptz, uuid, uuid[], integer, integer) is %L',
    obj_description('app.pos_order_snapshots(uuid, uuid, timestamptz, uuid, timestamptz, uuid, uuid[], integer, integer)'::regprocedure, 'pg_proc')
    || ' BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D: + card_attempt_in_progress (true, present only while the order has an active card-attempt claim; a UX gate, the sync_push guard is the authority) and the newest claim signal of its same-branch LIVE attempts in sync_at (D-059).');
end;
$do$;


-- ----------------------------------------------------------------------------
-- 10. Grants (the D-035 / D-036 pairing; D-037 for anon). Every new function is
--     first revoked from PUBLIC and every app role (the hosted default ACL
--     stamps authenticated and service_role on new public functions), then
--     granted to exactly one role on both layers where a grant exists.
-- ----------------------------------------------------------------------------
-- Internal helpers, triggers, lock helpers, internal guards, operator RPCs: no grant.
