  app.card_caller_binding_denial(uuid),
  app.card_attempt_proof(uuid, uuid, text, boolean),
  app.card_attempt_payment_id(app.card_provider_attempts),
  app.card_attempt_derive(app.card_provider_attempts),
  app.card_attempt_envelope(app.card_provider_attempts),
  app.card_order_claim_active(uuid, uuid),
