  app.card_proof_denial_evidence(jsonb, uuid, text, text),
  app.card_config_mismatch(text, uuid, text, text, text, jsonb, jsonb),
  app.card_terminal_posture(uuid, uuid, uuid),
  app.card_append_only_guard(),
  app.payment_terminals_guard(),
  app.card_attempts_insert_guard(),
  app.card_attempts_guard(),
  app.card_events_guard(),
  app.card_claim_guard(uuid, uuid, uuid, text, text, text, uuid),
  app.card_recording_resume_guard(uuid, uuid, uuid, integer, text, uuid, timestamptz, jsonb),
  app.set_card_payments_pilot(boolean, text, timestamptz, bigint, bigint, text, text, uuid),
  app.set_payment_terminal(uuid, text, text, text, text, text, text, text, uuid),
