  app.purge_expired_test_card_attempts(text, text, uuid, integer)
from public, anon, authenticated, service_role;

-- The caller-authority pair: authenticated on both layers (the SQL proof is the gate).
revoke all on function
  app.card_attempt_context(uuid, uuid, text, uuid, text),
  public.card_attempt_context(uuid, uuid, text, uuid, text),
  app.owner_card_attempts(uuid, uuid, uuid, timestamptz, timestamptz, text),
  public.owner_card_attempts(uuid, uuid, uuid, timestamptz, timestamptz, text)
from public, anon, authenticated, service_role;
