comment on table app.card_payments_pilot_revisions is
  'BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (DOMAIN_MODEL §8.7): append-only operator revision store behind app.set_card_payments_pilot; the latest row is current; no row = OFF. Pinned to the pilot scope. Private: forced RLS, no app-role grant.';
comment on table app.payment_terminals is
  'BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (DOMAIN_MODEL §8.5): exact-device card-terminal binding (opaque terminal_ref / credential_ref only; no credential or PIN-pad identifier). Written only by app.set_payment_terminal. Private.';
comment on table app.card_provider_attempts is
  'BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (DOMAIN_MODEL §8.4): the private card-present provider-attempt ledger (identity, frozen claim context, full-identity digests and outbound keys, sanitized provider facts). No card number, provider free text or raw payload. Written only by the §4.55 SECURITY DEFINER bodies.';
comment on table app.card_provider_private_events is
  'BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (DOMAIN_MODEL §8.6): private operator / TEST-denial / security evidence; never a tenant Activity-log row. Facts immutable; only the hold metadata of a mode=test event may change.';
comment on table app.card_attempt_identity_tombstones is
  'BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (D-058 point 7): append-only identities, digests and outbound keys of purged TEST attempts, so a purged identity is never reused or recorded.';
comment on function app.card_safe_text_ok(text, text) is
  'BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (D-058 point 10; packet §4.5): the field-specific no-card-data rule over the raw and the NFKC-canonical value (closed Unicode 15.1.0 category policy; 12+ Nd digit runs; masked card patterns). IMMUTABLE, SECURITY INVOKER, reads no table.';
comment on function app.card_caller_binding_denial(uuid) is
  'BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (D-060 point 2): the original-caller check of the five session-proving service-only operations - NULL for a valid auth.users caller outside an ACTIVE platform support session, else invalid_request / invalid_session / permission_denied. Reads only the explicit identity; internal, no client role.';
comment on function app.card_claim_guard(uuid, uuid, uuid, text, text, text, uuid) is
  'BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (API §4.55.3): the app.sync_push claim guard of the payment.create, order.discount, order.edit, order.items_add, order.void and shift.close arms. Internal; no client role.';
comment on function app.card_recording_resume_guard(uuid, uuid, uuid, integer, text, uuid, timestamptz, jsonb) is
  'BIZBOT-PAYMENTS-ZCREDIT-PILOT-001D (API §4.55.7; D-054 / D-057 point 3 / D-058 point 11): the explicit manager Resume recording guard; the only writer of recording_resume_count and the Resume histories. Internal; no client role.';
